	["A un clic"] = "En un clic",
	["A veces"] = "Parfois",
	["A veces el golpe ni te toca."] = "Parfois, le coup ne vous touche même pas.",
	["A veces el juego tarda o no deja mover a nadie más a esa capa. Puedes salir del grupo y probar con otra."] = "Parfois le jeu met du temps ou ne laisse plus personne passer sur cette couche. Tu peux quitter le groupe et en essayer une autre.",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "Parfois, tu pêches des caisses et des bouteilles avec des messages qui commencent une quête.",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "Parfois, des gemmes sortent en minant : garde-les, plusieurs métiers les utilisent dans leurs recettes.",
	["Abajo"] = "Le bas",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "Sous le modèle, choisis ce que fait ton personnage (marcher, danser, saluer...) et mets-le en pause.",
	["Abajo y al centro del ícono, con letra que crece con él. Apagada, chiquita en la esquina."] = "En bas au centre de l'icône, avec un texte qui grandit avec elle. Désactivé : petit dans le coin.",
	["Abalorio"] = "Bijou",
	["Abalorios"] = "Bijoux",
