	["Acepta invitaciones de grupo de tus amigos y de tu hermandad."] = "Accepte les invitations de groupe de tes amis et de ta guilde.",
	["Acepta por ti"] = "Accepte pour toi",
	["Acepta su invitación al grupo. Al llegar a su guarida, Alfa te avisa para salir del grupo."] = "Accepte son invitation de groupe. Une fois dans sa tanière, Alfa te prévient pour quitter le groupe.",
	["Acepta una invocación al momento, salvo en combate."] = "Accepte une invocation aussitôt, sauf en combat.",
	["Acepta una resurrección en cuanto se puede. Nunca en Hardcore."] = "Accepte une résurrection dès que possible. Jamais en Hardcore.",
	["Acepta y entrega las demás (normales, diarias y semanales). Nunca las grises ni las que piden oro o materiales."] = "Accepte et rend les autres (normales, journalières et hebdomadaires). Jamais les grises ni celles qui demandent de l'or ou des matériaux.",
	["Acepta y entrega tus misiones, elige tu guía y sigue sola, vende, repara y toma tus vuelos. Tú solo juegas."] = "Accepte et rend tes quêtes, choisit ton guide et continue seul, vend, répare et prend tes vols. Toi, tu joues.",
	["Aceptar"] = "OK",
	["Aceptar invocaciones"] = "Accepter les invocations",
	["Aceptar las misiones de tu guía"] = "Accepter les quêtes de ton guide",
	["Aceptar resurrecciones"] = "Accepter les résurrections",
	["Aceptar solas las misiones de la guía"] = "Accepter automatiquement les quêtes du guide",
	["Aceptar todas las misiones ya no pierde una diaria porque la ventana se cerraba antes de tiempo."] = "Accepter toutes les quêtes ne manque plus une journalière parce que la fenêtre se fermait trop tôt.",
	["Aceptar y entregar"] = "Accepter et rendre",
