	["Actitud rabiosa"] = "Posture berserker",
	["Activa el rastreo de hierbas para verlas en el minimapa mientras viajas."] = "Active la Découverte d'herbes pour les voir sur la minicarte en voyageant.",
	["Activa el rastreo de minerales y sigue las montañas: ahí están las mejores vetas."] = "Active la Découverte de gisements et suis les montagnes : c'est là que sont les meilleurs filons.",
	["Activa máquinas en las paredes que sueltan bombas que caminan: pulsa el botón junto a la máquina para apagarla, o maten las bombas antes de que lleguen."] = "Il active des machines murales qui libèrent des bombes ambulantes : appuyez sur le bouton à côté d'une machine pour l'arrêter, ou tuez les bombes avant qu'elles n'arrivent.",
	["Activar el medidor de daño"] = "Activer le compteur de dégâts",
	["Activar el modo limpio"] = "Activer le mode épuré",
