	["Activo"] = "Actif",
	["Actual"] = "Actuel",
	["Actualizar mi guía"] = "Mettre à jour mon guide",
	["Actualizar mis barras"] = "Mettre à jour mes barres",
	["Actualízala con la app de CurseForge o con el zip más reciente y luego usa /reload."] = "Mettez-le à jour avec l'application CurseForge ou le zip le plus récent, puis tapez /reload.",
	["Actualízalo con la app de CurseForge o con el zip más reciente y luego reinicia el juego o usa /reload."] = "Mettez-le à jour avec l'application CurseForge ou le zip le plus récent, puis relancez le jeu ou faites /reload.",
	["Acércate para usar %s"] = "Rapproche-toi pour utiliser %s",
	["Además del ícono, un brillo dorado que late alrededor de su barra."] = "En plus de l'icône, un halo doré qui pulse autour de leur barre.",
	["Adopta a un lobo 10 niveles menor que tú. Si acepta, ves su nivel, su zona y su misión (solo tú) y te aviso si se atora."] = "Adopte un loup de 10 niveaux de moins que toi. S'il accepte, tu vois son niveau, sa zone et sa quête (toi seul) et je te préviens s'il est bloqué.",
	["Adopta a un lobo nuevo o deja que uno con más nivel te adopte. Lo que comparten queda entre los dos."] = "Adopte un nouveau loup ou laisse-toi adopter par un plus haut niveau. Ce que vous partagez reste entre vous deux.",
	["Adoptar"] = "Adopter",
	["Afinar cosa por cosa"] = "Régler un par un",
	["Afinar siempre"] = "Toujours affiner",
	["Aflicción"] = "Affliction",
	["Aflicción para subir"] = "Affliction pour monter",
	["Agarras a varios enemigos a la vez."] = "Vous retenez plusieurs ennemis à la fois.",
	["Agilidad"] = "Agilité",
	["Agrega la primera: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota."] = "Ajoutez le premier : un objet, de l'or, un métier, un lieu, une quête, un niveau ou une note.",
	["Agrega tramos arriba: Alfa elige las misiones por ti."] = "Ajoutez des tronçons ci-dessus : Alfa choisit les quêtes pour vous.",
	["Agrega una línea con el objetivo de esa unidad; si te tiene a ti, lo dice."] = "Ajoute une ligne avec la cible de cette unité ; si c'est toi, il le dit.",
