	["Anisotrópico 8x"] = "Anisotrope 8x",
	["Ankh"] = "Ankh",
	["Anterior"] = "Précédent",
	["Antes de %s te falta:"] = "Avant %s, il te manque :",
	["Antes de abandonarla"] = "Avant de l'abandonner",
	["Antes de atacar, mira quién está cerca. Pelear con uno a la vez es más seguro."] = "Avant d'attaquer, regarde qui est à proximité. Combattre un ennemi à la fois est plus sûr.",
	["Antes de buscar la espada, Arthas mandó quemar sus propios barcos para que sus soldados no pudieran volver a casa."] = "Avant de chercher l'épée, Arthas a fait brûler ses propres navires pour que ses soldats ne puissent pas rentrer chez eux.",
	["Antes de comprar algo en la subasta, revisa si un vendedor lo tiene más barato."] = "Avant d'acheter quelque chose à l'hôtel des ventes, vérifie si un vendeur le propose moins cher.",
	["Antes de empezar, unas palabras de la manada."] = "Avant de commencer, quelques mots de la meute.",
	["Antes de entrar"] = "Avant d'entrer",
	["Antes de entregarla te falta: %s."] = "Avant de la rendre, il vous manque : %s.",
	["Antes de importar"] = "Avant d'importer",
	["Antes de irte: tienes %d misiones listas para entregar. ¿Pasamos a cobrarlas?"] = "Avant de partir : tu as %d quêtes prêtes à rendre. On passe récupérer les récompenses ?",
	["Antes de irte: tienes una misión lista para entregar. ¿Pasamos a cobrarla?"] = "Avant de partir : tu as une quête prête à rendre. On passe récupérer la récompense ?",
	["Antes de la mazmorra te falta:"] = "Avant le donjon, il te manque :",
	["Antes de pelear"] = "Avant le combat",
	["Antes de pelear: abre con Piroexplosión, tu hechizo más fuerte."] = "Avant le combat : ouvrez avec Explosion pyrotechnique, votre sort le plus puissant.",
	["Antes de restaurar"] = "Avant de restaurer",
	["Antes de salir de caza, configura Alfa a tu medida: el idioma, cómo se ve, qué hace sola por ti y si quieres que la manada te vea en el mapa del juego."] = "Avant de partir chasser, configure Alfa à ton goût : la langue, son apparence, ce qu'il fait seul pour toi et si la meute peut te voir sur la carte du jeu.",
	["Antes de una misión de élite o de grupo, un aviso con «Llamar a la manada»."] = "Avant une quête élite ou de groupe, un avis avec « Appeler la meute ».",
	["Antes esto era un pantano. La magia del portal y la guerra lo dejaron rojo, seco y sin vida."] = "Avant, c'était un marais. La magie de la Porte et la guerre l'ont laissé rouge, sec et sans vie.",
	["Antes hay que hacer otra misión"] = "Une autre quête doit être faite avant",
	["Antes necesitas"] = "Il faut d'abord",
	["Antes necesitas otra misión"] = "Il faut d'abord une autre quête",
	["Antes pide %s (%s)"] = "Requiert d'abord %s (%s)",
	["Antes que los elfos, los trols tuvieron grandes imperios en Azeroth, como el Amani en el norte y el Gurubashi en el sur."] = "Avant les elfes, les trolls ont eu de grands empires en Azeroth, comme celui des Amani au nord et celui des Gurubashi au sud.",
	["Antes, el reino de Ventormenta se llamaba Azeroth, igual que el mundo; Ventormenta era solo el nombre de su capital."] = "Autrefois, le royaume de Hurlevent s'appelait Azeroth, comme le monde ; Hurlevent n'était que le nom de sa capitale.",
	["Antes: %s"] = "D'abord : %s",
	["Antes: %s."] = "D'abord : %s.",
	["Antes: %s. Ahora: %s."] = "Avant : %s. Maintenant : %s.",
	["Anunciar"] = "Annoncer",
	["Anunciar en el chat"] = "Annoncer dans la discussion",
	["Anunciar en el grupo"] = "Annoncer au groupe",
	["Anuncios animados"] = "Annonces animées",
	["Anuncios animados y la manada a la vista"] = "Annonces animées et la meute en vue",
	["Apaga la viñeta, el grano, las barras y el tinte de un clic."] = "Désactive le vignettage, le grain, les bandes et la teinte en un clic.",
	["Apagada"] = "Désactivée",
	["Apagadas"] = "Désactivés",
	["Apagado"] = "Désactivé",
	["Apagado en los ajustes de abajo."] = "Désactivé dans les réglages plus bas.",
	["Apagado, el grano se queda quieto."] = "Désactivé, le grain reste immobile.",
	["Apagado, solo las acepta y la entrega la haces tú."] = "Désactivé : il les accepte seulement, c'est toi qui les rends.",
	["Apagados"] = "Désactivés",
	["Apagar la parte de Alfa que choca"] = "Désactiver la partie d'Alfa en conflit",
	["Apagarlo"] = "Le désactiver",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "Il apparaît à la fin de l'événement du Disciple de Naralex : protégez le druide pendant qu'il marche.",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "Il apparaît au troisième coup de gong, après deux vagues d'araignées.",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "Il apparaît avec une quête de la Horde (un objet dans l'eau). Il lance des sorts de givre.",
	["Aparece en cuanto termines la bienvenida de Alfa."] = "Elle apparaît dès que tu termines l'accueil d'Alfa.",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "Il apparaît pendant l'événement de l'experte en explosifs : protégez-la pendant que des vagues de troggs arrivent.",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "Des cadres d'exemple apparaissent : faites-les glisser où vous voulez et ajustez leur taille. Voilà à quoi ressemblera votre groupe.",
	["Aplaudir"] = "Applaudir",
	["Aplica la nitidez de abajo aunque no uses el escalado de resolución."] = "Applique la netteté ci-dessous même sans mise à l'échelle de la résolution.",
	["Aplicar"] = "Appliquer",
	["Aplicar %d puntos"] = "Appliquer %d points",
	["Aprende %s"] = "Apprends %s",
	["Aprende Cocina con un instructor."] = "Apprenez la Cuisine auprès d'un maître.",
	["Aprende Cocina para encender fogatas."] = "Apprenez la Cuisine pour allumer des feux de camp.",
	["Aprende Minería o Herboristería"] = "Apprenez le Minage ou l'Herboristerie",
	["Aprende Pesca"] = "Apprenez la Pêche",
	["Aprende Pesca con un instructor"] = "Apprenez la Pêche auprès d'un maître",
	["Aprende Pesca con un instructor de pesca y compra una caña: la guía te lleva."] = "Apprenez la Pêche auprès d'un maître de pêche et achetez une canne : le guide vous y mène.",
	["Aprende Pesca con un instructor, compra una caña y pesca en tu zona de inicio o en la capital. Pide el rango Oficial desde 50."] = "Apprenez la Pêche auprès d'un maître, achetez une canne et pêchez dans votre zone de départ ou dans la capitale. Demandez le rang Compagnon dès 50.",
	["Aprende equitación con %s"] = "Apprenez la monte auprès de %s",
	["Aprende las dos, consigue una caña y cocina lo que pescas hasta 75."] = "Apprenez les deux, procurez-vous une canne et cuisinez ce que vous pêchez jusqu'à 75.",
	["Aprender %s"] = "Apprendre %s",
	["Aprender de tus búsquedas"] = "Apprendre de vos recherches",
	["Aprender una profesión o llegar a un nivel en ella."] = "Apprendre un métier ou y atteindre un niveau.",
	["Aprendiste %s. %s"] = "Tu as appris %s. %s",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "Vous avez appris un sort qui convient mieux à vos clics :",
	["Aprendiz"] = "Apprenti",
	["Aprendí un hechizo nuevo, ¿para qué sirve?"] = "J'ai appris un nouveau sort : à quoi sert-il ?",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "Apprenez-les auprès du maître de votre classe, dans n'importe quelle capitale.",
	["Apunto el primer día que te vi. Cada año, ese día, lo festejamos juntos. Y el 16 de noviembre es el cumpleaños de Alfa."] = "Je note le premier jour où je t'ai vu. Chaque année, ce jour-là, on fait la fête ensemble. Et le 16 novembre, c'est l'anniversaire d'Alfa.",
	["Apágalo si no quieres que Alfa toque tus teclas, tu equipo ni tus ajustes al pescar."] = "Désactivez-le si vous ne voulez pas qu'Alfa touche à vos touches, à votre équipement ni à vos réglages pendant la pêche.",
	["Aquí"] = "Ici",
	["Aquí adentro se caza en equipo: espera a que quien cura tenga maná antes de seguir."] = "Ici, on chasse en équipe : attends que ton soigneur ait du mana avant de continuer.",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Les autres modules d'Alfa (sacs, itinéraires, monde et plus) apparaîtront ici dès qu'ils seront installés.",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "Ici, le jeu ne donne pas votre position (par exemple, dans un donjon).",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "Le jeu ne permet de rien partager ici. À la sortie, votre piste repart toute seule.",
	["Aquí empieza tu historia. Y yo voy contigo."] = "Ici commence ton histoire. Et je viens avec toi.",
	["Aquí estoy, como siempre. Nunca dejo a nadie atrás."] = "Me voici, comme toujours. Je n'abandonne jamais personne.",
	["Aquí estoy. Si no sabes por dónde empezar, toca «¿Por dónde empiezo?»."] = "Je suis là. Si tu ne sais pas par où commencer, touche « Par où je commence ? ».",
	["Aquí está el Portal Oscuro: por él cruzó la Horda desde Draenor para invadir Azeroth en la Primera Guerra."] = "Ici se dresse la Porte des Ténèbres : c'est par elle que la Horde est venue de Draenor envahir Azeroth lors de la Première Guerre.",
	["Aquí está la tumba de Uther el Iluminado, el maestro de Arthas. Murió a manos de su propio alumno, defendiendo las cenizas del rey Terenas."] = "Ici repose Uther le Porteur de Lumière, le mentor d'Arthas. Il est mort de la main de son propre élève en défendant les cendres du roi Terenas.",
	["Aquí juntas XP descansada poco a poco (más si cierras sesión aquí): luego ganas el doble por enemigo hasta gastarla."] = "Ici, tu accumules peu à peu de l'XP de repos (plus si tu te déconnectes ici) : ensuite tu gagnes le double par ennemi jusqu'à l'épuiser.",
	["Aquí la lees completa: cómo empieza, qué te piden y cómo termina."] = "Lis-la en entier ici : comment elle commence, ce qu'on te demande et comment elle se termine.",
	["Aquí no hay nodos que recolectar"] = "Rien à récolter ici",
	["Aquí sale por qué se activó la habilidad."] = "Ici s'affiche pourquoi la technique s'est activée.",
	["Aquí verás cuánto llevas descubierto de cada zona de tu continente."] = "Ici, tu verras ce que tu as découvert de chaque zone de ton continent.",
	["Aquí ves cuántas llevas, dónde sale y qué hacer con ella."] = "Ici, vous voyez combien vous en avez, d'où elle vient et quoi en faire.",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "Ici, tout ce qu'il faut savoir, et quoi faire ensuite.",
	["Aquí: %s %.1f, %.1f. Se guarda este punto."] = "Ici : %s %.1f, %.1f. Ce point est enregistré.",
	["Arañazo: sangrado con el tiempo."] = "Griffure : saignement sur la durée.",
	["Arcano"] = "Arcanes",
	["Arcano para subir"] = "Arcanes pour monter",
	["Archimonde subió a Hyjal para robar la energía del Árbol del Mundo; en vez de eso, el árbol fue su final."] = "Archimonde est monté sur Hyjal pour voler l'énergie de l'Arbre-Monde ; au lieu de ça, l'arbre a causé sa fin.",
	["Arco"] = "Arc",
	["Arcos, ballestas y armas de fuego"] = "Arcs, arbalètes et armes à feu",
	["Arena"] = "Sable",
	["Arma"] = "Arme",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "Prépare avec votre itinéraire ce qu'il faut pour pouvoir la prendre : le niveau ou les quêtes précédentes.",
	["Arma de asta"] = "Arme d'hast",
	["Arma de dos manos"] = "Arme à deux mains",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "Arme à deux mains, sceaux et jugements : le paladin qui monte le mieux en solo.",
	["Arma de fuego"] = "Arme à feu",
	["Arma de puño"] = "Arme de pugilat",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "Prépare le plan pour terminer les quêtes de ton journal et te mène à chacune.",
	["Arma tu grupo de 5 (buscador de grupos o tu manada)."] = "Formez votre groupe de 5 (recherche de groupe ou votre meute).",
	["Arma tu primer plan"] = "Créez votre premier plan",
	["Arma una ruta de %s en %s"] = "Créer un itinéraire de %s dans %s",
	["Arma y escudo"] = "Arme et bouclier",
	["Armadura"] = "Armure",
	["Armaduras"] = "Armures",
	["Armando"] = "Création",
	["Armando el circuito de la zona..."] = "Préparation du circuit de la zone...",
	["Armando «Cerrar mis misiones»..."] = "Création de « Terminer mes quêtes »...",
	["Armar el grupo"] = "Former le groupe",
	["Armar la ruta"] = "Créer l'itinéraire",
	["Armar lo que falta"] = "Créer ce qui manque",
	["Armar mi plan"] = "Créer mon plan",
	["Armar un plan nuevo"] = "Créer un nouveau plan",
	["Armas"] = "Armes",
	["Armas a dos manos"] = "Armes, deux mains",
	["Armas a muerte"] = "Armes à fond",
	["Armas contra jugadores"] = "Armes JcJ",
	["Armas para grupo"] = "Armes en groupe",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "Armes pensé pour les donjons : beaucoup de dégâts sur plusieurs ennemis avec Attaques circulaires, Frappe mortelle pour les boss et plus de toucher pour ne pas rater.",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "Armes qui pense d'abord à ne pas mourir : vous parez plus de coups, ralentissez ceux qui fuient et finissez avec un peu de Protection pour subir moins de dégâts.",
	["Armas seguro"] = "Armes prudent",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "Armes, armures, matériaux, recettes et montures : qui les laisse tomber et qui les vend.",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "Faites glisser chaque cadre de combat où vous voulez. Une fois terminé, verrouillez-les pour qu'ils ne gênent pas.",
	["Arrastra lo que quieras mover. Clic derecho en uno: vuelve a su lugar de siempre."] = "Fais glisser ce que tu veux déplacer. Clic droit sur un élément : il revient à sa place habituelle.",
	["Arrastra otra bolsa aquí para cambiarla."] = "Faites glisser un autre sac ici pour le remplacer.",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "Faites glisser pour déplacer vos cadres. Changez leur taille et leurs colonnes sur la page Soins.",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "Faites glisser pour déplacer vos cadres. Cliquez (avec ou sans Maj, Ctrl ou Alt) pour voir ce qui serait lancé.",
	["Arrastra tus marcos de combate adonde te acomoden. Para fijarlos, vuelve a Combate o escribe /alfa combate mover."] = "Fais glisser tes cadres de combat là où ça te convient. Pour les verrouiller, reviens à Combat ou tape /alfa combate mover.",
	["Arrastra una bolsa aquí para ponerla."] = "Faites glisser un sac ici pour l'équiper.",
	["Arreglos: «Cerrar mis misiones» vuelve a armar tu ruta, la ayuda de rotación vuelve a decirte qué usar y el mapa ya no muestra rectángulos pegados al acercar."] = "Corrections : « Terminer mes quêtes » trace de nouveau ton itinéraire, l’aide à la rotation te redit quoi utiliser et la carte n’affiche plus de rectangles collés en zoomant.",
	["Arriba a la derecha, el ícono de magia, maldición, veneno o enfermedad. Al pasar el ratón te dice qué clic lo quita."] = "En haut à droite, l'icône de magie, malédiction, poison ou maladie. Survole-la pour voir quel clic l'enlève.",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "En haut de la fenêtre, chaque sac équipé avec sa place : survolez-le pour mettre en évidence son contenu et faites glisser un autre sac pour le remplacer.",
	["Arriba de tus marcos, el maná de quienes curan en tu grupo. Se destaca al terminar cada pelea."] = "Au-dessus de tes cadres, le mana des soigneurs de ton groupe. Il ressort après chaque combat.",
	["Arriba en esta ventana está lo último que te dije, con sus botones. Para ver los 20 más recientes: /alfa lya historial."] = "En haut de cette fenêtre, ce que je t’ai dit en dernier, avec ses boutons. Les 20 plus récents : /alfa lya historial.",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "En haut, ce qu'Alfa recommande. Un clic et c'est parti.",
	["Arriesgado"] = "Risqué",
	["Arrodillarse"] = "S'agenouiller",
	["Arrojadiza"] = "Arme de jet",
	["Arrástralo para moverlo"] = "Faites-le glisser pour le déplacer",
	["Arrástralo para moverlo."] = "Fais-le glisser pour le déplacer.",
	["Arrástralo para moverlo. Clic derecho: vuelve a su lugar de siempre."] = "Fais-le glisser pour le déplacer. Clic droit : retour à sa place habituelle.",
	["Artefacto"] = "Artefact",
	["Artesano"] = "Artisan",
	["Artesanía y comercio"] = "Artisanat et marchandises",
	["Arthas mató a Kel'Thuzad en Andorhal, pero después lo revivió como liche con el poder de la Fuente del Sol."] = "Arthas a tué Kel'Thuzad à Andorhal, mais l'a ensuite relevé en liche grâce au pouvoir du Puits de soleil.",
	["Arthas mató al archimago Antonidas en Dalaran, y después Archimonde destruyó la ciudad."] = "Arthas a tué l'archimage Antonidas à Dalaran, puis Archimonde a détruit la ville.",
	["Arthas purgó Stratholme porque su grano estaba infectado. Esa decisión lo separó para siempre de Uther y de Jaina."] = "Arthas a purgé Stratholme parce que son grain était infecté. Cette décision l'a séparé pour toujours d'Uther et de Jaina.",
	["Arthas tomó la espada Agonía de Escarcha en Rasganorte creyendo que salvaría a su pueblo. La espada le robó el alma."] = "Arthas a pris l'épée Deuillelame en Norfendre en croyant qu'elle sauverait son peuple. L'épée lui a volé son âme.",
	["Arthas y Jaina se querían antes de que la plaga los separara."] = "Arthas et Jaina s'aimaient avant que la peste ne les sépare.",
	["Asesinato"] = "Assassinat",
	["Asesinato para subir"] = "Assassinat pour monter",
	["Aspecto"] = "Aspect",
	["Astranaar es el pueblo élfico en medio de Vallefresno, en una isla del lago."] = "Astranaar est la ville elfe au milieu d'Orneval, sur une île du lac.",
	["Asusta a los enemigos cercanos. Cuidado: pueden correr y traer a otros."] = "Effraie les ennemis proches. Attention : ils peuvent fuir et en ramener d'autres.",
	["Asusta a los enemigos cercanos. Te da tiempo para escapar o curarte."] = "Effraie les ennemis proches. Te donne le temps de fuir ou de te soigner.",
	["Asusta a todos los enemigos cercanos."] = "Effraie tous les ennemis proches.",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "Il apeure tous ceux qui sont proches : si vous êtes apeuré, essayez de ne pas courir vers d'autres cellules.",
	["Asusta a un enemigo y lo hace huir. Cuidado: puede traer a otros."] = "Effraie un ennemi et le fait fuir. Attention : il peut en ramener d'autres.",
	["Asusta un momento al enemigo y te cura. Tu escape de emergencia."] = "Effraie l'ennemi un instant et te soigne. Ta fuite d'urgence.",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "Il apeure et endort les joueurs : si vous êtes apeuré, essayez de ne pas courir vers d'autres ennemis.",
	["Así la manada se encuentra para cazar juntos. Es tu decisión, y la cambias cuando quieras."] = "C’est comme ça que la meute se retrouve pour chasser ensemble. C’est ton choix, et tu le changes quand tu veux.",
	["Así queda tu Alfa"] = "Voici ton Alfa",
	["Así sabes qué hace cada clic antes de tu próxima pelea."] = "Ainsi, vous savez ce que fait chaque clic avant votre prochain combat.",
	["Así se lee tu ayuda de rotación"] = "Comment lire votre aide à la rotation",
	["Así se ve en pantalla. Vuelve a Combate con /alfa combate."] = "Voilà à quoi ça ressemble à l'écran. Reviens à Combat avec /alfa combate.",
	["Así se ven tus avisos"] = "Voici à quoi ressemblent tes alertes",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo, en Marcos. Pulsa Listo cuando termines."] = "Voici à quoi ressembleront vos cadres. Faites-les glisser pour les déplacer et changez leur taille plus bas, dans Cadres. Appuyez sur Terminé une fois fini.",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo. Pulsa Listo cuando termines."] = "Voici à quoi ressembleront vos cadres. Faites-les glisser pour les déplacer et changez leur taille ci-dessous. Appuyez sur Terminé quand vous avez fini.",
	["Así terminó «%s»… ¿Te cuento el final?"] = "Voilà comment s'est terminée « %s »… Je te raconte la fin ?",
	["Así: /alfa cita mañana 21:30 Minas de la Muerte"] = "Comme ça : /alfa cita tomorrow 21:30 Mortemines",
	["Atacas más rápido según tus puntos de combo. Mantenlo en las peleas largas."] = "Tu attaques plus vite selon tes points de combo. Garde-le actif dans les longs combats.",
	["Atajos"] = "Raccourcis",
	["Ataque de tormenta: mucho daño, cada vez que esté listo."] = "Frappe-tempête : gros dégâts, dès qu'elle est prête.",
	["Ataques más rápidos después de un crítico."] = "Attaques plus rapides après un critique.",
	["Atardecer"] = "Coucher de soleil",
	["Atenuar a quien está lejos"] = "Atténuer les membres hors de portée",
	["Atiesh, el Gran Bastón del Guardián, fue de Medivh. En el Clásico se puede rehacer con fragmentos que caen en Naxxramas."] = "Atiesh, grand bâton du Gardien, appartenait à Medivh. En Classic, on peut la reforger avec des fragments qui tombent à Naxxramas.",
	["Atrapa al enemigo en su lugar. Para alejarte y lanzar tranquilo."] = "Immobilise l'ennemi sur place. Éloigne-toi et lance tranquillement.",
	["Atravesar objetos pequeños"] = "Traverser les petits objets",
	["Atronar fuerte: juntas varios monstruos y los frenas a todos."] = "Coup de tonnerre puissant : vous regroupez plusieurs monstres et les ralentissez tous.",
	["Atronar más barato para agarrar varios."] = "Coup de tonnerre moins cher pour en retenir plusieurs.",
	["Atronar más fuerte y barato: agarras a varios enemigos a la vez."] = "Coup de tonnerre plus fort et moins cher : vous retenez plusieurs ennemis à la fois.",
	["Atrás"] = "Retour",
	["Aturde al enemigo en forma de oso. Úsalo para interrumpir."] = "Étourdit l'ennemi en forme d'ours. Utilise-le pour interrompre.",
	["Aturde al enemigo unos segundos. Úsalo para interrumpir o para escapar."] = "Étourdit l'ennemi quelques secondes. Utilise-le pour interrompre ou fuir.",
	["Aturde al tanque con su martillo: mantén la vida del tanque alta."] = "Il étourdit le tank avec son marteau : gardez la vie du tank haute.",
	["Aturde según tus puntos de combo. Úsalo para interrumpir o rematar."] = "Étourdit selon tes points de combo. Utilise-le pour interrompre ou achever.",
	["Aturdes a uno mientras peleas con otro."] = "Vous étourdissez l'un pendant que vous combattez l'autre.",
	["Aturdes al enemigo más peligroso."] = "Vous étourdissez l'ennemi le plus dangereux.",
	["Aturdimiento a demanda."] = "Un étourdissement à la demande.",
	["Auberdine es el puerto de los elfos de la noche: de ahí salen barcos a Teldrassil y a los Reinos del Este."] = "Auberdine est le port des elfes de la nuit : des bateaux en partent pour Teldrassil et les royaumes de l'Est.",
	["Aullar al completar una misión"] = "Hurler quand tu termines une quête",
	["Aullar con tu grupo"] = "Hurler avec ton groupe",
	["Aullido"] = "Hurlement",
	["Aullido al abrir Alfa"] = "Hurlement à l'ouverture d'Alfa",
	["Aun de día el Bosque del Ocaso está oscuro. Aquí nunca sale el sol del todo."] = "Même de jour, le bois de la Pénombre est sombre. Le soleil n'y perce jamais vraiment.",
