	["Automática"] = "Automatique",
	["Automático"] = "Automatique",
	["Automático: el del buscador de grupo, o por tu clase y tu forma (postura defensiva u oso tanquean)."] = "Automatique : le rôle de la recherche de groupe, ou selon ta classe et ta forme (posture défensive ou ours = tank).",
	["Automático: el que marcaste en tu grupo, o tu actitud o forma."] = "Automatique : celui que tu as indiqué dans ton groupe, ou ta posture ou ta forme.",
	["Avanza en tu guía con la flecha"] = "Avance dans ton guide avec la flèche",
	["Avanzado"] = "Avancé",
	["Aventura"] = "Aventure",
	["Aventura (2): explorar todo el mapa del mundo con un personaje y terminar la cadena de Lord Valthalak (el conjunto de mazmorra 2)."] = "Aventure (2) : explorer toute la carte du monde avec un personnage et terminer la chaîne de seigneur Valthalak (ensemble de donjon 2).",
	["Aventura, Personaje, Mundo, Oficios, Manada y Ajustes. Cada una tiene sus páginas."] = "Aventure, Personnage, Monde, Métiers, Meute et Réglages. Chacune a ses pages.",
	["Aventura: descanso más rápido, vida y maná tras cada muerte, ver mejor a los sigilosos, talentos hasta 5 niveles antes y vuelos más baratos y rápidos."] = "Aventure : repos plus rapide, vie et mana après chaque victime, meilleure détection des furtifs, talents jusqu'à 5 niveaux plus tôt et vols moins chers et plus rapides.",
	["Avienta a todos los que están cerca: si peleas de lejos, aléjate."] = "Il repousse tous ceux qui sont proches : si vous combattez à distance, éloignez-vous.",
	["Avienta y aturde a todos los que están cerca: ponte con la espalda en la pared."] = "Elle repousse et étourdit tous ceux qui sont proches : placez-vous dos à un mur.",
	["Avisar a tu grupo cuando completas una misión"] = "Prévenir ton groupe quand tu termines une quête",
