	["Ay, lobo… van varias caídas seguidas. Respira, repara tu equipo y, si quieres, pide ayuda a la manada."] = "Oh, loup… plusieurs morts d'affilée. Respire, répare ton équipement et, si tu veux, demande de l'aide à la meute.",
	["Ayuda al subastar"] = "Aide aux enchères",
	["Ayuda de rotación"] = "Aide à la rotation",
	["Ayuda de rotación para las 27 especializaciones y la ventana /alfa paisaje con 68 ajustes gráficos explicados."] = "Une aide à la rotation pour les 27 spécialisations et la fenêtre /alfa paisaje avec 68 réglages graphiques expliqués.",
	["Ayudas de combate"] = "Aides au combat",
	["Ayudas para tu personaje"] = "Aides pour ton personnage",
	["Azeroth"] = "Azeroth",
	["Azeroth tiene dos continentes en el Clásico: Kalimdor al oeste y los Reinos del Este. En medio está el Gran Mar."] = "En Classic, Azeroth a deux continents : Kalimdor à l'ouest et les royaumes de l'Est. Entre les deux s'étend la Grande mer.",
	["Azshara lleva el nombre de la reina de los elfos que abrió la puerta a la Legión Ardiente. Tras la Gran División se convirtió en la reina de los naga."] = "Azshara porte le nom de la reine des elfes qui ouvrit la porte à la Légion ardente. Après la Fracture, elle devint la reine des nagas.",
	["Azshara y los Altonato que se hundieron con su palacio no murieron: se transformaron en los naga."] = "Azshara et les Bien-nés qui ont sombré avec son palais ne sont pas morts : ils sont devenus les nagas.",
	["Azul"] = "Bleu",
	["Azul de medianoche casi negro con detalles en plata de luna. Para cazar de noche."] = "Bleu minuit presque noir avec des touches d'argent de lune. Pour chasser la nuit.",
	["Aún nada esta semana"] = "Rien encore cette semaine",
	["Aún nadie responde"] = "Pas encore de réponse",
	["Aún no conozco a ningún lobo conectado que comparta su clase y su nivel. Pídeles que prendan «Compartir mi clase y nivel» en La Jauría."] = "Je ne connais encore aucun loup connecté qui partage sa classe et son niveau. Demande-leur d'activer « Partager ma classe et mon niveau » dans La Jauría.",
	["Aún no conozco ese objeto. Pásale el ratón encima y vuelve a intentarlo."] = "Je ne connais pas encore cet objet. Survolez-le avec la souris et réessayez.",
	["Aún no conozco su precio. Al buscarlo o escanear, Alfa lo aprende."] = "Je ne connais pas encore son prix. Alfa l'apprend quand tu le cherches ou scannes.",
	["Aún no dejas notas. También sirve /alfa nota <texto>."] = "Pas encore de notes. /alfa nota <texte> marche aussi.",
	["Aún no está terminada: te falta %s."] = "Pas encore terminée : il vous manque %s.",
	["Aún no está terminada: termínala antes de entregarla."] = "Pas encore terminée : terminez-la avant de la rendre.",
	["Aún no ganas oro en esta sesión. Alfa cuenta lo que ganas desde que entraste al juego."] = "Pas encore d'or gagné cette session. Alfa compte ce que tu gagnes depuis ta connexion.",
	["Aún no guardas ningún conjunto."] = "Tu n'as encore enregistré aucun ensemble.",
	["Aún no hay historias"] = "Pas encore d'histoires",
	["Aún no hay misiones de clase para ti: la próxima abre a nivel %d."] = "Pas encore de quêtes de classe pour vous : la prochaine s'ouvre au niveau %d.",
	["Aún no hay personajes guardados"] = "Aucun personnage enregistré pour l'instant",
