	["Aún no los aprendes"] = "Pas encore appris",
	["Aún no picaba"] = "Ça n'avait pas encore mordu",
	["Aún no puedes tomar %s"] = "Vous ne pouvez pas encore prendre %s",
	["Aún no sé cómo va."] = "Pas encore de nouvelles.",
	["Aún no tienes el nivel"] = "Votre niveau est encore trop bas",
	["Aún no tienes nada abierto. Mira Todas o usa los filtros de arriba para encontrar una guía."] = "Rien d'ouvert pour l'instant. Regardez dans Tous ou utilisez les filtres ci-dessus pour trouver un guide.",
	["Aún no tienes perfiles"] = "Tu n'as pas encore de profils",
	["Aún no tienes precios de la subasta: escanéala para saber cuánto vale de verdad."] = "Vous n'avez pas encore de prix de l'hôtel des ventes : scannez-le pour savoir ce que valent vraiment vos objets.",
	["Aún no tienes precios. Pulsa «Escanear con Alfa»."] = "Pas encore de prix. Appuyez sur « Scanner avec Alfa ».",
	["Aún no tienes rutas. Ármalas en la ventana de Alfa: Aventura > Rutas; cada una aparece aquí como guía."] = "Tu n'as pas encore d'itinéraires. Crée-les dans la fenêtre d'Alfa : Aventure > Itinéraires ; chacun apparaît ici comme un guide.",
	["Aún sin abrir: gana tu primer punto"] = "Pas encore débloqué : gagnez votre premier point",
	["Bahía del Botín es el puerto del cártel Bonvapor, y ahí manda el barón Revilgaz."] = "Baie-du-Butin est le port du cartel Gentepression, et c'est le baron Revilgaz qui y commande.",
	["Bailar"] = "Danser",
