	["Busca %s en: %s."] = "Cherche %s dans : %s.",
	["Busca addons que chocan con Alfa, partes apagadas y ajustes raros, con el arreglo a un clic. También con /alfa diagnostico."] = "Cherche les addons en conflit avec Alfa, les parties désactivées et les réglages étranges, avec la solution en un clic. Aussi avec /alfa diagnostico.",
	["Busca al entrenador de tu clase en la ciudad."] = "Cherche le maître de ta classe en ville.",
	["Busca cualquier cosa del juego"] = "Cherchez n'importe quoi dans le jeu",
	["Busca cualquier cosa, en español o en inglés…"] = "Cherchez n'importe quoi, en français ou en anglais…",
	["Busca el arma de dos manos con más daño por segundo: es lo que más sube tu daño."] = "Cherchez l'arme à deux mains avec le plus de dégâts par seconde : c'est ce qui augmente le plus vos dégâts.",
	["Busca el arma de dos manos más lenta y fuerte: tus sellos pegan con ella."] = "Cherchez l'arme à deux mains la plus lente et la plus forte : vos sceaux frappent avec elle.",
	["Busca la zona de la misión entre las guías de subir de nivel."] = "Cherchez la zone de la quête parmi les guides de montée de niveau.",
	["Busca lo mejor que puedes usar"] = "Cherche le meilleur que vous pouvez utiliser",
	["Busca por aquí"] = "Cherche par ici",
	["Busca siempre el arco, arma de fuego o ballesta con más daño por segundo."] = "Cherchez toujours l'arc, l'arme à feu ou l'arbalète avec le plus de dégâts par seconde.",
	["Busca un escudo con valor de bloqueo alto: sube el daño de Embate con escudo."] = "Cherchez un bouclier avec une valeur de blocage élevée : il augmente les dégâts de Heurt de bouclier.",
	["Busca un objeto en las bolsas, bancos y equipo de todos tus personajes. Los demás, con lo último que guardó Alfa."] = "Trouve un objet dans les sacs, banques et équipements de tous tes personnages. Les autres, avec ce qu'Alfa a enregistré en dernier.",
	["Busca una misión, un PNJ, una zona o una palabra…"] = "Cherchez une quête, un PNJ, une zone ou un mot…",
