	["Buzones, entrenadores, banco, subasta, reparar..."] = "Boîtes aux lettres, maîtres, banque, hôtel des ventes, réparations...",
	["Buzón"] = "Boîte aux lettres",
	["Básico"] = "Basique",
	["Búscalo en %s."] = "Cherche-le à %s.",
	["Búscalo en la Enciclopedia: objetos, PNJ, misiones, zonas y raros, con dónde están y el botón «Guíame»."] = "Cherche dans l’Encyclopédie : objets, PNJ, quêtes, zones et rares, avec où les trouver et le bouton « Guide-moi ».",
	["Búscalo por su nombre; se cumple cuando lo tienes en tus bolsas."] = "Cherchez-le par son nom ; c'est rempli quand il est dans vos sacs.",
	["CPS"] = "HPS",
	["Cabeza"] = "Tête",
	["Cada 2 niveles"] = "Tous les 2 niveaux",
	["Cada Aspecto guía un vuelo de dragones: Alexstrasza el rojo, Ysera el verde, Nozdormu el bronce, Malygos el azul y Neltharion el negro."] = "Chaque Aspect mène un vol draconique : Alexstrasza le rouge, Ysera le vert, Nozdormu le bronze, Malygos le bleu et Neltharion le noir.",
	["Cada ajuste que Alfa cambió vuelve al valor que tenía antes. Los filtros no cambian."] = "Chaque réglage modifié par Alfa revient à sa valeur précédente. Les filtres ne changent pas.",
	["Cada aviso y cada porqué sale con texto hasta %d veces y luego solo queda el ícono."] = "Chaque alerte et chaque raison s'affiche avec du texte jusqu'à %d fois, puis seule l'icône reste.",
	["Cada año, el día que empezaron a cazar juntos, Lya lo festeja. Y también el cumpleaños de Alfa."] = "Chaque année, le jour où vous avez commencé à chasser ensemble, toi et Lya, elle fait la fête. Et l'anniversaire d'Alfa aussi.",
	["Cada bloqueo te da ira: nunca te falta."] = "Chaque blocage vous donne de la rage : vous n'en manquez jamais.",
	["Cada bolsa en su bloque, con su nombre y su espacio."] = "Chaque sac dans son bloc, avec son nom et sa place.",
	["Cada botón de acción con el borde y el fondo del estilo, el ícono cuadrado y la letra de Alfa en la tecla y la cuenta."] = "Chaque bouton d'action avec la bordure et le fond du style, une icône carrée et la police d'Alfa sur la touche et le compteur.",
	["Cada casilla en su lugar, como en tus bolsas."] = "Chaque emplacement à sa place, comme dans vos sacs.",
	["Cada clase da retos del Legado al llegar a 25, 45 y 60: subir otras clases también le suma a tu cuenta."] = "Chaque classe donne des défis de l'Héritage aux niveaux 25, 45 et 60 : monter d'autres classes rapporte aussi à ton compte.",
	["Cada clic que cura también selecciona a ese compañero, para seguir con otro poder, un buff o quitarle una maldición o un veneno."] = "Chaque clic de soin cible aussi ce compagnon, pour enchaîner avec une autre technique, une amélioration, ou dissiper une malédiction ou un poison.",
	["Cada cofre o tesoro conocido."] = "Chaque coffre ou trésor connu.",
	["Cada crítico hace sangrar."] = "Chaque critique fait saigner.",
	["Cada domingo en Tuercespina: el primero en llevar 40 pescados sabrosos de los bancos especiales gana. También salen peces raros que se cambian por premios."] = "Chaque dimanche à Strangleronce : le premier à rapporter 40 poissons savoureux tachetés des bancs spéciaux gagne. Des poissons rares apparaissent aussi et s'échangent contre des prix.",
	["Cada entrada de mazmorra y banda con su rango de niveles. Clic: su página; Mayús+clic: la flecha te lleva."] = "Chaque entrée de donjon et de raid avec sa tranche de niveaux. Clic : sa page ; Maj+clic : la flèche vous y mène.",
	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "Chaque phrase apparaît trois fois au plus. Ceci les fait toutes revenir depuis le début.",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "Chaque coup critique fait saigner l'ennemi : des dégâts en plus sans rien faire.",
	["Cada grupo de la banda en su propia columna (o fila), como en la ventana de banda. Con el orden por grupo."] = "Chaque groupe du raid dans sa propre colonne (ou ligne), comme dans la fenêtre de raid. Avec le tri par groupe.",
	["Cada hierba pide más habilidad que la anterior: recoge todo lo que puedas y sube sola. Enciende el rastreo de hierbas."] = "Chaque herbe demande plus de compétence que la précédente : cueille tout ce que tu peux et ça monte tout seul. Active la détection des herbes.",
	["Cada hierba tiene su lugar: unas junto al agua, otras en las montañas o bajo los árboles."] = "Chaque herbe a sa place : certaines près de l'eau, d'autres dans les montagnes ou sous les arbres.",
	["Cada lugar conocido donde aparece un enemigo raro."] = "Chaque endroit connu où apparaît un ennemi rare.",
	["Cada lunes te pongo tres retos chiquitos: misiones, raros y uno sorpresa. Tu avance está en mi página y cada reto cumplido vale una salchicha de premio."] = "Chaque lundi, je te donne trois petits défis : des quêtes, des rares et une surprise. Ta progression est sur ma page, et chaque défi réussi vaut une saucisse en récompense.",
	["Cada lunes, tres retos chiquitos con su salchicha de premio. Tu avance sale arriba, en esta página."] = "Chaque lundi, trois petits défis avec une saucisse en récompense. Ta progression s'affiche en haut de cette page.",
	["Cada meseta de Cima del Trueno tiene su función: una para los ancianos y los druidas, otra para los espíritus y otra para los cazadores."] = "Chaque plateau des Pitons-du-Tonnerre a son rôle : un pour les anciens et les druides, un pour les esprits et un pour les chasseurs.",
	["Cada misión que terminas te hace más fuerte."] = "Chaque quête terminée te rend plus fort.",
	["Cada muelle con cuánto falta para que llegue su barco o zepelín."] = "Chaque quai avec le temps avant l'arrivée de son bateau ou zeppelin.",
	["Cada muelle con cuánto falta para que llegue."] = "Chaque quai avec le temps avant l'arrivée.",
	["Cada nivel"] = "À chaque niveau",
	["Cada paso de la bienvenida deja bajar hasta el final, sin cerrar y volver a abrir."] = "Chaque étape de l'accueil défile jusqu'en bas, sans fermer ni rouvrir.",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "Chaque préréglage remplit vos clics avec les sorts que vous connaissez déjà. Changez ensuite ce que vous voulez sur la page Soins.",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "Chaque défi rapporte 1 point. Au lancement de Forever il y a %d défis, et chaque personnage peut en dépenser jusqu'à %d.",
	["Cada semana guardo una copia de tus ajustes y perfiles. En Ajustes > Estilo y sonido, en «Respaldos», vuelves a una con un clic."] = "Chaque semaine, je garde une copie de tes réglages et profils. Dans Réglages > Style et son, sous « Sauvegardes », tu reviens à l'une d'elles en un clic.",
	["Cada versión nueva te recibe con la intro del lobo y sus notas, como estas."] = "Chaque nouvelle version t'accueille avec l'intro du loup et ses notes, comme celles-ci.",
	["Cada vez que aprendes uno de los principales de tu clase te digo en corto para qué sirve y cuándo usarlo."] = "Chaque fois que tu apprends un des sorts principaux de ta classe, je te dis en bref à quoi il sert et quand l'utiliser.",
	["Cada vez que entras al juego, la intro del lobo y la luna te da la bienvenida. Un clic o Esc la saltan."] = "À chaque connexion, l'intro du loup et de la lune te souhaite la bienvenue. Un clic ou Échap la passe.",
	["Cada vez: %s."] = "À chaque fois : %s.",
	["Cada zona con lobos y cuántos hay en cada guarida. En el mapa del mundo también sale."] = "Chaque zone avec des loups et combien il y en a dans chaque tanière. Ça s'affiche aussi sur la carte du monde.",
	["Cada ícono del mapa con su tamaño exacto en tu pantalla, nítido de orilla a orilla."] = "Chaque icône de la carte à sa taille exacte sur ton écran, nette d'un bord à l'autre.",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "Cairne Sabot-de-Sang gouverne depuis les Pitons-du-Tonnerre, même si Magatha, des Totem-Sinistre, ne l'aime pas autant qu'elle le prétend.",
	["Cairne Pezuña de Sangre peleó en el Monte Hyjal junto a Thrall contra la Legión."] = "Cairne Sabot-de-Sang a combattu au mont Hyjal aux côtés de Thrall contre la Légion.",
	["Caja para escribir con el estilo"] = "Champ de saisie stylisé",
	["Calculando"] = "Calcul",
	["Calculando la vuelta más corta…"] = "Calcul de la boucle la plus courte…",
	["Calidad"] = "Qualité",
	["Calidad de la niebla"] = "Qualité du brouillard",
	["Calidad de las sombras"] = "Qualité des ombres",
	["Calla las voces de /bailar, /reír, /aplaudir y otros gestos."] = "Coupe les voix de /danser, /rire, /applaudir et des autres émotes.",
	["Calla los ruidos de las mascotas, como el bostezo de los gatos de cazador."] = "Coupe les bruits des familiers, comme le bâillement des félins de chasseur.",
	["Calma, que la cacería no se va a ningún lado. Come algo, repara y, si es mucho, la manada te echa la mano."] = "Doucement, la chasse ne va nulle part. Mange un morceau, répare et, si c'est trop, la meute te donne un coup de patte.",
