	["Comida que da aguante o fuerza extra, y comes mientras descansas."] = "De la nourriture qui donne de l'endurance ou de la force en plus, à manger pendant que vous vous reposez.",
	["Comida y agua"] = "Nourriture et eau",
	["Comida y agua para llevar"] = "Nourriture et eau à emporter",
	["Comida y bebida"] = "Nourriture et boisson",
	["Comida, bebida y más"] = "Nourriture, boisson et plus",
	["Comida: llevas %d (mejor %d o más). A tu nivel: %s"] = "Nourriture : tu as %d (mieux vaut %d ou plus). À ton niveau : %s",
	["Comisión de la subasta"] = "Commission de l'hôtel des ventes",
	["Comisión de la subasta estimada: %d%%."] = "Commission estimée de l'hôtel des ventes : %d%%.",
	["Como el juego"] = "Comme le jeu",
	["Como espíritu, Lya te dice a cuánto está tu cuerpo, lo que cuesta el ángel a tu nivel y qué conviene. La flecha te lleva."] = "En esprit, Lya te dit à quelle distance est ton cadavre, ce que coûte l'esprit guérisseur à ton niveau et ce qui vaut mieux. La flèche t'y emmène.",
	["Como están"] = "Tels quels",
	["Como guerrero no te curas solo: Primeros auxilios y algo de comida te salvan entre peleas."] = "En guerrier, tu ne te soignes pas tout seul : le Secourisme et un peu de nourriture te sauvent entre les combats.",
	["Como juegas, llegas en 1 día."] = "À ton rythme, tu y arrives en 1 jour.",
	["Como juegas, llegas en unos %d días."] = "À ton rythme, tu y arrives en environ %d jours.",
