	["Completo"] = "Complet",
	["Componentes"] = "Composants",
	["Compra lo que tu paso necesita si el comerciante lo vende. Nada de más de 50 de oro."] = "Achète ce dont ton étape a besoin si le marchand le vend. Rien au-delà de 50 po.",
	["Compra tu montura con %s"] = "Achetez votre monture auprès de %s",
	["Comprar"] = "Acheter",
	["Comprar comida y bebida"] = "Acheter nourriture et boisson",
	["Comprar lo que falta cuesta más de %s (faltan precios)."] = "Acheter ce qui manque coûte plus de %s (des prix manquent).",
	["Comprar lo que falta cuesta unos %s."] = "Acheter ce qui manque coûte environ %s.",
	["Comprar lo que pide tu guía"] = "Acheter ce que demande ton guide",
	["Comprar otra casilla del banco"] = "Acheter un autre emplacement de banque",
	["Comprar y vender con otros"] = "Acheter et vendre avec d'autres joueurs",
	["Compártela y la hacen juntos."] = "Partage-la et faites-la ensemble.",
	["Comunidad"] = "Communauté",
	["Común"] = "Classique",
	["Con %s salen dos flechas a la vez. Alfa puede usar la de TomTom y esconder la suya."] = "Avec %s, deux flèches s'affichent en même temps. Alfa peut utiliser celle de TomTom et cacher la sienne.",
	["Con /alfa reportar: yo ya junté los errores que atrapé, con su versión y cuántas veces salieron. Tú solo lo pegas en el Discord."] = "Avec /alfa reportar : j'ai déjà réuni les erreurs interceptées, avec leur version et combien de fois elles sont apparues. Tu n'as qu'à coller sur Discord.",
	["Con /alfa, con el lobo del minimapa o dándome clic derecho. Para hablar conmigo de todo esto: /alfa ayuda."] = "Avec /alfa, le loup de la minicarte ou un clic droit sur moi. Pour parler de tout ça avec moi : /alfa ayuda.",
	["Con 10 de furia o más lo lanzas."] = "Tu peux le lancer à partir de 10 points de rage.",
	["Con 2 casillas libres o menos, un aviso con lo primero que puedes soltar y un botón para vender o ver tus bolsas."] = "Avec 2 emplacements libres ou moins, une alerte avec la première chose dont tu peux te séparer et un bouton pour vendre ou voir tes sacs.",
	["Con 2 o más misiones listas, el rastreador ofrece llevarte a entregarlas por el camino más corto."] = "Avec 2 quêtes prêtes ou plus, le suivi propose de t'emmener les rendre par le chemin le plus court.",
	["Con Cocina puedes encender tu propia fogata en cualquier lado."] = "Avec la Cuisine, tu peux allumer ton propre feu de camp n'importe où.",
	["Con Redención reviven tus compañeros caídos: en una mazmorra vale oro."] = "Avec Rédemption, tes compagnons tombés reviennent à la vie : en donjon, ça vaut de l'or.",
	["Con aullido"] = "Avec le hurlement",
	["Con buena reputación, los vendedores de esa facción te hacen descuento."] = "Avec une bonne réputation, les vendeurs de cette faction te font une remise.",
	["Con calma, nos pasa a todos. Mira qué te pegó y vuelve con todo."] = "Du calme, ça arrive à tout le monde. Regarde ce qui t'a frappé et reviens en force.",
	["Con dos amigos, trae hasta aquí a alguien de tu grupo."] = "Avec deux amis, fait venir ici quelqu'un de ton groupe.",
	["Con dos armas pega más rápido: guarda maná para el final."] = "Avec deux armes, il frappe plus vite : gardez du mana pour la fin.",
	["Con el correo puedes enviar contra reembolso: mandas el objeto y cobras al entregarlo."] = "Par courrier, tu peux envoyer contre remboursement : tu envoies l'objet et tu es payé à la réception.",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "Quand l'infobulle est masquée en combat, maintenez Maj enfoncée pour la voir.",
	["Con el cursor encima no se cierra."] = "Il ne se ferme pas tant que le curseur est dessus.",
	["Con el entrenador más cercano en tu camino."] = "Avec le maître le plus proche sur ton chemin.",
	["Con el mapa de vuelos abierto, marca el destino más cerca de tu paso de ahora."] = "Avec la carte des vols ouverte, marque la destination la plus proche de ton étape actuelle.",
	["Con el mapa de vuelos abierto, marco con una huella el destino más cerca de tu paso de ahora."] = "Avec la carte des vols ouverte, je marque d'une empreinte la destination la plus proche de ton étape actuelle.",
	["Con el modo pesca abierto y alguna meta, la ventanita de metas se ve sola."] = "Avec le mode pêche ouvert et un objectif, la petite fenêtre d'objectifs s'affiche toute seule.",
	["Con el modo pesca abierto, esta tecla lo hace todo: equipo, cebo, lanzar y recoger. Al cerrarlo vuelve a ser la de siempre."] = "Avec le mode pêche ouvert, cette touche fait tout : équipement, appât, lancer et remonter. À la fermeture, elle redevient la touche habituelle.",
	["Con el modo pesca abierto, un aviso suave para volver a lanzar."] = "Avec le mode pêche ouvert, un rappel discret pour relancer.",
	["Con el tiempo, los magos humanos se reunieron en Dalaran, que se volvió la ciudad de la magia de los Reinos del Este."] = "Avec le temps, les mages humains se sont réunis à Dalaran, qui est devenue la cité de la magie des royaumes de l'Est.",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "Avec l'interface manette, la carte du jeu s'ouvre avec sa propre touche.",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "Avec l'interface pour manette, Alfa laisse les sacs du jeu. Vous pouvez quand même ouvrir la fenêtre d'Alfa d'ici.",
	["Con la tecla en Espacio, Mayús+Espacio salta mientras el modo está abierto."] = "Avec la touche sur Espace, Maj+Espace saute pendant que le mode est ouvert.",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "Avec ceux d'Alfa, vous voyez tout dans une seule fenêtre : trois vues, la recherche, la barre de vos sacs et quoi vendre quand ils se remplissent.",
	["Con lo que gastaste: %s."] = "Après tes dépenses : %s.",
	["Con lo que tienes haces %d: +%s en total"] = "Avec ce que tu as, tu en fais %d : +%s au total",
	["Con mando, se quedan las bolsas del juego"] = "Avec une manette, les sacs du jeu restent",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "Avec ou sans Maj, Ctrl ou Alt. Rien n'est lancé : vous voyez ici ce qui serait lancé sur votre allié.",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "Quand sa vie est basse, il appelle deux aides : s'il est presque mort, achevez-le ; sinon, tuez les aides.",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "Quand sa vie est basse, il se transforme en serpent et frappe plus fort : gardez vos meilleures attaques pour ce moment.",
	["Con qué prioridad sugiere Alfa. Automática: la de tus talentos o, mientras subes, la de tu clase."] = "Avec quelle priorité Alfa suggère. Automatique : celle de vos talents ou, pendant la progression, celle de votre classe.",
	["Con reputación %s"] = "À la réputation %s",
	["Con sonido"] = "Avec son",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "Avec votre build, Alfa sait quelles caractéristiques vous servent et quel équipement chercher.",
	["Con tu grupo"] = "Avec ton groupe",
	["Con tu punto libre se compra 1 rango de %s:"] = "Votre point libre achète 1 rang de %s :",
	["Con tu ritual de invocación y la ayuda de dos compañeros, traes a otro miembro del grupo hasta donde estés."] = "Avec ton Rituel d'invocation et l'aide de deux compagnons, tu amènes un autre membre du groupe jusqu'à toi.",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "Avec vos %d points libres, %d rangs de %s sont achetés :",
	["Con un brillo suave"] = "Avec une douce lueur",
	["Con un comerciante abierto vende tu chatarra; con un banquero guarda tus materiales."] = "Avec un marchand ouvert, ça vend ta camelote ; chez un banquier, ça dépose tes composants.",
	["Con un comerciante o un banquero abierto, «Acomodar» en tus bolsas vende tu chatarra o guarda tus materiales en el banco. Un clic, y otro para detenerlo."] = "Avec un marchand ou un banquier ouvert, « Ranger » dans tes sacs vend ta camelote ou dépose tes composants à la banque. Un clic, et un autre pour l'arrêter.",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "Avec un ennemi ciblé, avant le début du combat, et transparent pour ne pas gêner.",
	["Con una tecla escondes lo del juego que no necesitas y quedan Alfa, tu rastreador y Lya. Otra pulsación lo devuelve todo."] = "D'une touche, tu caches ce dont tu n'as pas besoin dans le jeu et il reste Alfa, ton suivi et Lya. Un autre appui ramène tout.",
	["Con él tu tope sube a %d."] = "Avec lui, ton plafond monte à %d.",
	["Concurso"] = "Concours",
	["Concurso de pesca de Tuercespina"] = "Concours de pêche de Strangleronce",
	["Configura tu Alfa"] = "Configure ton Alfa",
	["Configuración terminada"] = "Configuration terminée",
	["Configuración y ayuda"] = "Configuration et aide",
	["Configurar"] = "Configurer",
	["Configurar con el asistente"] = "Configurer avec l'assistant",
	["Confirmado por Blizzard (su noticia del sistema de Legado de WoW Forever): los 65 retos de 1 punto, el tope de 16 por personaje, los tres árboles, los cuatro premios del registro y lo del modo extremo."] = "Confirmé par Blizzard (son article sur le système d'Héritage de WoW Forever) : les 65 défis à 1 point, le plafond de 16 par personnage, les trois arbres, les quatre récompenses de la piste et les règles du mode Hardcore.",
	["Conflagrar: consume tu Inmolar para un golpe fuerte."] = "Conflagration : consume votre Immolation pour une frappe puissante.",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "Il gèle ceux qui sont proches : si vous combattez à distance, éloignez-vous.",
	["Congela a un enemigo un rato. Ideal para controlar a uno extra en mazmorras."] = "Gèle un ennemi un moment. Idéal pour en contrôler un de plus en donjon.",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "Gelez le monstre avec Nova de givre et éloignez-vous avant de continuer à lancer des sorts.",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "Elle immobilise sur place et lance des éclairs : si vous combattez à distance, écartez-vous du groupe.",
	["Congela en su lugar a los enemigos cercanos. Aléjate y sigue lanzando."] = "Gèle sur place les ennemis proches. Éloigne-toi et continue à lancer.",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "Vous gelez et ralentissez les monstres pour qu'ils ne vous atteignent jamais : le mage le plus sûr pour monter.",
	["Conjuntos de equipo"] = "Ensembles d'équipement",
