	["Consigue %s"] = "Obtenez %s",
	["Consigue bolsas más grandes en cuanto puedas: más espacio, más botín."] = "Procure-toi de plus grands sacs dès que possible : plus de place, plus de butin.",
	["Consigue una caña de pescar"] = "Procurez-vous une canne à pêche",
