	["Continuar mi ruta"] = "Continuer mon itinéraire",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "Contre les boss de haut niveau, vous ratez beaucoup : ceci règle le problème.",
	["Contra jefes fallas mucho: esto te ayuda."] = "Contre les boss, vous ratez beaucoup : ceci vous aide.",
	["Contra lo que llevas:"] = "Par rapport à ce que tu portes :",
	["Contra lo que llevas: lo mismo."] = "Par rapport à ce que tu portes : pareil.",
	["Contra no-muertos y demonios: Exorcismo pega muy fuerte."] = "Contre les morts-vivants et les démons : Exorcisme frappe très fort.",
	["Control de animación"] = "Contrôle de l'animation",
	["Contármela"] = "Me la raconter",
	["Contármelo"] = "Me le raconter",
	["Convierte a un enemigo en oveja un rato. El mejor control en mazmorras."] = "Transforme un ennemi en mouton un moment. Le meilleur contrôle en donjon.",
	["Coordenadas en el mapa"] = "Coordonnées sur la carte",
	["Coordenadas en el minimapa"] = "Coordonnées sur la minicarte",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "Copiez ce texte (Ctrl+C) et transmettez-le à votre meute. Ils le collent dans Importer.",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "Copiez la chaîne ci-dessous et envoyez-la dans la discussion ou sur Discord : avec Alfa, ils la collent dans Importer et ont le même build que vous.",
	["Copiar"] = "Copier",
	["Copiar el Discord"] = "Copier le Discord",
	["Copiar y editar"] = "Copier et modifier",
	["Coral"] = "Corail",
	["Corre hacia el enemigo y lo aturde un momento. Úsala para empezar la pelea, desde lejos."] = "Fonce sur l'ennemi et l'étourdit un instant. Utilise-la à distance pour commencer le combat.",
	["Correr"] = "Courir",
	["Corres mucho más rápido un momento. Para huir o para alcanzar a alguien."] = "Tu cours beaucoup plus vite un instant. Pour fuir ou rattraper quelqu'un.",
	["Corres más rápido, pero si te pegan te aturdes. Solo para viajar."] = "Tu cours plus vite, mais les coups t'hébètent. Seulement pour voyager.",
	["Cortar"] = "Interrompre",
	["Cortar hechizos, amenaza, el tablón de la manada, mentor y dos estilos nuevos."] = "Interruptions, menace, le tableau de la meute, le mentorat et deux nouveaux styles.",
	["Cortar, amenaza y recargas"] = "Interruptions, menace et temps de recharge",
	["Costa Oscura está llena de ruinas élficas, como Ameth'Aran, de una época mucho más antigua."] = "Sombrivage est pleine de ruines elfiques d'une époque bien plus ancienne, comme Ameth'Aran.",
	["Costasur y Molino Tarren están a un paso uno del otro, y la Alianza y la Horda se miran feo desde siempre."] = "Austrivage et Moulin-de-Tarren sont à deux pas l'un de l'autre, et l'Alliance et la Horde s'y regardent de travers depuis toujours.",
	["Costuras, una abominación enorme, ataca Villa Oscura en una de las misiones más famosas del bosque."] = "Recousu, une énorme abomination, attaque Sombre-Comté dans l'une des quêtes les plus célèbres de la forêt.",
	["Crear %s ≈ %s"] = "Fabriquer %s ≈ %s",
	["Crear ruta"] = "Créer l'itinéraire",
	["Crecen hacia"] = "S'étendent vers",
	["Criatura peligrosa"] = "Créature dangereuse",
	["Criaturas de nivel %d a %d"] = "Créatures de niveau %d à %d",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "Créatures rares et trésors : où ils apparaissent et ce qu'ils laissent tomber.",
	["Cristal"] = "Cristal",
	["Créditos y licencias"] = "Crédits et licences",
	["Crítico"] = "Critique",
	["Crítico con hechizos"] = "Critique des sorts",
	["Críticos enormes: matas antes de que te curen."] = "Des critiques énormes : vous tuez avant qu'on ne les soigne.",
	["Críticos más fuertes."] = "Des critiques plus forts.",
	["Críticos un poco más fuertes."] = "Des critiques un peu plus forts.",
	["Ctrl"] = "Ctrl",
	["Cuadro corto en combate"] = "Petite bulle en combat",
	["Cuadro de información"] = "Infobulle",
	["Cualquier criatura de su nivel"] = "N'importe quelle créature de son niveau",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "N'importe laquelle de vos techniques que le jeu met en surbrillance grâce à un effet.",
	["Cualquier instructor de pesca te la enseña. Luego compra una caña y unas lombrices: con eso empiezas."] = "N'importe quel maître de pêche vous l'enseigne. Achetez ensuite une canne et quelques vers : c'est tout ce qu'il faut pour commencer.",
	["Cualquier profesión"] = "N'importe quel métier",
	["Cualquiera"] = "N'importe lequel",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "Quand le monstre a peu de vie, utilisez Exécution (Alfa vous prévient).",
	["Cuando alguien de tu grupo sube de nivel, Lya aúlla, lo felicita y te deja felicitarlo en el chat con un clic."] = "Quand quelqu’un de ton groupe monte de niveau, Lya hurle, le félicite et te laisse le féliciter dans le chat en un clic.",
	["Cuando aprendas %s, también."] = "Dès que vous connaîtrez %s, aussi.",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "Dès que vous connaîtrez %s, il vous prévient au moment de les utiliser.",
	["Cuando aprendas a cortar, aquí sale tu habilidad y su tecla."] = "Quand tu apprendras une interruption, ta technique et sa touche s'afficheront ici.",
	["Cuando aprendas una habilidad para cortar hechizos, te avisa en cuanto tu objetivo empiece a lanzar."] = "Quand tu apprendras une technique qui interrompt les sorts, ça te prévient dès que ta cible commence à incanter.",
	["Cuando aprendes un hechizo importante de tu clase, Lya te dice para qué sirve y cuándo usarlo."] = "Quand tu apprends un sort important de ta classe, Lya te dit à quoi il sert et quand l'utiliser.",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "Quand vous apprenez un nouveau rang, une alerte propose de le remplacer sur vos barres.",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "Quand vous cherchez quelque chose à l'hôtel des ventes, Alfa garde le prix le plus bas que vous voyez.",
	["Cuando caes"] = "Quand tu tombes",
	["Cuando el Pozo de la Eternidad explotó, el gran continente antiguo se partió en pedazos. A eso le llaman la Gran División."] = "Quand le Puits d'éternité a explosé, le grand continent ancien s'est brisé en morceaux. On appelle cela la Fracture.",
	["Cuando el juego termina de cargar, Alfa revisa lo que elegiste aquí y lo vuelve a poner si algo lo cambió. Si después los cambias en el menú del juego, Alfa se queda con lo nuevo."] = "Quand le jeu a fini de charger, Alfa vérifie ce que vous avez choisi ici et le remet si quelque chose l'a changé. Si vous les changez ensuite dans le menu du jeu, Alfa garde les nouveaux.",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "Quand tu entres dans une auberge ou une ville, et quand ton XP de repos est épuisée.",
	["Cuando hay un festival, vale la pena darse una vuelta: casi siempre trae mascotas, ropa o comida que no salen el resto del año."] = "Quand il y a une fête, ça vaut le détour : il y a presque toujours des mascottes, des vêtements ou de la nourriture introuvables le reste de l'année.",
	["Cuando hay varias para elegir, toma la que más te sirve."] = "Quand il y en a plusieurs au choix, prend celle qui te sert le plus.",
	["Cuando huelo salchichas se me olvida todo. Bueno, menos tú."] = "Quand je sens des saucisses, j'oublie tout. Enfin, sauf toi.",
	["Cuando la Legión volvió en la Tercera Guerra, Malfurion y Tyrande hicieron sonar el Cuerno de Cenarius para despertar a los druidas dormidos."] = "Quand la Légion est revenue pendant la Troisième Guerre, Malfurion et Tyrande ont sonné le Cor de Cénarius pour réveiller les druides endormis.",
	["Cuando la meta de ahora de tu plan es un lugar, la flecha lo toma sin que hagas clic."] = "Quand l'objectif actuel de votre plan est un lieu, la flèche le prend sans que vous cliquiez.",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "Quand sa vie baisse, il étourdit tout le monde et court à son coffre changer d'arme : attendez-le, ne le poursuivez pas.",
	["Cuando levantes algo que le sirve a un lobo conectado, te lo digo aquí. Ellos comparten su clase y nivel en los ajustes."] = "Quand tu ramasses quelque chose d'utile à un loup connecté, je te le dis ici. Ils partagent leur classe et leur niveau dans les réglages.",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "Quand vous portez un objet, Alfa vous dit s'il vaut mieux le vendre, le mettre aux enchères ou le transformer, et combien vous gagnez.",
	["Cuando los orcos se volvieron brujos, dejaron de oír a los elementos. Thrall les devolvió ese camino."] = "Quand les orcs sont devenus démonistes, ils ont cessé d'entendre les éléments. Thrall leur a rendu ce chemin.",
	["Cuando no sepas algo de Alfa, dame clic derecho y elige «¿En qué te ayudo?»: te explico cada cosa y te llevo a ella. También te cuento historias del lugar donde estás."] = "Quand tu ne sais pas quelque chose sur Alfa, fais-moi un clic droit et choisis « Je t’aide pour quoi ? » : je t’explique chaque chose et je t’y emmène. Je te raconte aussi des histoires sur l’endroit où tu es.",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "Quand un autre loup avec Alfa partage sa position, il apparaît ici et sur votre carte. Pour agrandir la meute, invitez vos amis : qu'ils installent Alfa, acceptent de partager et rejoignent le Discord de La Jauría.",
	["Cuando sales como espíritu te digo a cuánto está tu cuerpo, lo que cuesta el ángel a tu nivel y qué conviene. La flecha te lleva."] = "Quand tu libères ton esprit, je te dis à quelle distance est ton cadavre, ce que coûte l'esprit guérisseur à ton niveau et ce qui vaut mieux. La flèche t'y emmène.",
	["Cuando se abre una misión de clase para ti, te ofrece su guía."] = "Quand une quête de classe s'ouvre à toi, te propose son guide.",
	["Cuando se escapa"] = "Quand il s'échappe",
	["Cuando se llenan"] = "Quand ils se remplissent",
	["Cuando se te acaban te digo qué te conviene a tu nivel y te llevo al vendedor más cercano. El agua solo si usas maná."] = "Quand il t'en reste peu, je te dis ce qui convient à ton niveau et je t'emmène au vendeur le plus proche. L'eau, seulement si tu utilises du mana.",
	["Cuando te llega equipo mejor que lo que llevas puesto, un aviso con un botón para ponértelo (solo con tu clic y fuera de combate)."] = "Quand tu reçois un équipement meilleur que celui que tu portes, un avis avec un bouton pour l'équiper (seulement sur ton clic et hors combat).",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "Quand vous n'avez plus de mana, passez en forme de félin pour finir le combat.",
	["Cuando tengas las guías de tu facción, aquí sale tu ruta al 60."] = "Dès que tu as les guides de ta faction, ton itinéraire vers le 60 s'affiche ici.",
	["Cuando tengas pescado que sepas cocinar, aparece aquí."] = "Quand vous aurez du poisson que vous savez cuisiner, il apparaîtra ici.",
	["Cuando termine el combate."] = "À la fin du combat.",
	["Cuando tu guía dice «Sube al nivel», el rastreador te dice cuánta experiencia te falta y dónde rinde más: enemigos de tu nivel que también cuentan para tus misiones. «Llévame» y la flecha te lleva."] = "Quand ton guide dit « Atteins le niveau », le suivi te dit combien d'expérience il te manque et où elle rapporte le plus : des ennemis de ton niveau qui comptent aussi pour tes quêtes. « M'y emmener » et la flèche te guide.",
	["Cuando tu objetivo lance algo que se puede cortar, te avisa con %s y su tecla."] = "Quand ta cible incante quelque chose d'interruptible, ça te prévient avec %s et sa touche.",
	["Cuando tu objetivo lanza algo que se puede cortar: tu habilidad para cortar, su tecla y si está lista."] = "Quand ta cible incante quelque chose d'interruptible : ta technique d'interruption, sa touche et si elle est prête.",
	["Cuando tu objetivo o tu foco empieza a lanzar algo que se puede cortar, Alfa te avisa con tu habilidad para cortar, su tecla y si ya está lista. En mazmorras el juego a veces lo oculta: ahí avisa igual que está lanzando."] = "Quand ta cible ou ta focalisation commence à incanter quelque chose d'interruptible, Alfa te prévient avec ta technique d'interruption, sa touche et si elle est prête. En donjon, le jeu le cache parfois : là, il te dit quand même qu'elle incante.",
	["Cuando tu paso lo pide y hablas con su posadero. Nunca en otra posada."] = "Quand ton étape le demande et que tu parles à son aubergiste. Jamais dans une autre auberge.",
	["Cuando tus bolsas se llenan, Hoy te dice qué puedes vender y cuánto te dan."] = "Quand tes sacs se remplissent, Aujourd'hui t'indique ce que tu peux vendre et combien tu en tireras.",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "Quand vous ou votre groupe combattez, vous voyez ici qui fait le plus de dégâts.",
	["Cuando un elfo de la noche muere, su espíritu toma forma de fuego fatuo y corre más rápido hasta su cuerpo."] = "Quand un elfe de la nuit meurt, son esprit prend la forme d'un feu follet et court plus vite jusqu'à son corps.",
	["Cuando un lobo de la manada encuentra un raro, te aviso en qué guarida está y te dejo pedir entrar con un clic."] = "Quand un loup de la meute trouve un rare, je te dis dans quelle tanière il est et tu peux demander à entrer en un clic.",
	["Cuando un lobo de tu zona pide ayuda, te avisa dónde está con «¡Voy!»: la flecha te lleva y le dice que vas."] = "Quand un loup de ta zone demande de l’aide, tu sais où il est avec « J’arrive ! » : la flèche t’y emmène et lui dit que tu viens.",
	["Cuando un lobo encuentra un raro o un tesoro en tu zona, te avisa en qué guarida está. Si es la tuya, «Ir de caza»; si es otra, «Pedir entrar»."] = "Quand un loup trouve un rare ou un trésor dans ta zone, tu sais dans quelle tanière il est. Si c’est la tienne, « Partir en chasse » ; sinon, « Demander à entrer ».",
	["Cuando un oficio llega al tope de su rango, Lya te dice que ya puedes aprender el siguiente y dónde está tu instructor."] = "Quand un métier atteint le maximum de son rang, Lya te dit que tu peux apprendre le suivant et où se trouve ton maître.",
	["Cuando una pieza baja de este porcentaje."] = "Quand une pièce passe sous ce pourcentage.",
	["Cuando una zona se llena, el juego la parte en guaridas (capas): el mismo lugar con otra gente, otros raros y otros minerales. Pide entrar a la de alguien de la manada y el juego te pasa al unirte a su grupo."] = "Quand une zone se remplit, le jeu la divise en tanières (couches) : le même endroit avec d’autres gens, d’autres rares et d’autres minerais. Demande à entrer dans celle d’un membre de la meute et le jeu t’y emmène quand tu rejoins son groupe.",
	["Cuando usas una habilidad que tarda 30 segundos o más en volver, Alfa la pone en una barra discreta con lo que le falta. En Combate eliges cuáles no quieres ver."] = "Quand tu utilises une technique qui met 30 secondes ou plus à revenir, Alfa la place dans une barre discrète avec le temps restant. Dans Combat, tu choisis celles que tu ne veux pas voir.",
	["Cuando vas solo por el mundo, así no sale tras cada enemigo."] = "Quand tu es seul dans le monde, pour qu'il n'apparaisse pas après chaque ennemi.",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "Quand vous vaincrez votre premier boss, votre progression apparaîtra ici.",
	["Cuando ves a alguien que también usa Alfa (y comparte con la manada), un anuncio corto te lo dice para que lo saludes."] = "Quand tu vois quelqu'un qui utilise aussi Alfa (et partage avec la meute), une courte annonce te le dit pour que tu le salues.",
	["Cuando ves caer a un raro, me acuerdo: en su cuadro y en La Jauría te digo hace cuánto lo cazaron y si pudo volver ya (a la media hora, más o menos)."] = "Quand tu vois tomber un rare, je m'en souviens : dans son infobulle et dans La Jauría, je te dis depuis combien de temps il a été tué et s'il peut être revenu (après une demi-heure, environ).",
	["Cuando ya casi se rompe."] = "Quand elle est sur le point de se briser.",
	["Cuando ya entregaste todo o cerraste tu zona, te dice qué sigue (la flecha la pones tú con «Llévame»)."] = "Quand tu as tout rendu ou fini ta zone, il te dit la suite (c'est toi qui places la flèche avec « M'y emmener »).",
	["Cuarenta. ¡Hora de correr más rápido!"] = "Quarante. L'heure de courir plus vite !",
	["Cuello"] = "Cou",
	["Cuenta:"] = "Compte :",
	["Cuero"] = "Cuir",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "Corps à corps avec des totems et des frappes élémentaires : le chaman qui monte le mieux.",
	["Cuesta %s."] = "Coût : %s.",
	["Cuestan %s: te alcanza."] = "Coût : %s. Vous avez assez.",
	["Cuestan %s; llevas %s."] = "Coût : %s ; vous avez %s.",
	["Cuida bien a %s, que la manada lo necesita."] = "Prends bien soin de %s, la meute en a besoin.",
	["Cuidado al nadar mar adentro: en aguas profundas te cansas y te puedes ahogar."] = "Attention en nageant au large : en eau profonde, tu te fatigues et tu peux te noyer.",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "Attention à ne pas en attirer plusieurs à la fois : Feu n'a pas autant de contrôle.",
	["Cuidado: aquí los enemigos son nivel %s."] = "Attention : ici, les ennemis sont niveau %s.",
	["Cumpleaños"] = "Anniversaires",
	["Cumpliste todas sus metas."] = "Vous avez rempli tous ses objectifs.",
	["Cumpliste todas sus metas. Elige otro plan o arma uno nuevo."] = "Vous avez rempli tous ses objectifs. Choisissez un autre plan ou créez-en un nouveau.",
	["Cumpliste tu plan en %s."] = "Tu as accompli ton plan en %s.",
	["Cura"] = "Soigneur",
	["Cura a quien tenga el dolor de sombras; la pelea es corta."] = "Soignez celui qui subit la douleur de l'ombre ; le combat est court.",
	["Cura a sus ayudantes y a sí misma: interrúmpanla."] = "Elle soigne ses aides et se soigne elle-même : interrompez-la.",
	["Cura a todo tu grupo a la vez. Perfecta cuando a todos les pegan."] = "Soigne tout ton groupe d'un coup. Parfait quand tout le monde se fait frapper.",
	["Cura a tu grupo con un clic."] = "Soigne ton groupe en un clic.",
	["Cura a tu mascota poco a poco. Mantenla viva: ella te cuida."] = "Soigne ton familier peu à peu. Garde-le en vie : il veille sur toi.",
	["Cura con un clic y ese compañero queda seleccionado; limpia maldiciones y venenos con otro clic."] = "Soigne d'un clic et ce compagnon reste ciblé ; dissipe malédictions et poisons d'un autre clic.",
	["Cura de golpe y luego un rato más."] = "Soigne d'un coup puis encore un moment.",
	["Cura poco a poco. Ideal para alguien que recibe daño sin parar."] = "Soigne peu à peu. Idéal pour quelqu'un qui prend des dégâts sans arrêt.",
	["Cura poco a poco. Ponla en quien recibe daño."] = "Soigne peu à peu. Mets-le sur celui qui prend des dégâts.",
	["Curación"] = "Soins",
	["Curación con clic"] = "Soins en un clic",
	["Curación: arrastra para mover"] = "Soins : faites glisser pour déplacer",
	["Curandero"] = "Soigneur",
	["Curar con un clic"] = "Soigner en un clic",
	["Curar y seleccionar"] = "Soigner et cibler",
	["Curas"] = "Tu soignes",
	["Curas que van llegando"] = "Soins entrants",
	["Cursor"] = "Curseur",
	["Cuándo"] = "Quand",
	["Cuándo vuelve sola detrás de tu personaje."] = "Quand elle revient toute seule derrière votre personnage.",
	["Cuánta lluvia, nieve y polvo se ve cuando hay mal tiempo."] = "La quantité de pluie, de neige et de poussière visible par mauvais temps.",
	["Cuánta memoria usa cada parte de Alfa ahora, y suelta la que ya no ocupa. También con /alfa rendimiento."] = "Combien de mémoire chaque partie d'Alfa utilise en ce moment, et libère ce qui ne sert plus. Aussi avec /alfa rendimiento.",
	["Cuántas capas de sombra se dibujan: con más capas, las sombras nítidas llegan más lejos."] = "Le nombre de couches d'ombre dessinées : avec plus de couches, les ombres nettes portent plus loin.",
	["Cuántas casillas caben en cada fila."] = "Combien d'emplacements tiennent sur chaque ligne.",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "Le nombre d'emplacements libres restants quand Alfa vous prévient.",
	["Cuántas habilidades después"] = "Combien de techniques ensuite",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Combien de dégâts chaque blocage absorbe ; augmente aussi les dégâts de Heurt de bouclier.",
	["Cuánto dura un aviso en pantalla"] = "Durée d'affichage d'une alerte",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Le temps restant avant votre prochaine attaque automatique, pour chaque main. Aide à placer Heurtoir ou Frappe héroïque sans perdre de coups.",
	["Cuánto más brillan las luces que en una pantalla normal. El juego no pasa del máximo de tu monitor."] = "De combien les lumières brillent plus que sur un écran normal. Le jeu ne dépasse jamais le maximum de votre moniteur.",
	["Cuánto oro"] = "Combien d'or",
	["Cuánto pasto, flores y hierbas cubren el suelo."] = "La quantité d'herbe, de fleurs et de plantes qui couvrent le sol.",
	["Cuánto por debajo de lo que vale tiene que estar tu precio para avisarte."] = "De combien ton prix doit être sous sa valeur pour que je te prévienne.",
	["Cuánto se ve el fondo de las ventanas de chat; en cero solo queda el borde."] = "Visibilité du fond des fenêtres de discussion ; à zéro, seule la bordure reste.",
	["Cuánto te ayuda Alfa"] = "Combien Alfa t’aide",
	["Cuánto te falta para el 60 a tu ritmo, qué guías y mazmorras te tocan y cuánto avanzas cada día."] = "Ce qu'il te reste avant le 60 à ton rythme, quels guides et donjons t'attendent et combien tu avances chaque jour.",
	["Cuántos"] = "Combien",
	["Cuántos consejos"] = "Combien de conseils",
	["Cuántos en el top"] = "Combien dans le top",
	["Cuántos se anuncian"] = "Combien sont annoncés",
	["Cuántos tienes, en el cuadro de cada objeto"] = "Combien vous en avez, dans l'infobulle de chaque objet",
	["Cuántos van en cada columna (o fila) antes de empezar otra. 5 es un grupo por columna."] = "Combien en mettre dans chaque colonne (ou ligne) avant d'en commencer une autre. 5 donne un groupe par colonne.",
	["Cuéntame algo"] = "Raconte-moi quelque chose",
	["Cuéntame algo de aquí"] = "Raconte-moi quelque chose sur cet endroit",
	["Cuéntanos qué te parece en La Jauría."] = "Dis-nous ce que tu en penses sur La Jauría.",
	["Cálido"] = "Chaud",
	["Cámara"] = "Caméra",
	["Cámbialo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el juego lo lee en combate y fallaría."] = "Changez-le dans le menu du jeu : Options > %s > « %s ». Alfa ne le change pas pour vous : le jeu le lit en combat et provoquerait une erreur.",
	["Cólera de las bestias: tu mascota pega mucho más un rato."] = "Courroux bestial : votre familier frappe beaucoup plus fort pendant un moment.",
	["Cómo cambiarlo"] = "Comment le changer",
	["Cómo conseguir cualquier objeto, misión o PNJ, y qué guía te lleva ahí."] = "Comment obtenir n'importe quel objet, quête ou PNJ, et quel guide t'y mène.",
	["Cómo conseguir cualquier objeto, montura, PNJ, misión o lugar."] = "Comment obtenir n'importe quel objet, monture, PNJ, quête ou lieu.",
	["Cómo conseguirla"] = "Comment l'obtenir",
	["Cómo conseguirlo"] = "Comment l'obtenir",
	["Cómo decide Alfa"] = "Comment Alfa décide",
	["Cómo encenderlo"] = "Comment l'activer",
	["Cómo está tu plano: %s."] = "Ambiance sur ta couche : %s.",
	["Cómo hacer oro"] = "Comment gagner de l'or",
	["Cómo juego"] = "Ma façon de jouer",
	["Cómo se consigue"] = "Comment l'obtenir",
	["Cómo se ganan"] = "Comment les gagner",
	["Cómo se mueve"] = "Comment elle bouge",
	["Cómo se usa"] = "Mode d'emploi",
	["Cómo se ven las zonas sin descubrir"] = "Apparence des zones non découvertes",
	["Cómo subir"] = "Comment monter de niveau",
	["Cómo subirla"] = "Comment la monter",
	["Cómo trabaja tu ruta"] = "Comment fonctionne votre itinéraire",
	["Cómo ves Alfa"] = "Comment tu vois Alfa",
	["Cómprala con un vendedor."] = "Achetez-en chez un marchand.",
	["Cópialo con Ctrl+C y guárdalo, o pásaselo a la manada. Para traerlo de vuelta: «Importar»."] = "Copie-le avec Ctrl+C et garde-le, ou passe-le à la meute. Pour le récupérer : « Importer ».",
	["Cópialo con Ctrl+C. Luego abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y pégalo con Ctrl+V."] = "Copie-le avec Ctrl+C. Ouvre ensuite « Guilde et communautés », choisis %s, clique sur « Inviter un membre » et colle-le avec Ctrl+V.",
	["Cópialos con Ctrl+C y pégalos en tu reporte. «Reportar» ya los lleva."] = "Copie-les avec Ctrl+C et colle-les dans ton signalement. « Signaler » les inclut déjà.",
	["DPS"] = "DPS",
	["DPS del arma"] = "DPS de l'arme",
	["Daga"] = "Dague",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Nourrissez votre familier pour qu'il soit content et frappe plus fort.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Nourrissez-le pour qu'il soit heureux : il frappe plus fort.",
	["Dame clic derecho y elige «¿En qué te ayudo?» cuando quieras. ¡Buena caza, lobo!"] = "Fais un clic droit sur moi et choisis « Je t’aide pour quoi ? » quand tu veux. Bonne chasse, loup !",
	["Dar a las barras el estilo de Alfa"] = "Donner aux barres le style d'Alfa",
	["Dar al chat el estilo de Alfa"] = "Donner à la discussion le style d'Alfa",
	["Dar al minimapa el estilo de Alfa"] = "Donner à la minicarte le style d'Alfa",
	["Darle una salchicha"] = "Lui donner une saucisse",
	["Darnassus está en las ramas de Teldrassil. La suma sacerdotisa Tyrande Susurravientos gobierna desde el Templo de la Luna."] = "Darnassus se trouve dans les branches de Teldrassil. La grande prêtresse Tyrande Murmevent gouverne depuis le temple de la Lune.",
	["Dath'Remar Caminante del Sol guió a los altos elfos hasta Quel'Thalas. De su linaje viene el príncipe Kael'thas."] = "Dath'Remar Haut-Soleil a guidé les hauts-elfes jusqu'à Quel'Thalas. Le prince Kael'thas descend de sa lignée.",
	["Datos"] = "Données",
	["Datos curiosos"] = "Anecdotes",
	["Datos curiosos de Lya, escritos por Alfa."] = "Les anecdotes de Lya, écrites par Alfa.",
	["Daño"] = "Dégâts",
	["Daño a distancia"] = "Dégâts à distance",
	["Daño a todos los que están cerca de ti. Para cuando te rodean."] = "Des dégâts à tous ceux qui sont près de toi. Pour quand tu es encerclé.",
	["Daño arcano al instante y un rato más. Bueno para empezar o mientras corres."] = "Dégâts des arcanes instantanés, puis encore un moment. Bien pour ouvrir ou en courant.",
	["Daño con el tiempo: ponla al empezar la pelea."] = "Dégâts sur la durée : appliquez-le au début du combat.",
	["Daño de arcos, armas de fuego y ballestas."] = "Dégâts des arcs, armes à feu et arbalètes.",
	["Daño de escarcha que deja lento al enemigo. Perfecto si huye."] = "Dégâts de givre qui ralentissent l'ennemi. Parfait s'il fuit.",
	["Daño de escarcha que deja lento al enemigo. Tu hechizo para mantenerlo lejos."] = "Dégâts de givre qui ralentissent l'ennemi. Ton sort pour le garder à distance.",
	["Daño de fuego al instante. Úsalo para rematar o mientras te mueves."] = "Dégâts de feu instantanés. Utilise-le pour achever ou en mouvement.",
	["Daño de fuego con el tiempo."] = "Dégâts de feu sur la durée.",
	["Daño de fuego que quema un rato. Bueno para empezar la pelea."] = "Dégâts de feu qui brûlent un moment. Bien pour ouvrir le combat.",
	["Daño de sombra durante un buen rato. Ponla al inicio."] = "Dégâts d'ombre pendant un bon moment. Pose-le au début.",
	["Daño de sombra durante un rato. Ponla al inicio y sigue con otra cosa."] = "Dégâts d'ombre sur la durée. Pose-la au début et passe à autre chose.",
	["Daño de sombra fuerte. Buen golpe para empezar o para rematar."] = "Gros dégâts d'ombre. Un bon coup pour ouvrir ou achever.",
	["Daño de sombra que hace lento al enemigo. Canalízalo mientras se acerca."] = "Dégâts d'ombre qui ralentissent l'ennemi. Canalise-le pendant qu'il approche.",
	["Daño del arma"] = "Dégâts de l'arme",
