	["Daño directo de tus armas y habilidades."] = "Dégâts directs de vos armes et techniques.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Des dégâts en groupe de cinq : frapper fort sans voler les monstres au tank.",
	["Daño extra después de recibir críticos."] = "Dégâts en plus après avoir subi des critiques.",
	["Daño extra después de recibir un golpe crítico."] = "Dégâts en plus après avoir subi un coup critique.",
	["Daño o curas"] = "Dégâts ou soins",
	["Daño periódico"] = "Dégâts périodiques",
	["Daño por segundo"] = "Dégâts par seconde",
	["Daño rápido que también interrumpe hechizos. Úsalo con quien lanza magia."] = "Des dégâts rapides qui interrompent aussi les sorts. Utilise-le contre les lanceurs de sorts.",
	["Daño sagrado fuerte contra no-muertos y demonios."] = "Gros dégâts sacrés contre les morts-vivants et les démons.",
	["Daño sobre tus enemigos"] = "Dégâts au-dessus de vos ennemis",
	["De %d a %d"] = "De %d à %d",
