	["De 1 a 300"] = "De 1 à 300",
	["De 1 a 300, dónde pescar cerca de ti, equipo, cebos, misiones y el concurso."] = "De 1 à 300, où pêcher près de vous, équipement, appâts, quêtes et le concours.",
	["De 1 a 300: qué hacer, con qué y dónde aprender"] = "De 1 à 300 : quoi faire, avec quoi et où apprendre",
	["De 15 minutos a 4 horas."] = "De 15 minutes à 4 heures.",
	["De Forever"] = "Forever",
	["De La Jauría"] = "De La Jauría",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono. Lo que el juego hace brillar pasa al frente; las de área salen con varios enemigos peleando. Solo aparecen las que ya aprendiste."] = "De haut en bas : la première que le jeu vous laisse utiliser est celle de l'icône. Ce que le jeu fait briller passe devant ; les techniques de zone apparaissent quand vous combattez plusieurs ennemis. Seules celles que vous avez apprises apparaissent.",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "De haut en bas : la première que le jeu vous laisse utiliser est celle de l'icône ; celles de zone, seulement avec 3 ennemis ou plus en combat.",
	["De clase"] = "De classe",
	["De clase: %s"] = "De classe : %s",
	["De donde estés a cualquier lugar, con vuelos, barcos, zepelines, portales y a pie, y la lista de tramos."] = "D'où que tu sois vers n'importe où, avec vols, bateaux, zeppelins, portails et à pied, et la liste des étapes.",
	["De este lugar Lya todavía no sabe datos curiosos. Elige una misión de la lista para leer su historia."] = "Lya ne connaît pas encore d'anecdotes sur cet endroit. Choisissez une quête dans la liste pour lire son histoire.",
	["De este lugar todavía no sé mucho. ¿Vemos tus historias?"] = "Je ne sais pas encore grand-chose de cet endroit. On regarde tes histoires ?",
	["De fábrica el seguimiento muestra solo lo que estás haciendo; encendido, muestra el paso completo con sus notas."] = "Par défaut, le suivi n'affiche que ce que vous faites ; activé, il affiche toute l'étape avec ses notes.",
	["De la base de datos incluida"] = "De la base de données incluse",
	["De la otra facción"] = "Autre faction",
	["De los que se presumen"] = "De quoi se vanter",
	["De misión"] = "De quête",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "Du niveau %.1f au %.1f, avec environ %s d'or. Seulement des quêtes que vous pouvez déjà prendre ; ce qui demande plus de niveau vient après une étape qui l'attend.",
	["De noche Durotar refresca y se ven muchas estrellas desde Orgrimmar."] = "La nuit, Durotar se rafraîchit et on voit plein d'étoiles depuis Orgrimmar.",
	["De noche Teldrassil se llena de luciérnagas. Los elfos de la noche están en su hora."] = "La nuit, Teldrassil se remplit de lucioles. C'est l'heure des elfes de la nuit.",
	["De noche Un'Goro ruge. Los diablosaurios del cráter no duermen nunca."] = "La nuit, Un'Goro rugit. Les diablosaures du cratère ne dorment jamais.",
	["De noche Vallefresno brilla con luz de luna. Los furbolg duermen... casi todos."] = "La nuit, Orneval brille au clair de lune. Les furbolgs dorment... presque tous.",
	["De noche en Cuna del Invierno la aurora pinta el cielo. Vale la pena verla un ratito."] = "La nuit à Berceau-de-l'Hiver, l'aurore peint le ciel. Ça vaut le coup de la regarder un peu.",
	["De noche en Dun Morogh la nieve cruje bajo las patas. Me encanta ese sonido."] = "La nuit à Dun Morogh, la neige crisse sous les pattes. J'adore ce bruit.",
	["De noche en Elwynn se oyen los lobos del bosque. Tranquilo: son primos lejanos."] = "La nuit à Elwynn, on entend les loups de la forêt. Pas d'inquiétude : ce sont des cousins éloignés.",
	["De noche en Los Humedales croan las ranas y los raptores acechan entre los juncos."] = "La nuit dans les Paluns, les grenouilles coassent et les raptors rôdent dans les roseaux.",
	["De noche en Mulgore el viento canta entre las mesetas. Los tauren dicen que es la Madre Tierra."] = "La nuit à Mulgore, le vent chante entre les mesas. Les taurens disent que c'est la Terre-Mère.",
	["De noche en Tanaris la arena se enfría rápido. Cuidado con los escorpiones."] = "La nuit à Tanaris, le sable refroidit vite. Attention aux scorpions.",
	["De noche en el Bosque del Ocaso los worgen salen a cazar. No te separes de mí."] = "La nuit dans le bois de la Pénombre, les worgens sortent chasser. Ne t'éloigne pas de moi.",
	["De noche en las Tierras de la Peste los muertos caminan más. Quédate junto a la luz."] = "La nuit dans les Maleterres, les morts marchent davantage. Reste près de la lumière.",
	["De noche los Defias se mueven por los Páramos. Mira bien antes de entrar a una granja."] = "La nuit, les Défias rôdent dans la marche de l'Ouest. Regarde bien avant d'entrer dans une ferme.",
	["De todo %s, ¿qué rincón te gusta más?"] = "De tout %s, quel coin préfères-tu ?",
	["De tu gente todavía no sé mucho. ¿Te cuento otra cosa?"] = "Je ne sais pas encore grand-chose de ton peuple. Je te raconte autre chose ?",
	["De tu nivel al 60, a tu ritmo"] = "De ton niveau au 60, à ton rythme",
	["De vez en cuando Lya te pide una. Te las tiene bien contadas."] = "De temps en temps, Lya t'en demande une. Elle les compte bien.",
	["Debajo del ícono: útil mientras aprendes."] = "Sous l'icône : pratique pendant l'apprentissage.",
	["Dedo"] = "Doigt",
	["Defensa"] = "Défense",
	["Deja Alt abajo y pasa el ratón por cualquier cosa de Alfa: te digo para qué sirve. La tecla se cambia en Estilo y sonido."] = "Garde Alt enfoncée et survole n'importe quoi d'Alfa : je te dis à quoi ça sert. La touche se change dans Style et son.",
	["Deja esta tecla abajo y pasa el ratón por cualquier cosa de Alfa: te digo para qué sirve."] = "Garde cette touche enfoncée et survole n'importe quoi d'Alfa : je te dis à quoi ça sert.",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "Laissez le tank frapper quelques secondes avant d'utiliser vos gros coups.",
	["Deja que la manada te vea en el mapa"] = "Laisse la meute te voir sur la carte",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "Laissez votre familier commencer le combat et tirez quand le monstre l'attaque.",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Ne garde que l'essentiel : vous, votre groupe, vos marqueurs et la prochaine étape du guide.",
	["Deja una nota en tu mapa donde estás (/alfa nota <texto>)"] = "Laisse une note sur ta carte là où tu es (/alfa nota <texte>)",
