	["Dentro de %s (mazmorra)"] = "Dans %s (donjon)",
	["Dentro de la mazmorra"] = "Dans le donjon",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "Les donjons et les villes n'ont pas de nœuds. Sortez dans le monde et votre itinéraire se crée en un clic.",
	["Dentro de una instancia el juego no deja compartir: sale solo cuando salgas."] = "Dans une instance, le jeu ne permet pas de partager : c'est envoyé tout seul à votre sortie.",
	["Dentro de una instancia no hay planos."] = "Il n'y a pas de couches dans une instance.",
	["Dentro de una instancia no se puede seguir a nadie."] = "Impossible de suivre quelqu'un à l'intérieur d'une instance.",
	["Dentro de una mazmorra, al apuntar a un jefe sale una tarjeta chica con lo que te toca según tu papel y cómo van tus misiones de ahí. No atrapa clics."] = "Dans un donjon, cibler un boss affiche une petite carte avec ce que ton rôle doit faire et où en sont tes quêtes de l'endroit. Elle n'intercepte aucun clic.",
	["Dentro de una mazmorra, apunta al jefe: arriba te sale una tarjeta con lo que te toca según tu papel y cómo van tus misiones de ahí."] = "Dans un donjon, cible le boss : une carte s'affiche en haut avec ce que ton rôle doit faire et où en sont tes quêtes de l'endroit.",
	["Depositar"] = "Déposer",
