	["Desde el nivel 20, desuellas bestias de hasta tu habilidad dividida entre 5. Necesitas un cuchillo de desollar."] = "À partir du niveau 20, tu dépèces des bêtes jusqu'à ta compétence divisée par 5. Il te faut un couteau à dépecer.",
	["Desde el sigilo y por la espalda: lo hace sangrar un buen rato."] = "Depuis le camouflage et de dos : il saigne un bon moment.",
	["Desde el sigilo y por la espalda: un golpe enorme para empezar."] = "Depuis le camouflage et de dos : un énorme coup d'ouverture.",
	["Desde el sigilo: aturde al enemigo unos segundos para empezar con ventaja."] = "Depuis le camouflage : étourdit l'ennemi quelques secondes pour commencer avec l'avantage.",
	["Desde hoy apunto cada paso grande que demos juntos."] = "À partir d'aujourd'hui, je note chaque grand pas qu'on fait ensemble.",
	["Desde nivel %d"] = "Dès le niveau %d",
	["Desde siempre"] = "Depuis toujours",
	["Desde tu última visita también hubo cambios en %s: los ves en «Ver todo lo nuevo»."] = "Depuis ta dernière visite, il y a aussi eu des changements dans %s : tu les trouveras dans « Voir toutes les nouveautés ».",
	["Desencanta los objetos verdes y azules que no uses para sacar polvos, esencias y fragmentos."] = "Désenchante les objets verts et bleus que tu n'utilises pas pour obtenir des poussières, des essences et des éclats.",
	["Desencantar ≈ %s"] = "Désenchanter ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "Désenchanter : ≈ %s par objet%s. Nécessite Enchantement %d.",
	["Deseo de muerte: mucho más daño un rato; úsalo en peleas largas."] = "Souhait mortel : beaucoup plus de dégâts pendant un moment ; utilisez-le dans les longs combats.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "Pourfendre fait plus de dégâts pendant que le monstre saigne ; il vous le faut pour Blessures profondes.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "Pourfendre fait plus de dégâts ; il vous le faut pour Blessures profondes.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "Pourfendre vous prépare plus de Fulgurances : plus de coups impossibles à esquiver.",
	["Deshacer"] = "Annuler",
	["Deshacer preajuste"] = "Annuler le préréglage",
	["Desmarca las metas hechas de este personaje (las que ya se cumplen se vuelven a marcar solas)."] = "Décoche les objectifs faits de ce personnage (ceux déjà remplis se recochent tout seuls).",
	["Desmarcar"] = "Décocher",
	["Desollar es de las formas más fáciles de hacer oro mientras subes de nivel."] = "Le Dépeçage est l'un des moyens les plus faciles de gagner de l'or en montant de niveau.",
	["Desollar y Peletería van de la mano: tú consigues el cuero y tú lo trabajas."] = "Le Dépeçage et le Travail du cuir vont de pair : tu récupères le cuir et tu le travailles.",
	["Despojar más rápido"] = "Fouiller plus vite",
	["Después"] = "Plus tard",
	["Después de"] = "Après",
	["Después de cada golpe, regresa a tu lugar rápido."] = "Après chaque projection, revenez vite à votre place.",
	["Después de estos siguen %d más."] = "%d autres suivent ceux-ci.",
	["Después de otra"] = "Après une autre",
	["Después de tu segunda pelea, aquí ves la de antes."] = "Après votre deuxième combat, vous voyez ici le précédent.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "Après un critique, vous attaquez plus vite : plus de coups, plus de rage.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "Après lui, les braseros de l'autel s'allument et des vagues d'ennemis arrivent : préparez-vous avant.",
	["Después del combate"] = "Après le combat",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "Après le premier boss, un prisonnier de votre faction ouvre la porte : parlez-lui.",
	["Después sigue"] = "Ensuite",
