	["Después: %s"] = "Ensuite : %s",
	["Después: nivel %d"] = "Après : niveau %d",
	["Destierra a un demonio o elemental un rato. Buen control en mazmorras."] = "Bannit un démon ou un élémentaire un moment. Bon contrôle en donjon.",
	["Destino"] = "Destination",
	["Destrucción"] = "Destruction",
	["Destrucción para subir"] = "Destruction pour monter",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "Vous dépecez ce que vous tuez et le transformez en armures de cuir pour vous ; le reste se vend.",
	["Desuello"] = "Dépeçage",
	["Desuello es su mejor pareja. Los hilos y la sal los venden los proveedores de peletería."] = "Le Dépeçage est son meilleur partenaire. Les fournisseurs de travail du cuir vendent le fil et le sel.",
	["Desvanecer objetos lejanos"] = "Estomper les objets lointains",
