	["Errores de Lua de Alfa en esta sesión:"] = "Erreurs Lua d'Alfa pendant cette session :",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "Erreurs Lua d'Alfa pendant cette session : aucune",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Le donjon est court et se trouve dans Stormwind. Les prisonniers sont dans des cellules de chaque côté : avancez lentement.",
	["Es de la otra facción"] = "Elle est de l'autre faction",
	["Es de una misión."] = "C'est un objet de quête.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "C'est le boss demandé par une quête de l'Alliance : vérifiez vos quêtes avant d'entrer.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "C'est le premier boss, et il est simple. À sa mort, le prisonnier de votre faction ouvre la porte de la cour.",
	["Es el primer reto: con él se abre el Legado."] = "C'est le premier défi : il débloque l'Héritage.",
	["Es el punto %d de %d de tu build."] = "C'est le point %d sur %d de votre build.",
	["Es el que toca ahora."] = "C'est celui à prendre maintenant.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "C'est le dernier du Cimetière. Il lance des flammes autour de lui : si vous combattez à distance, restez loin.",
	["Es el único lobo a la vista."] = "C'est le seul loup en vue.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Il est grand et on s'y perd facilement : suivez une seule personne et ne partez pas seul.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "C'est la machine de Sneed : détruisez-la et il sortira se battre.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "C'est le premier donjon de la Horde : court et idéal pour apprendre à jouer en groupe.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "C'est le premier grand donjon de l'Alliance : avancez lentement et attirez un groupe à la fois.",
	["Es la que más vale al venderla."] = "C'est celle qui se vend le plus cher.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Il est long et a deux entrées. Beaucoup d'ennemis sont en pierre et frappent fort.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Il est long et plein de robots : certains posent des bombes ou déclenchent des alarmes qui font venir plus d'ennemis.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Il est lent : si vous combattez à distance, attaquez-le pendant qu'il approche.",
	["Es muy veloz: frénalo si tu clase puede."] = "Il est très rapide : ralentissez-le si votre classe le peut.",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "C'est facultatif. Si tu dis oui, les loups de La Jauría qui utilisent Alfa voient ton personnage sur la carte de WoW, comme tu vois ton groupe, et peuvent te rejoindre avec la flèche ; et toi de même. Alfa partage seulement où se trouve ton personnage dans le jeu : la zone, le point sur la carte, son niveau et sa classe. Rien de ta position réelle, de ton ordinateur ni de ton compte.",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Va por un canal oculto que no sale en el chat, aunque alguien que entre a él con otro addon podría verlo. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "C'est facultatif : votre personnage apparaît sur la carte de WoW des loups de La Jauría qui utilisent Alfa, et eux sur la vôtre, pour vous retrouver et les rejoindre avec la flèche. Seul l'endroit où se trouve votre personnage dans le jeu est partagé (zone, point sur la carte, niveau et classe), jamais votre position réelle ni rien de votre ordinateur, et jamais en donjon. Cela passe par un canal caché qui n'apparaît pas dans le chat, même si quelqu'un qui le rejoint avec un autre addon pourrait le voir. Votre groupe est toujours visible. Vous le changez quand vous voulez dans La Jauría.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "C'est pour les niveaux %s et vous êtes niveau %d : encore %d niveaux.",
	["Es para otra raza."] = "C'est pour une autre race.",
	["Es raro del Cementerio y no siempre aparece."] = "C'est un rare du Cimetière, il n'apparaît pas toujours.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "C'est un rare du Cimetière, il n'apparaît pas toujours. Il empoisonne : guérissez le poison.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "C'est un rare du Cimetière, il n'apparaît pas toujours. Il peut réduire au silence les lanceurs de sorts.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "C'est un rare qui se montre peu. Il utilise du feu autour de lui.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "C'est un rare, caché dans une grotte. C'est une chauve-souris qui frappe vite.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "C'est un rare, il n'apparaît pas toujours. Il frappe très fort pour son niveau : attirez-le avec prudence.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "C'est un rare, il n'est pas toujours là. Il frappe fort tous ceux qui sont devant lui.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "C'est un rare. Il pose un totem de terre : détruisez-le.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "C'est un rare, il n'est pas toujours là. Il endort les joueurs et explose de magie autour de lui.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Il est simple : bon moment pour boire avant le dernier boss.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "C'est un lanceur de sorts : interrompez-le si votre classe le peut (Coup de pied, Coup de bouclier, Horion de terre...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "C'est un chaman avec des totems : détruisez les totems, ils meurent vite.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "C'est un nain avec un bouclier : il encaisse beaucoup, mais sans surprise.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "C'est un ennemi coriace de la mine : traitez-le comme un petit boss.",
	["Es un grupo: cada uno suelta su propio botín."] = "C'est un groupe : chacun laisse tomber son propre butin.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "C'est un paladin : il se soigne avec Lumière sacrée. Interrompez son soin.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "C'est un satyre rapide qui empoisonne : si votre classe guérit les poisons, faites-le.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "C'est un trogg qui lance des éclairs : interrompez-le.",
	["Es una mejora para ti"] = "C'est une amélioration pour vous",
	["Es una mejora para ti."] = "C'est une amélioration pour toi.",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "C'est une monture de votre classe : demandez à votre maître de classe quand et comment l'obtenir.",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "C'est une tortue géante très cuirassée : elle frappe lentement mais fort.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "C'est une tortue très résistante, mais elle ne fait que frapper : aucune surprise.",
	["Es viejo: escanea para tenerlo al día."] = "Il est ancien : scanne pour le mettre à jour.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "Cette chaîne ne contient aucune statistique notée par Alfa.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Cette rangée n'est pas encore ouverte : il manque des points dans cette branche.",
	["Esa tecla ya tiene dueño"] = "Cette touche est déjà prise",
	["Esa ya me la diste, ¡gracias! Guárdame la siguiente."] = "Celle-là, tu me l'as déjà donnée, merci ! Garde-moi la prochaine.",
	["Esbirros enemigos"] = "Serviteurs ennemis",
	["Escala de estadísticas"] = "Échelle de statistiques",
	["Escalas:"] = "Escales :",
	["Escaneando..."] = "Scan en cours...",
	["Escanear ahora"] = "Scanner maintenant",
	["Escanear con Alfa"] = "Scanner avec Alfa",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Scan complet : %s objets avec un prix (%s enchères).",
	["Escarcha"] = "Givre",
	["Escarcha en cono frente a ti que hace lentos a los enemigos."] = "Du givre en cône devant toi qui ralentit les ennemis.",
	["Escarcha para subir"] = "Givre pour monter",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Masque les barres de nom et les noms des PNJ pendant la pêche (les ennemis hostiles gardent leur nom), pour mieux voir et atteindre le flotteur.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Masque ce qui demande plus de compétence que vous n'en avez. Sans cela, ils s'affichent en gris et pâles.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "Tape %s ou clique sur le loup de la minicarte pour l'ouvrir. Elle s'ouvre sur Aujourd'hui, avec ce dont ta classe a besoin ; %s affiche ou masque la fenêtre du guide.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "Tapez %s et dites-le-nous sur le Discord de La Jauría.",
	["Escribe /alfa diagnostico: reviso si otro addon choca con Alfa, si falta una parte o si un ajuste quedó raro, y te doy el arreglo a un clic."] = "Tape /alfa diagnostico : je vérifie si un autre addon entre en conflit avec Alfa, s'il manque une partie ou si un réglage est étrange, et je te donne la solution en un clic.",
	["Escribe /alfa teclas: ahí están todas, y con un clic pulsas la que quieras."] = "Tape /alfa teclas : elles y sont toutes, et d'un clic tu appuies sur celle que tu veux.",
	["Escribe al menos 3 letras del objeto."] = "Tape au moins 3 lettres de l'objet.",
	["Escribe al menos dos letras."] = "Tapez au moins deux lettres.",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. Un clic en la marca y la flecha te lleva."] = "Écris quelque chose et appuie sur « Note ici » : elle reste sur ta carte là où tu es. Un clic sur la marque et la flèche t'y mène.",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. «Spot aquí» marca un buen lugar para farmear, en dorado. Un clic en la marca y la flecha te lleva."] = "Écris quelque chose et appuie sur « Note ici » : ça reste sur ta carte là où tu es. « Spot ici » marque un bon endroit pour farmer, en doré. Un clic sur la marque et la flèche t'y mène.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "Tapez le nom d'un donjon ci-dessus pour le trouver.",
	["Escribe cuánto oro (1 o más)."] = "Indiquez combien d'or (1 ou plus).",
	["Escribe el número que quieras y presiona Enter."] = "Tapez le nombre voulu et appuyez sur Entrée.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "Écrit le top %d dans la discussion de votre groupe ou raid.",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "Écrit dans la discussion de groupe quand tu termines un objectif d'une quête partagée. Désactivé par défaut pour ne remplir la discussion de personne.",
	["Escribe lo que buscas: un ajuste, o algo del juego, y te lo busco en la Enciclopedia."] = "Écris ce que tu cherches : un réglage ou quelque chose du jeu, et je te le cherche dans l'Encyclopédie.",
	["Escribe qué buscas: «Minas de la Muerte, falta sanador»."] = "Écris ce que tu cherches : « Mortemines, il manque un soigneur ».",
	["Escribe qué dice la nota: /alfa nota Aquí sale el mineral"] = "Écris ce que dit la note : /alfa nota Il y a du minerai ici",
	["Escribe qué se farmea ahí: /alfa spot Lobos para pieles"] = "Écris ce qu'on y farme : /alfa spot Loups pour les peaux",
	["Escribe qué van a hacer (una mazmorra, una misión, lo que sea)."] = "Écris ce que vous allez faire (un donjon, une quête, n'importe quoi).",
	["Escribe tu nota."] = "Écrivez votre note.",
	["Escribe un nivel (2 o más)."] = "Indiquez un niveau (2 ou plus).",
	["Escribe un nombre corto para reconocerla."] = "Tapez un nom court pour le reconnaître.",
	["Escribe un nombre para este conjunto."] = "Écrivez un nom pour cet ensemble.",
	["Escribe un objeto y pulsa «Buscar»: te contestan los lobos de tu hermandad que lo permiten."] = "Tape un objet et appuie sur « Rechercher » : les loups de ta guilde qui l'autorisent te répondent.",
	["Escribir a %s"] = "Écrire à %s",
	["Escuchar"] = "Écouter",
	["Escuchar el aullido"] = "Écouter le hurlement",
	["Escudo"] = "Bouclier",
	["Escudo de relámpagos"] = "Bouclier de foudre",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Bouclier et défense : vous retenez tous les monstres pour que votre groupe ne souffre pas.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Bouclier et lumière sacrée : un tank très résistant qui récupère son propre mana.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Boucliers et soins préventifs : vous encaissez beaucoup et soutenez le groupe.",
	["Ese build es para otra clase."] = "Ce build est pour une autre classe.",
	["Ese día ni la manada te alcanzaba."] = "Ce jour-là, même la meute ne pouvait pas te suivre.",
	["Ese respaldo ya no está."] = "Cette sauvegarde n'existe plus.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Ce talent exige d'abord un autre talent complet (la flèche de l'arbre).",
	["Ese texto es demasiado largo para un build."] = "Ce texte est trop long pour un build.",
	["Ese texto es demasiado largo para una cadena de escala."] = "Ce texte est trop long pour une chaîne d'échelle.",
	["Ese texto no es un perfil de Alfa. Copia el que da «Exportar» completo."] = "Ce texte n'est pas un profil Alfa. Copie en entier le texte que donne « Exporter ».",
	["Ese texto no es una ruta de Alfa."] = "Ce texte n'est pas un itinéraire d'Alfa.",
	["Esmeralda"] = "Émeraude",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Ce n'est pas une chaîne de build d'Alfa. Elle commence par ALFA1;",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "Ce n'est pas une chaîne d'échelle de statistiques. Elle commence par ( Pawn: v1: \"Nom\": ...",
	["Eso se puede al salir de combate."] = "C'est possible une fois sorti du combat.",
	["Espacio"] = "Espace",
	["Espacio libre"] = "Espace libre",
	["Espacio y dinero"] = "Place et argent",
	["Espacios libres para el botín"] = "Places libres pour le butin",
