	["Español, inglés y siete idiomas más, en toda la interfaz."] = "Espagnol, anglais et sept autres langues, dans toute l'interface.",
	["Espera %s"] = "Attendez %s",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "Attendez que le tank ait bien l'ennemi en main avant de frapper fort.",
	["Espera a que termine el combate."] = "En attente de la fin du combat.",
	["Espera a salir de combate para probarla."] = "Attendez d'être hors combat pour la tester.",
	["Espera a salir de combate."] = "Attendez d'être hors combat.",
	["Espera a terminar de entrar al juego."] = "Attendez d'être entièrement connecté.",
	["Espera de unos %d min; va a %s"] = "Environ %d min d'attente ; va à %s",
	["Espera unos segundos antes de buscar otra vez."] = "Attends quelques secondes avant de chercher à nouveau.",
	["Espera unos segundos antes de volver a poner tu anuncio."] = "Attends quelques secondes avant de reposter ton annonce.",
	["Espera · nivel %d"] = "En attente · niveau %d",
	["Esperando"] = "En attente",
