	["Espíritu"] = "Esprit",
	["Esquiva"] = "Esquive",
	["Esquivar"] = "Esquive",
	["Esquivas casi todo unos segundos. Tu salvavidas cuando te pegan muchos."] = "Tu esquives presque tout pendant quelques secondes. Ta bouée quand beaucoup te frappent.",
	["Esquivas más cuerpo a cuerpo. Úsalo si el enemigo te alcanza."] = "Tu esquives plus au corps à corps. Utilise-le si l'ennemi t'atteint.",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "Cette classe n'a pas de pondérations de statistiques dans Alfa.",
	["Esta clase no tiene pesos de estadísticas."] = "Cette classe n'a pas de pondérations de statistiques.",
	["Esta es Hoy"] = "Voici Aujourd'hui",
	["Esta explicación no saldrá más. En Combate puedes volver a encenderlas."] = "Cette explication ne s'affichera plus. Vous pouvez les réactiver dans Combat.",
	["Esta guía no tiene un paso para ti ahora"] = "Ce guide n’a pas d’étape pour toi en ce moment",
	["Esta guía no tiene un paso para ti ahora: puede que hayas omitido lo que queda o que aún no te toque. Elige otra guía o vuelve a esta más adelante."] = "Ce guide n’a pas d’étape pour toi maintenant : tu as peut-être sauté le reste ou ce n’est pas encore ton tour. Choisis un autre guide ou reviens plus tard.",
	["Esta misión va sola: no pide otra ni abre otra."] = "Cette quête est seule : elle n'en demande ni n'en débloque aucune autre.",
	["Esta semana llevas %s"] = "Cette semaine tu en es à %s",
	["Esta semana todavía no cazamos nada. ¿Salimos?"] = "On n’a encore rien chassé cette semaine. On y va ?",
	["Esta semana, entre %d lobos: %s"] = "Cette semaine, entre %d loups : %s",
	["Esta sesión"] = "Cette session",
	["Esta sesión, por recurso"] = "Cette session, par ressource",
	["Esta sesión: %d capturas de %d lanzamientos. Desde siempre: %d."] = "Cette session : %d prises sur %d lancers. Depuis toujours : %d.",
	["Esta sesión: %s"] = "Cette session : %s",
	["Esta sesión: +%s"] = "Cette session : +%s",
	["Esta sesión: +%s · %s por hora"] = "Cette session : +%s · %s par heure",
	["Esta subasta no permite el escaneo completo."] = "Cet hôtel des ventes ne permet pas le scan complet.",
	["Esta va de %s y %s… ¿Te la cuento?"] = "Au programme : %s et %s… Je te la raconte ?",
	["Esta va de %s y de lobos… me toca de cerca. ¿Te la cuento?"] = "Au programme : %s et des loups… ça me touche de près. Je te la raconte ?",
	["Esta vez conviene el ángel."] = "Cette fois, l'esprit guérisseur vaut mieux.",
	["Esta zona"] = "Cette zone",
	["Esta zona huele a aventura. ¿Tú qué hueles?"] = "Cette zone sent l'aventure. Et toi, tu sens quoi ?",
	["Establos"] = "Maître des écuries",
	["Estadísticas"] = "Caractéristiques",
	["Estadísticas [pesca]"] = "Statistiques",
	["Este aviso ya no mostrará texto: solo el ícono. En Combate puedes volver a encenderlos."] = "Cette alerte n'affichera plus de texte : seulement l'icône. Vous pouvez les réactiver dans Combat.",
	["Este banco no vende más espacio."] = "Cette banque ne vend plus de place.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Ce build frappe extrêmement fort, mais encaisse peu : choisissez bien le moment d'entrer.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "Ce clic ne fait rien. Choisissez-lui une action dans Votre souris, sur la page Soins.",
	["Este cliente no carga los mosaicos del minimapa: se ve el arte pintado."] = "Ce client ne charge pas les tuiles de la minicarte : l'art peint s'affiche.",
	["Este cliente no da el arte del mapa"] = "Ce client ne fournit pas les images de la carte",
	["Este cliente no deja compartir"] = "Ce client ne permet pas de partager",
	["Este cliente no deja compartir marcadores."] = "Ce client ne permet pas de partager des marqueurs.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Ce client ne peut pas copier votre configuration tout seul : la fenêtre de lancement par clic de Blizzard s'est ouverte pour que vous la fassiez là.",
	["Este cliente no tiene %d de estos ajustes: no se muestran."] = "Ce client n'a pas %d de ces réglages : ils ne sont pas affichés.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "Ce client n'a pas le lancement par clic de Blizzard. Vos clics fonctionnent sur les cadres d'Alfa.",
	["Este paso"] = "Cette étape",
	["Este paso es para cerrar tus misiones de %s. Cuando estés allá, «Llévame» te lleva a cada una."] = "Cette étape sert à terminer tes quêtes en %s. Une fois là-bas, « M'y emmener » te guide vers chacune.",
	["Este paso no tiene punto en el mapa."] = "Cette étape n'a pas de point sur la carte.",
	["Este paso une el Bosque del Ocaso con el Pantano de las Penas, y casi todos lo cruzan sin detenerse."] = "Ce passage relie le bois de la Pénombre au marais des Chagrins, et presque tout le monde le traverse sans s'arrêter.",
	["Este talento no está en tu build."] = "Ce talent ne fait pas partie de votre build.",
	["Este tramo quedó vacío."] = "Ce tronçon est vide.",
