	["Estilo del minimapa"] = "Style de la minicarte",
	["Estilo y sonido"] = "Style et son",
	["Esto está lleno de cazadores"] = "C'est plein de chasseurs ici",
	["Esto huele a historia grande. Pon atención."] = "Ça sent la grande histoire. Fais bien attention.",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Impossible de changer cela en combat. Réessayez à la fin du combat.",
	["Esto no se puede vincular."] = "Impossible de créer un lien pour ceci.",
	["Esto te sirve más en el banco o con otro de tus personajes (mándaselo por correo). Con un banquero, se guarda con un clic."] = "Ceci te sert plus à la banque ou chez un autre de tes personnages (envoie-le par courrier). Chez un banquier, ça se range en un clic.",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "Ces filtres sont dessinés par Alfa, pas par le jeu : ils restent derrière toute l'interface (sans jamais la couvrir) et se voient aussi interface masquée (Alt+Z), pour vos captures.",
	["Está en combate. Prueba en un momento."] = "Il est en combat. Réessaie dans un instant.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Il est dans le Cimetière. Il inflige une douleur de l'ombre qui fait des dégâts sur la durée.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Il est dans l'eau, près de la cascade : amenez-le sur la terre ferme avant de combattre.",
	["Está en la %s, otro plano de tu zona."] = "Il est dans la %s, une autre couche de ta zone.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Il est dans l'Armurerie. Quand il crie, il tournoie avec sa hache et frappe tous ceux qui sont proches : éloignez-vous.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Il est dans la Bibliothèque et arrive avec ses chiens : tuez-les d'abord ou utilisez des attaques de zone.",
	["Está en tu lista de compras."] = "C'est sur ta liste de courses.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Il est caché dans la Cathédrale. Il lance des malédictions et se soigne : interrompez-le.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Il est plein de hurans et de tunnels d'épines : attirez-en peu à la fois.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Il est entouré de gobelins au travail : attirez d'abord ces gobelins, un par un.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Il est entouré de murlocs : attirez ses amis avant lui.",
	["Están apagadas en tu lista de addons: %s. Sin ellas faltan páginas de Alfa."] = "Elles sont désactivées dans ta liste d'addons : %s. Sans elles, il manque des pages à Alfa.",
	["Están encendidas pero el juego no las cargó: %s. Recarga; si siguen así, reinstala Alfa completo."] = "Elles sont activées mais le jeu ne les a pas chargées : %s. Recharge ; si ça continue, réinstalle Alfa en entier.",
	["Están por quitártelo"] = "Tu vas le perdre",
	["Estás aquí"] = "Vous êtes ici",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Vous êtes chez un banquier : depuis sa fenêtre, déposez ce que vous voulez en un clic.",
	["Estás con un banquero: «Al banco» los deposita con un clic, o toca uno para guardar solo ese."] = "Tu es chez un banquier : « À la banque » les dépose en un clic, ou touche-en un pour ne ranger que lui.",
	["Estás dentro"] = "Vous êtes à l'intérieur",
	["Estás descansando"] = "Tu es au repos",
	["Estás en %s. %s Abajo tienes lo que más me preguntan de aquí."] = "Tu es dans %s. %s En dessous, ce qu’on me demande le plus ici.",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Vous êtes en combat. Les talents ne se changent que hors combat : finissez le combat et réessayez.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Vous êtes en combat : cherchez l'équipement à la fin du combat.",
