	["Gratis tras vencer a un enemigo, y te cura."] = "Gratuite après avoir vaincu un ennemi, et elle vous soigne.",
	["Grifos"] = "Griffons",
	["Grim Batol fue una ciudad enana. Después, los orcos Faucedraco la usaron para tener presa a Alexstrasza, la Reina Dragón."] = "Grim Batol était une cité naine. Plus tard, les orcs Gueule-de-dragon s'en sont servis pour retenir Alexstrasza, la Reine-dragon.",
	["Grito de batalla"] = "Cri de guerre",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "Cri de guerre pour le guerrier ; Intelligence des Arcanes et une armure pour le mage ; Robustesse et Feu intérieur pour le prêtre ; et ce qu'il faut pour chaque classe.",
	["Grom Grito Infernal fue el primer jefe orco en beber la sangre de Mannoroth, y así ató a su pueblo a los demonios."] = "Grom Hurlenfer fut le premier chef orc à boire le sang de Mannoroth, et il a ainsi lié son peuple aux démons.",
	["Grom Grito Infernal y Varian Wrynn son guerreros legendarios de la historia."] = "Grom Hurlenfer et Varian Wrynn sont des guerriers légendaires de l'histoire.",
	["Grom'gol es el campamento de la Horda en la Vega, con zepelines a Orgrimmar y a Entrañas."] = "Grom'gol est le campement de la Horde dans la vallée de Strangleronce, avec des zeppelins pour Orgrimmar et Fossoyeuse.",
	["Grupo"] = "Groupe",
	["Grupo de %d"] = "Groupe de %d",
	["Grupo de 5"] = "Groupe de 5",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "Gardez %d quêtes : vous les rendrez dans un guide suivant.",
	["Guarda Grito intimidador para cuando estés en peligro."] = "Gardez Cri d'intimidation pour quand vous êtes en danger.",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "Gardez Mur protecteur pour les pires moments du boss.",
	["Guarda cómo tienes Alfa ahora con el nombre de tu personaje, para volver a ella con un clic. Útil si juegas con varios personajes."] = "Enregistre ta configuration actuelle d'Alfa sous le nom de ton personnage, pour y revenir en un clic. Pratique si tu joues plusieurs personnages.",
	["Guarda en el banco los materiales que todavía no usas, y deja las bolsas libres para el botín."] = "Range à la banque les matériaux que tu n'utilises pas encore, et garde tes sacs libres pour le butin.",
	["Guarda lo que llevas como un conjunto (curar, daño, pesca...) desde el botón de tus bolsas o en Bolsas, y póntelo con un clic. En combate te lo pongo al terminar."] = "Enregistre ce que tu portes comme ensemble (soins, dégâts, pêche...) depuis le bouton de tes sacs ou dans Sacs, et équipe-le d'un clic. En combat, je te l'équipe à la fin.",
	["Guarda lo que llevas puesto con un nombre (curar, daño, pesca...) y póntelo con un clic, fuera de combate."] = "Enregistre ce que tu portes sous un nom (soins, dégâts, pêche...) et équipe-le d'un clic, hors combat.",
	["Guarda lo que llevas puesto con un nombre (curar, daño, pesca...) y vuelve a ponértelo con un clic. También desde el botón de tus bolsas."] = "Enregistre ce que tu portes sous un nom (soins, dégâts, pêche...) et remets-le d'un clic. Aussi depuis le bouton de tes sacs.",
	["Guarda o cambia tu mascota"] = "Mettez votre familier à l'écurie ou changez-en",
	["Guarda tu configuración como perfil primero."] = "Enregistre d'abord ta configuration comme profil.",
	["Guarda tus materiales en el banco (%d)."] = "Dépose tes composants à la banque (%d).",
	["Guarda un poco de tela para vendas: Primeros auxilios también la usa."] = "Garde un peu de tissu pour les bandages : le Secourisme en utilise aussi.",
