	["Guiarme"] = "Me guider",
	["Gul'dan fue el primer brujo orco, y su historia no terminó nada bien. Tú úsalo con más cabeza."] = "Gul'dan fut le premier démoniste orc, et son histoire a très mal fini. Toi, utilise ce pouvoir avec plus de sagesse.",
	["Gul'dan fundó el Consejo de la Sombra, un grupo de brujos que movía a la Horda desde las sombras."] = "Gul'dan a fondé le Conseil des ombres, un groupe de démonistes qui tirait les ficelles de la Horde dans l'ombre.",
	["Guía"] = "Guide",
	["Guía a tu manada"] = "Guide ta meute",
	["Guía abierta en una pestaña nueva: sigue la flecha."] = "Guide ouvert dans un nouvel onglet : suivez la flèche.",
