	["Habilidades más baratas."] = "Techniques moins chères.",
	["Habilidades más baratas: más golpes de amenaza."] = "Techniques moins chères : plus de coups de menace.",
	["Habilidades nuevas por aprender: %d. Tu entrenador te espera."] = "Nouvelles techniques à apprendre : %d. Ton maître t'attend.",
	["Habilidades por entrenar"] = "Compétences à apprendre",
	["Habilidades que vigila la ayuda de Blizzard"] = "Techniques surveillées par l'assistant de combat de Blizzard",
	["Habitual"] = "Habituel",
	["Habla con %s"] = "Parlez à %s",
	["Habla con el maestro de vuelo de cada pueblo nuevo: así aprendes la ruta."] = "Parle au maître de vol de chaque nouvelle ville : c'est ainsi que tu apprends la route.",
	["Habla con un banquero para comprarla."] = "Parlez à un banquier pour l'acheter.",
	["Hablar"] = "Parler",
	["Hace heridas que sangran: vigila la vida del tanque."] = "Il inflige des blessures qui saignent : surveillez la vie du tank.",
	["Hace lento al enemigo cuerpo a cuerpo. Después aléjate y dispara."] = "Ralentit l'ennemi au corps à corps. Ensuite, recule et tire.",
	["Hace mil años, en la Guerra de las Arenas Movedizas, los elfos y los dragones encerraron a los qiraji tras el Muro del Escarabajo."] = "Il y a mille ans, pendant la guerre des Sables changeants, les elfes et les dragons ont enfermé les Qiraji derrière le mur du Scarabée.",
	["Hace más de diez mil años todas las tierras eran un solo continente: Kalimdor, que en élfico quiere decir «tierra de la eterna luz de las estrellas»."] = "Il y a plus de dix mille ans, toutes les terres formaient un seul continent : Kalimdor, qui en elfique veut dire « terre de la lumière éternelle des étoiles ».",
	["Hace más lento al enemigo. Gana distancia para seguir disparando."] = "Ralentit l'ennemi. Prends de la distance pour continuer à tirer.",
	["Hace más lento al enemigo. Úsala con los que huyen para que no traigan ayuda."] = "Ralentit l'ennemi. Utilise-le sur les fuyards pour qu'ils n'amènent pas de renforts.",
	["Hace sangrar al enemigo un rato. Ponla al inicio de las peleas largas."] = "Fait saigner l'ennemi un moment. Pose-le au début des longs combats.",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "Fait saigner l'ennemi : appliquez-le au début du combat.",
	["Hace sangrar mucho: vale la pena con enemigos que duran."] = "Fait beaucoup saigner : ça vaut la peine contre les ennemis qui durent.",
	["Hace siglos, Aegwynn venció a un avatar de Sargeras y escondió su cuerpo en la Tumba de Sargeras, en las Islas Abruptas."] = "Il y a des siècles, Aegwynn a vaincu un avatar de Sargeras et caché son corps dans la tombe de Sargeras, sur les îles Brisées.",
	["Hacen %d misiones contigo"] = "Fait %d quêtes avec toi",
	["Hacen 1 misión contigo"] = "Fait 1 quête avec toi",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "Il faut au moins 3 endroits différents de cette ressource dans la zone.",
	["Hacer mazmorras con tu grupo da botín, misiones y reputación: es farmeo con plática incluida."] = "Faire des donjons avec ton groupe rapporte butin, quêtes et réputation : c'est du farm avec la discussion en prime.",
	["Hacer oro"] = "Faire de l'or",
	["Haces daño"] = "Tu fais des dégâts",
	["Haces de luz entre árboles, nubes y montañas."] = "Des rayons de lumière entre les arbres, les nuages et les montagnes.",
	["Hacha de dos manos"] = "Hache à deux mains",
	["Hacha de una mano"] = "Hache à une main",
	["Hacia %s"] = "Vers %s",
	["Hacia %s (niv. %s)"] = "Vers %s (niv. %s)",
	["Hacia abajo"] = "Vers le bas",
	["Hacia arriba"] = "Vers le haut",
	["Hacia dónde se acomodan tus compañeros."] = "Dans quel sens les membres du groupe sont disposés.",
	["Hacia:"] = "Vers :",
	["Hacia: %s"] = "Vers : %s",
	["Halloween de Azeroth"] = "Sanssaint",
	["Halloween recuerda el día en que los Renegados se liberaron del Rey Exánime: por eso queman al Hombre de Mimbre."] = "La Sanssaint rappelle le jour où les Réprouvés se sont libérés du roi-liche : c'est pour ça qu'ils brûlent l'Homme d'osier.",
	["Hamuul Tótem de Runa, el archidruida de Cima del Trueno, fue de los primeros tauren aceptados en el Círculo Cenarion."] = "Hamuul Totem-runique, l'archidruide des Pitons-du-Tonnerre, fut l'un des premiers Taurens acceptés dans le Cercle cénarien.",
	["Hasta dónde llegan las montañas lejanas."] = "Jusqu'où vont les montagnes lointaines.",
	["Hasta dónde puedes alejar la cámara con la rueda. El juego puede limitarlo: Alfa muestra el valor que de verdad quedó."] = "Jusqu'où vous pouvez reculer la caméra avec la molette. Le jeu peut le limiter : Alfa affiche la valeur réellement appliquée.",
	["Hasta dónde se dibuja el mundo. Es lo que más FPS cuesta."] = "Jusqu'où le monde est dessiné. C'est ce qui coûte le plus de FPS.",
	["Hasta dónde se dibuja el pasto. Más lejos, menos «alfombra» que aparece al caminar."] = "Jusqu'où l'herbe est dessinée. Plus loin, moins de « tapis » qui apparaît en marchant.",
	["Hasta el alfa se cae. Lo importante es levantarse. ¡Vamos!"] = "Même l'alpha tombe. L'important, c'est de se relever. Allez !",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "Jusqu'au niveau 20, utilisez une arme à deux mains ; ensuite, passez à deux armes à une main.",
	["Hasta mi nivel"] = "Jusqu'à mon niveau",
	["Hasta qué distancia se ven las placas de nombre. El juego puede limitarlo."] = "Jusqu'à quelle distance les barres de nom s'affichent. Le jeu peut le limiter.",
	["Hasta qué nivel"] = "Jusqu'à quel niveau",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "Certains ennemis se transforment en loups et d'autres apeurent : si vous êtes apeuré, ne paniquez pas, attendez.",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "Il y a beaucoup d'eau : quand vous nagez sous l'eau, surveillez votre barre de respiration et remontez prendre de l'air.",
	["Hay muchas tribus trol: Amani, Gurubashi, Furiarena, Zandalar... y casi todas pelean entre sí."] = "Il y a beaucoup de tribus trolls : Amani, Gurubashi, Furie-des-sables, Zandalar... et presque toutes se battent entre elles.",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "Il y a beaucoup de morts-vivants et de hurans : prévoyez de quoi guérir les maladies si votre groupe le peut.",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "Il y a beaucoup de troggs et d'élémentaires de feu ensemble : attirez un ou deux groupes à la fois, pas plus.",
	["Hay nueve clases en el Clásico, pero solo la Alianza tiene paladines y solo la Horda tiene chamanes."] = "Il y a neuf classes en Classic, mais seule l'Alliance a des paladins et seule la Horde a des chamans.",
	["Hay que llevar el recado y hablar con quien te espera."] = "Il faut porter le message et parler à qui t'attend.",
	["Hay una guía de Alfa"] = "Il existe un guide d'Alfa",
	["Haz %s: unas %d veces"] = "Fabrique %s : environ %d fois",
	["Haz Pociones de sanación menores de más para este tramo."] = "Fais des Potions de soins mineures en plus pour cette étape.",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "Faites un clic droit (ou Maj+clic) sur la carte là où vous en voulez un : donnez-lui un nom, une icône et une couleur, et la flèche vous y mène quand vous voulez.",
	["Haz clic en un atajo y pulsa la tecla que quieras; Esc cancela y el clic derecho lo quita. Se guardan fuera de combate."] = "Clique sur un raccourci et appuie sur la touche voulue ; Échap annule et le clic droit l'enlève. Ils s'enregistrent hors combat.",
	["Haz clic en un marco de ejemplo"] = "Cliquez sur un cadre d'exemple",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "Cliquez, puis appuyez sur la touche voulue (Échap annule). Le clic droit la retire.",
	["Haz clic y pulsa la tecla, un botón del ratón o la rueda (con Mayús, Ctrl o Alt si quieres). Esc cancela; clic derecho la quita."] = "Cliquez et appuyez sur la touche, un bouton de la souris ou la molette (avec Maj, Ctrl ou Alt si vous voulez). Échap annule ; clic droit l'efface.",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "Double-clic droit dans le monde pour lancer la ligne, sans la touche. Jamais en combat ni en vol.",
	["Haz misiones de tu registro o caza enemigos de tu nivel (los grises no dan nada)."] = "Fais des quêtes de ton journal ou chasse des ennemis de ton niveau (les gris ne rapportent rien).",
	["Haz tu propia agua. Así no gastas oro en bebida."] = "Fais ta propre eau. Plus besoin de dépenser de l'or en boisson.",
	["Haz tu propia comida para recuperar vida."] = "Fais ta propre nourriture pour récupérer de la vie.",
	["Hazlo ya"] = "Fabrique-le maintenant",
	["Hecha"] = "Terminé",
	["Hecha %d veces"] = "Terminé %d fois",
	["Hechas"] = "Terminés",
	["Hechizo del preajuste"] = "Sort du préréglage",
	["Hechizo desconocido"] = "Sort inconnu",
	["Hechizo elegido por ti"] = "Sort choisi par vous",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "Nouveau sort pour vos clics de Soins. Ouvrez /alfa curacion.",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "Des sorts d'ombre qui font des dégâts sur la durée : le prêtre qui monte le mieux en solo, presque sans se reposer.",
	["Hechizos de tu mascota"] = "Sorts de votre familier",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "Des sorts de loin et des racines pour que le monstre ne vous atteigne pas. La forme de sélénien arrive à la fin.",
	["Hecho"] = "Fait",
	["Hemet Nesingwary organiza safaris por toda la Vega: sus encargos de cazar panteras, tigres y raptores son famosos."] = "Hemet Nesingwary organise des safaris dans toute la vallée de Strangleronce : ses chasses aux panthères, tigres et raptors sont célèbres.",
	["Hemorragia: suma puntos de combo y el enemigo recibe más daño."] = "Hémorragie : accumule des points de combo et l'ennemi subit plus de dégâts.",
	["Hender armadura más barato."] = "Fracasser armure moins cher.",
	["Hender armadura más barato: amenaza constante."] = "Fracasser armure moins cher : une menace constante.",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "Fracasser armure moins cher : plus de menace sur plusieurs ennemis.",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "Fracasser armure : une menace constante et l'ennemi subit plus de dégâts.",
	["Herboristería"] = "Herboristerie",
	["Herboristería combina bien con Alquimia, y también con Desollar o Minería para recolectar el doble."] = "L'Herboristerie va bien avec l'Alchimie, et aussi avec le Dépeçage ou le Minage pour récolter deux fois plus.",
	["Herramienta"] = "Outil",
	["Herramientas"] = "Outils",
	["Herrería"] = "Forge",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "La Forge fabrique des armes et des armures en plaques très bonnes pour votre niveau, et le Minage vous fournit les matériaux gratuitement.",
	["Herrería fabrica escudos y piezas resistentes."] = "La Forge fabrique des boucliers et des pièces résistantes.",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "La Forge fabrique des boucliers et des plaques avec défense et endurance, exactement ce qu'il faut à un tank.",
	["Herrería y Minería van de la mano: tú sacas el metal y tú lo forjas."] = "La Forge et le Minage vont de pair : tu extrais le métal et tu le forges.",
	["Hiciste lo que pedía antes. Búscala con su «!» y tómala, o elige qué sigue."] = "Tu as fait ce qu’elle demandait avant. Trouve-la grâce à son « ! » et prends-la, ou choisis la suite.",
	["Hielo"] = "Glace",
	["Hierbas"] = "Herbes",
	["Historias"] = "Histoires",
	["Historias de las misiones"] = "Histoires des quêtes",
	["Historias de tus misiones"] = "Histoires de tes quêtes",
	["Historias guardadas"] = "Histoires gardées",
	["Historias y datos curiosos"] = "Histoires et anecdotes",
	["Hogger es un gnoll de Elwynn tan temido que, para muchos aventureros, fue su primer gran reto."] = "Lardeur est un gnoll d'Elwynn si redouté que, pour beaucoup d'aventuriers, il a été le premier grand défi.",
	["Hombros"] = "Épaules",
	["Honor"] = "Honneur",
	["Horarios de barcos y zepelines"] = "Horaires des bateaux et des zeppelins",
	["Horarios de barcos y zepelines en el mapa"] = "Horaires des bateaux et zeppelins sur la carte",
	["Horda"] = "Horde",
	["Hoy"] = "Aujourd'hui",
	["Hoy avanzaste %s niveles"] = "Aujourd'hui tu as pris %s niveaux",
	["Hoy avanzaste 1 nivel"] = "Aujourd'hui tu as pris 1 niveau",
	["Hoy en Azeroth hay fiesta: %s. ¿Vamos a ver qué hay?"] = "Il y a une fête en Azeroth aujourd'hui : %s. On va voir ?",
	["Hoy en números"] = "Aujourd'hui en chiffres",
	["Hoy está difícil, ¿verdad? No pasa nada. Descansa un poco, repara y volvemos con más fuerza."] = "C'est une journée difficile, hein ? Ce n'est pas grave. Repose-toi un peu, répare et on revient plus forts.",
	["Hoy llevas %s"] = "Aujourd’hui tu en es à %s",
	["Hoy te guía"] = "Aujourd'hui te guide",
	["Hoy te pone tu siguiente paso primero, y en combate ninguna ventana de Alfa te deja atrapado."] = "Aujourd'hui affiche d'abord ta prochaine étape, et en combat aucune fenêtre d'Alfa ne te bloque plus.",
	["Hoy todavía no avanzas: ¡a cazar!"] = "Pas encore de progrès aujourd'hui : en chasse !",
	["Hoy todavía no cazamos nada. ¿Salimos?"] = "On n’a encore rien chassé aujourd’hui. On y va ?",
	["Hoy, Aventura, Personaje, Mundo, Oficios y Manada en una sola ventana: %s o el lobo del minimapa."] = "Aujourd'hui, Aventure, Personnage, Monde, Métiers et Meute dans une seule fenêtre : %s ou le loup de la minicarte.",
	["Hoy, a tu clase"] = "Aujourd'hui, pour ta classe",
	["Huele a pan recién hecho por aquí… se me antoja."] = "Ça sent le pain frais par ici… j'en ai envie.",
	["Huele a salchichas asadas por aquí… ¿o es mi imaginación?"] = "Ça sent les saucisses grillées par ici… ou c'est mon imagination ?",
	["Huella"] = "Empreinte",
	["Huelo a botín... y a una que otra salchicha."] = "Ça sent le butin... et une saucisse ou deux.",
	["Humanos"] = "Humains",
	["Humo, agua y efectos se funden con lo que tocan en lugar de cortarse en seco."] = "La fumée, l'eau et les effets se fondent dans ce qu'ils touchent au lieu d'être coupés net.",
	["Huracán: golpea a todos a tu alrededor."] = "Tourbillon : frappe tous les ennemis autour de vous.",
	["Háblame de mi gente"] = "Parle-moi de mon peuple",
	["Iconos de viaje en el minimapa"] = "Icônes de voyage sur la minicarte",
	["Idioma"] = "Langue",
	["Igual que Alfa"] = "Comme Alfa",
	["Igual que lo tuyo"] = "Comme le vôtre",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "Comme les autres seigneurs : il lance des éclairs et se soigne. Interrompez son soin.",
	["Illidan absorbió el poder del Cráneo de Gul'dan y se volvió mitad demonio. Por eso Malfurion lo desterró."] = "Illidan a absorbé le pouvoir du Crâne de Gul'dan et est devenu à moitié démon. C'est pour ça que Malfurion l'a banni.",
	["Illidan guardó agua del Pozo antes de su caída y creó uno nuevo en Hyjal. Por eso Malfurion lo encerró bajo tierra durante diez mil años."] = "Illidan a gardé de l'eau du Puits avant sa chute et en a créé un nouveau sur Hyjal. C'est pour ça que Malfurion l'a enfermé sous terre pendant dix mille ans.",
	["Illidan se fue a Terrallende, lo que quedó de Draenor, y ahí se hizo de un ejército propio."] = "Illidan est parti en Outreterre, ce qui reste de Draenor, et s'y est constitué sa propre armée.",
	["Illidan, el gemelo de Malfurion, amaba a Tyrande, pero ella eligió a su hermano. Esa herida lo acompañó por diez mil años."] = "Illidan, le jumeau de Malfurion, aimait Tyrande, mais elle a choisi son frère. Cette blessure l'a suivi pendant dix mille ans.",
	["Imagen HDR"] = "Image HDR",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "Importe une chaîne d'échelle de statistiques, et utilise, renomme, exporte ou supprime tes échelles.",
	["Importado"] = "Importé",
	["Importado: %s. Ya puedes seguirlo."] = "Importé : %s. Vous pouvez le suivre dès maintenant.",
	["Importar"] = "Importer",
	["Importar ajustes"] = "Importer des réglages",
	["Importar un build"] = "Importer un build",
	["Importar una ruta"] = "Importer un itinéraire",
	["Importar..."] = "Importer...",
	["Incapacita al enemigo un momento. Úsalo para ponerte a su espalda."] = "Neutralise l'ennemi un instant. Utilise-le pour passer dans son dos.",
	["Inclina la cámara al subir y bajar cuestas."] = "Incline la caméra dans les montées et les descentes.",
	["Ingeniería"] = "Ingénierie",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "L'Ingénierie donne des étourdissements et des astuces qui gagnent les duels ; le Minage fournit les matériaux.",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "L'Ingénierie donne des grenades et des filets pour contrôler l'adversaire ; le Minage fournit les matériaux.",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "L'Ingénierie donne des grenades, des filets et des bombes qui décident des combats contre les joueurs ; le Minage fournit les matériaux.",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "L'Ingénierie vous sauve avec des astuces pour fuir ; la Couture fabrique vos vêtements.",
	["Inicio"] = "Accueil",
	["Inicio de Alfa"] = "Accueil d'Alfa",
	["Inicio del horizonte"] = "Début de l'horizon",
	["Insignias de La Jauría: los Alfas y los miembros llevan su lobo en el cuadro, en La Jauría y en el mapa; y quienes comparten se ven con una huella."] = "Insignes de La Jauría : les Alphas et les membres portent leur loup dans l'infobulle, dans La Jauría et sur la carte ; et ceux qui partagent apparaissent comme une empreinte.",
	["Instantánea: úsala cada vez que esté lista."] = "Instantanée : utilisez-la dès qu'elle est prête.",
