	["Interfaz del juego"] = "Interface du jeu",
	["Interrumpe un hechizo con tu escudo. Úsalo con magos y curanderos enemigos."] = "Interrompt un sort avec ton bouclier. Utilise-le contre les lanceurs de sorts et soigneurs ennemis.",
	["Interrumpe un hechizo y bloquea esa magia un rato."] = "Interrompt un sort et verrouille cette école de magie un moment.",
	["Interrumpe un hechizo. Guárdalo para cuando el enemigo lance algo peligroso."] = "Interrompt un sort. Garde-le pour quand l'ennemi lance quelque chose de dangereux.",
	["Interrumpe un hechizo. Úsalo con magos y curanderos enemigos."] = "Interrompt un sort. Utilise-le contre les lanceurs de sorts et soigneurs ennemis.",
	["Interrumpes hechizos y los silencias."] = "Vous interrompez les sorts et réduisez leur lanceur au silence.",
