	["Moviendo"] = "Déplacement",
	["Mucho daño con tu arma a distancia: disparos fuertes antes de que el monstruo llegue."] = "Beaucoup de dégâts avec votre arme à distance : des tirs puissants avant que le monstre n'arrive.",
	["Mucho daño de sombra que va creciendo. Una maldición por enemigo."] = "Beaucoup de dégâts d'ombre qui augmentent. Une malédiction par ennemi.",
	["Mucho maná y hechizos arcanos potentes: el mago que menos descansa."] = "Beaucoup de mana et des sorts des arcanes puissants : le mage qui se repose le moins.",
	["Mucho tiempo sin verte, %s. Repasa tus misiones antes de salir."] = "Ça fait longtemps, %s. Revois tes quêtes avant de partir.",
	["Muchos"] = "Beaucoup",
	["Muchos enemigos duermen a un jugador: no es grave, el sueño se quita solo."] = "Beaucoup d'ennemis endorment un joueur : ce n'est pas grave, le sommeil se dissipe tout seul.",
	["Muchos: consejos del momento y de vez en cuando uno de Alfa. Pocos: menos seguido. Solo importantes: al morir, al subir de nivel y en tus logros."] = "Beaucoup : des conseils sur le moment et de temps en temps un sur Alfa. Peu : moins souvent. Importants seulement : quand tu meurs, montes de niveau et lors de tes étapes marquantes.",
	["Muchísima amenaza en un golpe."] = "Énormément de menace en un coup.",
	["Muelle de %s"] = "Quai de %s",
	["Muelles y torres de zepelín, con a dónde van."] = "Quais et tours des zeppelins, avec leurs destinations.",
	["Muertes"] = "Morts",
	["Muerto"] = "Mort",
	["Muestra la ventana de guía y la flecha, y cierra esta ventana para que las veas."] = "Affiche la fenêtre du guide et la flèche, et ferme cette fenêtre pour que tu les voies.",
	["Muestra la vida en número, debajo del nombre."] = "Affiche la vie en chiffres, sous le nom.",
	["Muestra lo que aún no exploras, con un tono más frío para distinguirlo."] = "Affiche ce que vous n'avez pas encore exploré, dans un ton plus froid pour le distinguer.",
	["Muestra un aviso de ejemplo para que veas dónde sale."] = "Affiche une alerte d'exemple pour voir où elle apparaît.",
	["Muestra un ícono encima del corcho: así sabes que tu tecla lo va a recoger."] = "Affiche une icône au-dessus du flotteur : vous savez ainsi que votre touche va le remonter.",
	["Mueve lo de Alfa con el ratón"] = "Déplacer les éléments d'Alfa à la souris",
	["Mueve tus marcos"] = "Déplacez vos cadres",
	["Mulgore de día: pasto hasta donde alcanza la vista y kodos pastando. Qué paz."] = "Mulgore de jour : de l'herbe à perte de vue et des kodos qui broutent. Quelle paix.",
	["Mundo"] = "Monde",
	["Munición"] = "Munitions",
	["Muradin Barbabronce acompañó a Arthas a Rasganorte. Cuando Arthas tomó la espada, un trozo de hielo golpeó a Muradin y lo dieron por muerto."] = "Muradin Barbe-de-bronze a accompagné Arthas en Norfendre. Quand Arthas a pris l'épée, un bloc de glace a frappé Muradin et on l'a laissé pour mort.",
	["Muradin Barbabronce le enseñó a Arthas a pelear cuando el príncipe era joven."] = "Muradin Barbe-de-bronze a appris à se battre à Arthas quand le prince était jeune.",
	["Muro de escudo dura más."] = "Mur protecteur dure plus longtemps.",
	["Muro de escudo dura más: te salva en los jefes."] = "Mur protecteur dure plus longtemps : il vous sauve contre les boss.",
	["Muy grande"] = "Très grande",
	["Muy peligroso para tu nivel: mejor con grupo o rodéalo."] = "Très dangereux pour ton niveau : mieux vaut un groupe, ou contourne-le.",
	["Muy pronto"] = "Bientôt",
	["Muéstrala u ocúltala. También con su tecla o con /alfa guia."] = "Affichez-la ou masquez-la. Aussi avec sa touche ou avec /alfa guia.",
	["Muévete a las zonas de nivel 10 a 20. Las lombrices ayudan a que no se escapen. Pide el rango Experto desde 125."] = "Passez aux zones de niveau 10 à 20. Les vers aident à ce que les poissons ne s'échappent pas. Demandez le rang Expert dès 125.",
	["Muñecas"] = "Poignets",
	["Márcala cuando la hagas"] = "Cochez-la quand vous la faites",
	["Márcalo con la calavera y todo tu grupo lo verá."] = "Marque-le d'une tête de mort et tout ton groupe le verra.",
	["Más"] = "Plus",
	["Más Abrumar gracias a Desgarrar."] = "Plus de Fulgurances grâce à Pourfendre.",
	["Más Golpes heroicos: más daño por pelea."] = "Plus de Frappes héroïques : plus de dégâts par combat.",
	["Más adelante"] = "Plus tard",
	["Más adelante eliges entre ingeniería gnómica y goblin: los inventos gnómicos fallan a veces de forma muy graciosa, y los goblin explotan más."] = "Plus tard, tu choisis entre l'ingénierie gnome et gobeline : les gadgets gnomes ratent parfois de façon très drôle, et les gobelins explosent davantage.",
	["Más adelante eliges especialidad: de escamas de dragón, elemental o tribal."] = "Plus tard, tu choisis une spécialité : écailles de dragon, élémentaire ou tribal.",
	["Más adelante eliges especialidad: forjador de armaduras o armero, y los armeros, entre espadas, mazas y hachas."] = "Plus tard, tu choisis une spécialité : fabricant d'armures ou fabricant d'armes, et les fabricants d'armes choisissent entre épées, masses et haches.",
	["Más adelante: %s."] = "Plus tard : %s.",
	["Más aguante para ti y tus amigos. Dásela a todo el grupo antes de empezar."] = "Plus d'endurance pour toi et tes amis. Donne-la à tout le groupe avant de commencer.",
	["Más aguante y seguridad. Matas un poco más lento, pero casi no mueres."] = "Plus d'endurance et de sécurité. Vous tuez un peu plus lentement, mais vous ne mourez presque jamais.",
	["Más alto, atraviesa objetos más grandes antes de acercarse."] = "Plus haut, elle traverse des objets plus grands avant de se rapprocher.",
	["Más alto, los objetos lejanos tardan más en desaparecer."] = "Plus haut, les objets lointains mettent plus de temps à disparaître.",
	["Más alto, más nítido. Demasiado puede marcar bordes y brillos."] = "Plus haut, c'est plus net. Trop peut accentuer les bords et les reflets.",
	["Más alto, ves más a los lados."] = "Plus haut, vous voyez davantage sur les côtés.",
	["Más amenaza."] = "Plus de menace.",
	["Más amenaza: los monstruos se quedan contigo."] = "Plus de menace : les monstres restent sur vous.",
	["Más armadura para ti y tu grupo cercano. Una buena aura para empezar."] = "Plus d'armure pour toi et ton groupe proche. Une bonne aura pour commencer.",
	["Más armadura y más poder. Mantenlo siempre puesto."] = "Plus d'armure et plus de puissance. Garde-le toujours actif.",
