	["No se sabe en qué lugar está."] = "On ne sait pas où il se trouve.",
	["No se ve en pantalla. Tráela de vuelta cuando quieras (también con /alfa lya)."] = "Elle n'est pas à l'écran. Fais-la revenir quand tu veux (aussi avec /alfa lya).",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "Il n'apparaît pas toujours dans la mine : si vous le voyez, c'est un boss de plus avec un bon butin.",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "Il n'apparaît pas toujours. Il inflige une douleur de l'ombre : soignez celui qui l'a.",
	["No sigues ninguna guía"] = "Vous ne suivez aucun guide",
	["No son para ti"] = "Pas pour vous",
	["No sé de dónde sale este objeto."] = "Je ne sais pas d'où vient cet objet.",
	["No sé de eso todavía. Prueba con otra palabra, o pregúntale a la manada en el Discord."] = "Je ne sais pas encore ça. Essaie un autre mot, ou demande à la meute sur Discord.",
	["No sé dónde se entrega"] = "Lieu de rendu inconnu",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "Je ne sais pas où se rend %s : je l'ai retirée de l'itinéraire.",
	["No sé dónde se entrega %s: la saqué del plan."] = "Je ne sais pas où se rend %s : je l'ai retirée du plan.",
	["No sé dónde se junta este material."] = "Je ne sais pas où se récolte ce matériau.",
	["No sé dónde se junta: búscalo en la Enciclopedia para ver de dónde sale."] = "Je ne sais pas où ça se récolte : cherchez-le dans l'Encyclopédie pour voir d'où il vient.",
	["No sé dónde se toma esa misión."] = "Je ne sais pas où se prend cette quête.",
	["No sé en qué zona estás."] = "Je ne sais pas dans quelle zone vous êtes.",
	["No sé qué misión es."] = "Je ne sais pas de quelle quête il s'agit.",
	["No sé si alguien en Azeroth cocina salchichas como las de casa... pero si encuentras una receta, ¡me avisas!"] = "Je ne sais pas si quelqu'un en Azeroth cuisine des saucisses comme à la maison... mais si tu trouves une recette, dis-le-moi !",
	["No sé si se puede tomar"] = "Je ne sais pas si elle peut être prise",
	["No te alcanza"] = "Pas assez d'argent",
	["No tienes cartas."] = "Tu n'as pas de courrier.",
	["No tienes cebos. Los venden los vendedores de suministros de pesca; la guía dice cuáles sirven a tu habilidad."] = "Vous n'avez pas d'appâts. Les vendeurs de fournitures de pêche en vendent ; le guide dit lesquels conviennent à votre compétence.",
	["No tienes demonio: el abisario aguanta los golpes por ti."] = "Vous n'avez pas de démon : le marcheur du Vide encaisse les coups pour vous.",
	["No tienes demonio: invoca uno antes de pelear."] = "Vous n'avez pas de démon : invoquez-en un avant le combat.",
	["No tienes demonio: invócalo al instante, aun peleando."] = "Vous n'avez pas de démon : invoquez-le instantanément, même en plein combat.",
	["No tienes marcadores en el mapa de Alfa. Pon uno en el mapa y vuelve aquí."] = "Vous n'avez aucun marqueur sur la carte d'Alfa. Placez-en un sur la carte et revenez ici.",
	["No tienes mascota: llámala."] = "Vous n'avez pas de familier : appelez-le.",
	["No tienes mascota: si murió, revívela."] = "Vous n'avez pas de familier : s'il est mort, ressuscitez-le.",
	["No tienes misiones para este plan con ese filtro."] = "Vous n'avez pas de quêtes pour ce plan avec ce filtre.",
	["No tienes puntos libres. El siguiente talento del plan (%s) te toca en el nivel %d."] = "Vous n'avez pas de points libres. Le prochain talent du plan (%s) arrive au niveau %d.",
	["No tienes un conjunto llamado «%s»."] = "Tu n'as pas d'ensemble nommé « %s ».",
