	["Para vender"] = "À vendre",
	["Para vender, habla con un comerciante."] = "Pour vendre, parlez à un marchand.",
	["Para ver cuánto procesador usa cada parte, escribe /console scriptProfile 1 y luego /reload. Hace el juego un poco más lento: cuando termines, /console scriptProfile 0 y /reload."] = "Pour voir le processeur utilisé par chaque partie, tape /console scriptProfile 1 puis /reload. Le jeu ralentit un peu : quand tu as fini, /console scriptProfile 0 et /reload.",
	["Para ver las guaridas de la manada, deja que te vean en el mapa."] = "Pour voir les tanières de la meute, laisse-la te voir sur la carte.",
