	["Pregúntale a la manada"] = "Demande à la meute",
	["Pregúntale a un guardia de la ciudad por el instructor de la profesión."] = "Demandez à un garde de la ville où trouver le maître du métier.",
	["Premio final: %s"] = "Récompense finale : %s",
