	["Premio: %s"] = "Récompense : %s",
	["Prendas de lana que te enseñe tu instructor."] = "Vêtements en laine que t'apprend ton maître.",
	["Prendas de seda que te enseñe tu instructor."] = "Vêtements en soie que t'apprend ton maître.",
