	["Primer aviso"] = "Première alerte",
	["Primer tirón"] = "Première touche",
	["Primero cobra lo que ya hiciste: una ruta por el camino más corto, junta por PNJ."] = "Encaissez d'abord ce que vous avez déjà fait : un itinéraire par le chemin le plus court, regroupé par PNJ.",
	["Primero con el banco de la hermandad"] = "D'abord avec la banque de guilde",
	["Primero crea una ruta: /alfa recoleccion ruta"] = "Créez d'abord un itinéraire : /alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "La défense d'abord : vous parez beaucoup plus de coups et vous vous reposez moins.",
	["Primero elige tu build"] = "Choisissez d'abord votre build",
	["Primero necesitas %s, que se toma a nivel %d."] = "Il vous faut d'abord %s, qui se prend au niveau %d.",
	["Primero pelean contra el Comandante Mograine; cuando cae, ella llega y lo resucita."] = "D'abord, vous affrontez le commandant Mograine ; quand il tombe, elle arrive et le ressuscite.",
	["Primero prende la línea de tiempo del jefe."] = "Activez d'abord la chronologie du boss.",
	["Primero sale su trituradora; al romperla, Sneed baja y pelea a pie."] = "D'abord vient son déchiqueteur ; une fois détruit, Sneed descend et combat à pied.",
	["Primero toma %s"] = "Prenez d'abord %s",
	["Primero un objeto, luego oro, luego una profesión y al final el banco: tú eliges el orden."] = "D'abord un objet, puis de l'or, puis un métier et enfin la banque : c'est vous qui choisissez l'ordre.",
	["Primero: %s"] = "D'abord : %s",
	["Primeros auxilios"] = "Secourisme",
	["Primeros auxilios le sirve a cualquier clase, sobre todo a las que no se curan solas."] = "Le Secourisme sert à toutes les classes, surtout à celles qui ne se soignent pas seules.",
	["Primeros auxilios sirve a cualquier clase: unas vendas te sacan de apuros."] = "Le Secourisme sert à toutes les classes : quelques bandages te sortent d'affaire.",
	["Principal"] = "Principal",
