	["Profesiones"] = "Métiers",
	["Profesiones (18): llegar a 150, 225 y 300 en Alquimia, Herrería, Encantamiento, Ingeniería, Peletería y Sastrería."] = "Métiers (18) : atteindre 150, 225 et 300 en Alchimie, Forge, Enchantement, Ingénierie, Travail du cuir et Couture.",
	["Profesiones que te sirven"] = "Métiers utiles pour vous",
	["Profesiones: más puntos de habilidad, más recursos al recolectar, mejores precios con los vendedores, más platos y más peces."] = "Métiers : plus de points de compétence, plus de ressources en récoltant, de meilleurs prix chez les vendeurs, plus de plats et plus de poissons.",
	["Profesión"] = "Métier",
	["Promedio de la sesión: %s XP por hora."] = "Moyenne de la session : %s XP par heure.",
