	["Proponer"] = "Proposer",
	["Proponer la siguiente guía"] = "Proposer le guide suivant",
	["Propusiste una cita"] = "Tu as proposé une sortie",
	["Propón qué, el día y la hora: a los lobos de tu hermandad con Alfa les llega con «Voy». Te recuerdo 15 minutos antes."] = "Propose quoi, le jour et l'heure : les loups de ta guilde avec Alfa le reçoivent avec « J'en suis ». Je te le rappelle 15 minutes avant.",
	["Propón una salida a la manada (/alfa cita mañana 21:30 Minas)"] = "Propose une sortie à la meute (/alfa cita tomorrow 21:30 Mortemines)",
	["Propón una salida con día y hora y recibe las de tu hermandad con «Voy». Lya te la recuerda 15 minutos antes."] = "Propose une sortie avec un jour et une heure et reçois celles de ta guilde avec « J'en suis ». Lya te la rappelle 15 minutes avant.",
	["Protección"] = "Protection",
	["Protección [paladín]"] = "Protection",
