	["Protege a un aliado de todo daño físico un momento. Salva a quien cura."] = "Protège un allié de tous les dégâts physiques un instant. Sauve ton soigneur.",
	["Proyectiles"] = "Projectiles",
	["Prueba"] = "Test",
	["Prueba con %d: arrastra para mover"] = "Test avec %d : faites glisser pour déplacer",
	["Prueba con el nombre del pueblo o de la zona."] = "Essaie avec le nom de la ville ou de la zone.",
	["Prueba con otra búsqueda o quita un filtro."] = "Essayez une autre recherche ou retirez un filtre.",
