	["Spots de farmeo"] = "Spots de farm",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "Stromgarde, l'héritière de Strom, résiste tant bien que mal : trolls, ogres et Syndicat se disputent ses ruines.",
	["Su arpón envenena: quita el veneno si puedes."] = "Son harpon empoisonne : guérissez le poison si vous le pouvez.",
	["Su botín está por descubrir"] = "Son butin reste à découvrir",
	["Su electricidad salta de un jugador a otro: sepárense."] = "Son électricité saute d'un joueur à l'autre : écartez-vous.",
	["Su ficha"] = "Sa fiche",
	["Su final no alcanzó a guardarse."] = "Sa fin n'a pas pu être gardée à temps.",
	["Su grupo está lleno o no puede invitar."] = "Son groupe est plein ou il ne peut pas inviter.",
	["Su guarida ya no está abierta."] = "Sa tanière n’est plus ouverte.",
	["Su mordida envenena: quita el veneno si puedes."] = "Sa morsure empoisonne : guérissez le poison si vous le pouvez.",
	["Su nombre ya está en el correo: pon %s y envíalo."] = "Son nom est déjà dans le courrier : ajoute %s et envoie.",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "Leur or et leurs récompenses sont déjà à vous : il ne reste qu'à les rendre.",
	["Su plano está lleno de gente. Si le abres tu guarida, Alfa lo invita a tu grupo y sale solo al llegar."] = "Sa couche est bondée. Si tu lui ouvres ta tanière, Alfa l'invite dans ton groupe et il part seul une fois arrivé.",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "Son éclair saute d'un joueur à l'autre : ne restez pas tous groupés.",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "Son éclair saute d'un joueur à l'autre : écartez-vous un peu.",
