	["Te llevo a entregarlas todas en el mejor orden."] = "Je t’emmène les rendre toutes dans le meilleur ordre.",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "Je vous mène à la meilleure source. N'oubliez pas qu'une monture demande un niveau, la monte et de l'or.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "Je vous mène à celui qui reçoit chacune, et vous récupérez les suivantes.",
	["Te llevo la cuenta de tu día de caza: misiones, niveles, oro, raros y el tiempo. Escribe /alfa lya dia y te lo cuento."] = "Je tiens le compte de ta journée de chasse : quêtes, niveaux, or, rares et temps. Tape /alfa lya dia et je te raconte.",
	["Te llevo la cuenta de tu semana de caza y tu mejor día. Escribe /alfa lya semana y te lo cuento."] = "Je tiens le compte de ta semaine de chasse et de ton meilleur jour. Tape /alfa lya semana et je te raconte.",
	["Te lo da un PNJ"] = "Donné par un PNJ",
	["Te lo enseña cualquier instructor de este oficio en las ciudades. Puedes tener dos oficios principales; Cocina y Primeros auxilios no cuentan."] = "N'importe quel maître de ce métier dans les villes te l'apprend. Tu peux avoir deux métiers principaux ; Cuisine et Secourisme ne comptent pas.",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "N'importe quel maître de pêche vous l'enseigne. Tant que vous ne l'avez pas appris, votre compétence ne dépasse pas le plafond.",
	["Te lo enseña tu entrenador."] = "Ton maître te l'enseigne.",
	["Te lo enseñan desde el nivel %d."] = "On l'enseigne dès le niveau %d.",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "Je te le demande de tout cœur : ne dépèce jamais un loup devant moi, d'accord ?",
