	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "Elle te salue selon l'heure, commente la zone et s'assoit parfois pour quémander avec son petit os.",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "Vous avez de la rage en trop et plusieurs ennemis : votre prochain coup en touche deux.",
	["Te sobra ira: gástala en tu siguiente golpe."] = "Vous avez de la rage en trop : dépensez-la dans votre prochain coup.",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "Vous avez de la rage en trop : votre prochain coup est plus puissant.",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "Te suggère des objectifs d'étapes suivantes qui sont tout près.",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "Te suggère quelle technique utiliser maintenant et lesquelles suivent. Il ne fait que suggérer : il n'appuie jamais sur rien à ta place.",
	["Te teletransporta a tu ciudad. Necesitas una runa de teletransporte."] = "Te téléporte dans ta ville. Il te faut une rune de téléportation.",
	["Te teletransportas unos metros hacia adelante. Para escapar de raíces y aturdimientos."] = "Te téléporte quelques mètres en avant. Pour échapper aux immobilisations et étourdissements.",
	["Te vuelve inmune un rato. Úsalo para salvarte o para escapar."] = "Te rend insensible un moment. Utilise-le pour te sauver ou fuir.",
	["Te vuelves invisible al caminar. Acércate sin que te vean y elige cómo empezar."] = "Tu deviens invisible en marchant. Approche sans être vu et choisis comment commencer.",
