	["Tienes %d piezas mejores para pescar en tus bolsas."] = "Vous avez %d meilleures pièces de pêche dans vos sacs.",
	["Tienes %d puntos de talento: empieza por %s"] = "Vous avez %d points de talent : commencez par %s",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "Vous avez %d points hors de %s. Alfa ne retire jamais de talents : pour suivre ce build, réinitialisez vos talents auprès de votre maître de classe et Alfa les replace en un clic. Ou choisissez le build de la branche que vous avez déjà.",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "Vous avez %d points libres, mais les prochains talents de %s n'existent pas dans votre arbre (un patch les a peut-être modifiés). Placez-les à la main dans la fenêtre du jeu ou essayez un autre style.",
	["Tienes %s de %s"] = "Vous avez %s sur %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "Vous avez %s prix issus de vos recherches. Pour tous les connaître, scannez à l'hôtel des ventes.",
	["Tienes 1 misión lista para entregar"] = "Vous avez 1 quête prête à rendre",
	["Tienes 5 puntos de combo y estás en grupo: el sangrado rinde más."] = "Vous avez 5 points de combo et êtes en groupe : le saignement rapporte plus.",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "Vous avez 5 points de combo : le coup de grâce le plus puissant.",
	["Tienes 5 puntos de combo: muerde fuerte."] = "Vous avez 5 points de combo : mordez fort.",
	["Tienes 6 guías abiertas"] = "Vous avez 6 guides ouverts",
	["Tienes activado «Rechazar invitaciones a hermandad» en Ajustes > Comodidades > Social: apágalo para que te llegue la invitación."] = "« Refuser les invitations de guilde » est activé dans Réglages > Confort de jeu > Social : désactivez-le pour recevoir l'invitation.",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "Vous avez des changements non confirmés dans la fenêtre des talents : ils sont annulés avant l'application.",
	["Tienes cambios sin guardar en la ventana de talentos del juego: guárdalos o deshazlos ahí primero"] = "Vous avez des changements non enregistrés dans la fenêtre des talents du jeu : enregistrez-les ou annulez-les d'abord",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "Tu as activé « seulement les quêtes de mon itinéraire » : seules les quêtes de ton itinéraire sont acceptées.",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "Tu as de la rage : utilise-le avant le prochain combat, il te donne, à toi et à ton groupe, plus de puissance d'attaque.",
	["Tienes habilidades nuevas"] = "Tu as de nouvelles compétences",
	["Tienes habilidades sin aprender (%d). Aprenderlas te hace más fuerte."] = "Tu as des techniques non apprises (%d). Les apprendre te rend plus fort.",
	["Tienes la %s, %d versiones atrás."] = "Ta version : %s, avec %d versions de retard.",
	["Tienes la %s."] = "Ta version : %s.",
	["Tienes misiones grises: mira cuáles ya no valen la pena y suéltalas para hacer espacio."] = "Vous avez des quêtes grises : voyez celles qui n'en valent plus la peine et abandonnez-les pour faire de la place.",
	["Tienes más rangos de los que pide tu build."] = "Vous avez plus de rangs que n'en demande votre build.",
	["Tienes puesto «%s». Abre la ventana para afinar cada detalle: distancia, pasto, niebla, agua, cámara, placas y filtros."] = "Vous avez « %s » appliqué. Ouvrez la fenêtre pour affiner chaque détail : distance, herbe, brouillard, eau, caméra, barres de nom et filtres.",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "Vous avez des points hors du plan : Alfa ne les retire pas, il ne fait qu'ajouter.",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "Vous avez six guides ouverts : fermez-en un et réessayez.",
	["Tienes todo %s"] = "%s est au complet",
	["Tienes un hechizo para ir al Claro de la Luna, el santuario de los druidas."] = "Tu as un sort pour te rendre à Reflet-de-Lune, le sanctuaire des druides.",
	["Tienes un punto de talento: %s"] = "Vous avez un point de talent : %s",
	["Tienes una misión de clase"] = "Tu as une quête de classe",
	["Tinte de color"] = "Teinte de couleur",
	["Tipo"] = "Type",
	["Tirion Vadín fue expulsado de la Mano de Plata por defender a Eitrigg, un orco que le salvó la vida. Hoy Eitrigg aconseja a Thrall en Orgrimmar."] = "Tirion Fordring a été chassé de la Main d'argent pour avoir défendu Eitrigg, un orc qui lui avait sauvé la vie. Aujourd'hui, Eitrigg conseille Thrall à Orgrimmar.",
	["Tirion Vadín, el paladín expulsado de la orden, vive solo en una cabaña de estas tierras."] = "Tirion Fordring, le paladin chassé de l'ordre, vit seul dans une cabane sur ces terres.",
	["Toca %s."] = "C'est le moment de %s.",
	["Toca ahora"] = "Maintenant",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "Basculez l'interrupteur pour en ajouter ou en retirer une ; vos choix l'emportent sur le filtre.",
	["Toca una tarjeta para prenderla o apagarla. Las encendidas llevan el borde de color."] = "Touche une carte pour l’activer ou la désactiver. Les activées ont une bordure de couleur.",
	["Toca «Seleccionarlo» otra vez, o usa el botón de raros."] = "Touche « Le cibler » encore une fois, ou utilise le bouton des rares.",
	["Tocando a la puerta de la %s"] = "Tu frappes à la porte de la %s",
	["Toda calidad"] = "Toutes les qualités",
	["Toda fuente"] = "Toute source",
	["Toda la cuenta"] = "Tout le compte",
	["Toda ranura"] = "Tous les emplacements",
	["Todas"] = "Tous",
	["Todas (%d)"] = "Toutes (%d)",
	["Todas las calidades"] = "Toutes les qualités",
	["Todas las guías de profesiones"] = "Tous les guides de métiers",
	["Todas las guías por zona y nivel, con la que Alfa te sugiere para ti."] = "Tous les guides par zone et par niveau, avec celui qu'Alfa te suggère.",
	["Todas las mascotas de compañía: dónde salen, cuánto cuestan y cuáles te faltan."] = "Toutes les mascottes : d'où elles viennent, combien elles coûtent et lesquelles vous manquent.",
	["Todas las mazmorras"] = "Tous les donjons",
	["Todas las metas, notas y pasos de esta guía en otra ventana."] = "Tous les objectifs, notes et étapes de ce guide dans une autre fenêtre.",
	["Todas las misiones"] = "Toutes les quêtes",
	["Todas las misiones de aquí en el mejor orden, con la flecha."] = "Toutes les quêtes d'ici dans le meilleur ordre, avec la flèche.",
	["Todas las misiones de la zona en el mejor orden."] = "Toutes les quêtes de la zone dans le meilleur ordre.",
	["Todas las misiones de tu zona (las que llevas y las que puedes tomar) en el mejor orden, como una guía."] = "Toutes les quêtes de ta zone (celles que tu as et celles que tu peux prendre) dans le meilleur ordre, comme un guide.",
	["Todas las misiones que Lya te guardó, por zona, con su historia completa. También con /alfa historias."] = "Toutes les quêtes que Lya a gardées pour toi, par zone, avec leur histoire complète. Aussi avec /alfa historias.",
	["Todas las monturas: cómo se consigue cada una, qué pide y si ya la tienes."] = "Toutes les montures : comment obtenir chacune, ce qu'elle demande et si vous l'avez déjà.",
	["Todas las profesiones"] = "Tous les métiers",
	["Todas las páginas de Alfa a la vista: mazmorras, talentos, combate, oficios, la manada y más."] = "Toutes les pages d'Alfa à la vue : donjons, talents, combat, métiers, la meute et plus.",
	["Todas las secciones"] = "Toutes les sections",
	["Todas las teclas de Alfa en un lugar"] = "Toutes les touches d'Alfa au même endroit",
	["Todas las teclas de Alfa en un lugar, para cambiarlas ahí mismo. También con /alfa teclas."] = "Toutes les touches d'Alfa au même endroit, pour les changer sur place. Aussi avec /alfa teclas.",
	["Todas las zonas"] = "Toutes les zones",
	["Todas las zonas y razas"] = "Toutes les zones et races",
	["Todavía es pronto"] = "C'est encore tôt",
	["Todavía nada en esta sesión"] = "Rien encore cette session",
	["Todavía no"] = "Pas encore",
	["Todavía no cambias de guarida"] = "Tu n’as pas encore changé de tanière",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "Vous ne connaissez pas encore ses sorts : ils se remplissent à mesure que vous les apprenez.",
	["Todavía no conozco tus recetas"] = "Je ne connais pas encore vos recettes",
	["Todavía no es para ti"] = "Pas encore pour vous",
	["Todavía no escribimos nada en tu historia. ¡Vamos a hacer algo grande!"] = "On n'a encore rien écrit dans ton histoire. Faisons quelque chose de grand !",
	["Todavía no estás en una hermandad. En la página La Jauría ves cómo unirte a la manada."] = "Tu n'es pas encore dans une guilde. La page La Jauría te montre comment rejoindre la meute.",
	["Todavía no has pescado nada en esta sesión"] = "Vous n'avez encore rien pêché cette session",
	["Todavía no hay ayuda de rotación para ti"] = "Pas encore d'aide à la rotation pour vous",
	["Todavía no hay datos de este personaje"] = "Pas encore de données pour ce personnage",
	["Todavía no hay datos para esta gráfica."] = "Pas encore de données pour ce graphique.",
	["Todavía no hay foto de este banco"] = "Pas encore de relevé de cette banque",
	["Todavía no hay guías para tu camino"] = "Pas encore de guides pour ton chemin",
	["Todavía no hay peleas"] = "Pas encore de combats",
	["Todavía no hay progreso"] = "Pas encore de progression",
	["Todavía no hay una pelea anterior"] = "Pas encore de combat précédent",
	["Todavía no hay una pelea que anunciar."] = "Pas encore de combat à annoncer.",
	["Todavía no hay una pelea que resumir."] = "Il n'y a pas encore de combat à résumer.",
	["Todavía no lo pescas"] = "Pas encore pêché",
	["Todavía no lo recolectas"] = "Pas encore récolté",
	["Todavía no lo sacas del agua. Cuando lo hagas, aquí verás cuántos llevas, cuándo y dónde."] = "Vous ne l'avez pas encore sorti de l'eau. Quand ce sera fait, vous verrez ici combien, quand et où.",
	["Todavía no pescas en %s. Lo que saques aquí se anota por zona."] = "Vous n'avez pas encore pêché à %s. Ce que vous attrapez ici est noté par zone.",
	["Todavía no puedes conseguirlo: %s."] = "Vous ne pouvez pas encore l'obtenir : %s.",
	["Todavía no recolectas nada"] = "Vous n'avez encore rien récolté",
	["Todavía no sabes pescar"] = "Vous ne savez pas encore pêcher",
	["Todavía no se puede tomar: Alfa la recoge cuando se abra."] = "Elle ne peut pas encore être prise : Alfa la récupérera dès qu'elle s'ouvrira.",
	["Todavía no sigues ninguna guía. Elige una y Alfa te lleva paso a paso, con la flecha y la ruta."] = "Tu ne suis encore aucun guide. Choisis-en un et Alfa te guide pas à pas, avec la flèche et l'itinéraire.",
	["Todavía no te alcanza."] = "Vous n'avez pas encore assez.",
	["Todavía no tienes escalas propias. Pega una cadena de escala arriba."] = "Tu n'as pas encore d'échelles à toi. Colle une chaîne d'échelle ci-dessus.",
	["Todavía no tienes marcadores"] = "Vous n'avez pas encore de marqueurs",
	["Todavía no tienes rutas propias"] = "Vous n'avez pas encore d'itinéraires à vous",
	["Todavía no tienes talentos para compartir."] = "Vous n'avez pas encore de talents à partager.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "Tu n'as pas encore de guide ouvert. Choisis-en un et Alfa te guide pas à pas : où aller, quoi faire et à qui parler.",
	["Todavía quedan pilones de los titanes en el cráter, y funcionan con cristales de colores."] = "Des pylônes des titans se dressent encore dans le cratère, et ils fonctionnent avec des cristaux de couleur.",
	["Todo"] = "Tout",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "Tout Azeroth sur une seule toile : zoomez avec la molette, faites glisser pour vous déplacer et placez vos marqueurs d'un clic droit.",
	["Todo a la mano"] = "Tout à portée de main",
	["Todo a la vista otra vez"] = "Tout est de nouveau visible",
	["Todo al máximo seguro. Pide una tarjeta de video fuerte."] = "Tout au maximum sûr. Demande une carte graphique puissante.",
	["Todo bien (lo más gastado: %d%%)"] = "Tout va bien (le plus usé : %d%%)",
	["Todo como estaba antes de Alfa"] = "Tout comme avant Alfa",
	["Todo con tu estilo"] = "Tout à ton style",
	["Todo el juego, aunque no lo tengas"] = "Tout le jeu, même ce que vous n'avez pas",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "Tout le jeu, même ce que vous n'avez pas : objets, PNJ, quêtes, zones et rares.",
	["Todo el juego, aunque no lo tengas: objetos, monturas, mascotas, PNJ, misiones, zonas y raros."] = "Tout le jeu, même ce que vous n'avez pas : objets, montures, mascottes, PNJ, quêtes, zones et rares.",
	["Todo el texto de Alfa un poco más grande, en cada ventana. Se suma al tamaño de Ajustes > Apariencia."] = "Tout le texte d'Alfa un peu plus grand, dans chaque fenêtre. S'ajoute à la taille de Réglages > Apparence.",
	["Todo en orden"] = "Tout va bien",
	["Todo en orden: nada choca con Alfa."] = "Tout va bien : rien n'entre en conflit avec Alfa.",
	["Todo esto lo hace Alfa sola al hablar con quien da o recibe una misión. Mantén presionado Mayús para hacerlo tú en el momento."] = "Alfa fait tout cela tout seul quand tu parles à qui donne ou reçoit une quête. Maintiens Maj pour le faire toi-même sur le moment.",
	["Todo junto"] = "Tout ensemble",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "Tout ensemble montre chaque emplacement à sa place ; par catégorie regroupe équipement, consommables, quêtes et matériaux ; par sac place chaque sac dans son bloc.",
	["Todo listo"] = "Tout est prêt",
	["Todo lo de Alfa, explicado por Lya y a un clic"] = "Tout Alfa, expliqué par Lya et à un clic",
	["Todo lo que hay en Alfa"] = "Tout ce qu’il y a dans Alfa",
	["Todo lo que no sea equipo"] = "Tout ce qui n'est pas de l'équipement",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "Tout ce qui est dessiné sur vos cartes, au même endroit. Ce qu'ajoutent les autres modules d'Alfa arrive aussi ici.",
	["Todo nivel"] = "Tous les niveaux",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "Chaque objet, PNJ, quête, zone et rare, avec où l'obtenir et « Me guider ».",
	["Todo oficio"] = "Tous les rôles",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "Tout pour les dégâts : critiques, saignements et Fulgurance très souvent. Vous tuez à toute vitesse, mais sans défense en plus : si beaucoup d'ennemis s'en prennent à vous, fuyez.",
	["Todo subtipo"] = "Tous les sous-types",
	["Todo tipo"] = "Tous les types",
	["Todos"] = "Tous",
	["Todos llegan a %s"] = "Tous mènent à %s",
	["Todos los avisos de Alfa los dice Lya, también los de al entrar y el de hechizos nuevos, con letra más grande que cambias con su clic derecho."] = "Lya dit toutes les alertes d’Alfa, même celles à la connexion et celle des nouveaux sorts, en plus gros texte que tu changes avec un clic droit sur elle.",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "Tous ceux de ce type, ou un seul (par exemple, seulement le cuivre). Entre parenthèses, combien il y en a dans votre zone.",
	["Todos los materiales"] = "Tous les matériaux",
	["Todos los niveles"] = "Tous les niveaux",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Tous les objets, PNJ, quêtes, zones et rares, même ceux que vous n'avez pas : qui le laisse tomber et à quelle fréquence, qui le vend et où, quelle quête le donne et comment y aller.",
	["Todos los objetos, monturas, mascotas, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Tous les objets, montures, mascottes, PNJ, quêtes, zones et rares, même ceux que vous n'avez pas : qui le laisse tomber et avec quelle probabilité, qui le vend et où, quelle quête le donne et comment s'y rendre.",
	["Todos los paladines sueñan con la Crematoria, la espada de Alexandros Mograine."] = "Tous les paladins rêvent du Porte-cendres, l'épée d'Alexandros Mograine.",
	["Todos los pasos"] = "Toutes les étapes",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "Toutes les étapes de ce guide ; cliquez sur l'une d'elles pour la voir.",
	["Todos los pasos de la guía en la ventana de guía."] = "Toutes les étapes du guide, dans la fenêtre du guide.",
	["Todos los que callaste"] = "Tous ceux en sourdine",
	["Todos los tipos"] = "Tous les types",
	["Todos tus personajes"] = "Tous tes personnages",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "Tous vos points sont déjà dépensés, dont une partie hors de ce build. Pour passer à ce build, réinitialisez vos talents auprès de votre maître de classe ; ensuite, Alfa vous les applique en un clic.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "Tous : les alertes mineures aussi. Seulement les graves : uniquement ce qui peut vous tuer.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "Ramasse le butin de pêche tout de suite, même si la fouille automatique du jeu est désactivée.",
	["Toma el dinero y los objetos de tus cartas, una por una. Las de pago contra entrega y las de un MJ se quedan para que las abras tú."] = "Prend l'argent et les objets de tes lettres, une par une. Celles en contre-remboursement et celles d'un MJ restent pour que tu les ouvres toi-même.",
	["Toma las de tu ruta que tienes cerca"] = "Prends les quêtes de ton itinéraire à proximité",
	["Toma las mejores de cerca que ya puedes hacer."] = "Prenez les meilleures quêtes proches que vous pouvez déjà faire.",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "Prenez les meilleures quêtes du coin, puis terminez-les ensemble.",
	["Toma todo el botín de una vez cuando tienes el despojo automático."] = "Prend tout le butin d'un coup quand la fouille automatique est activée.",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "Prenez quelques quêtes proches et Alfa les termine avec vous par le chemin le plus court.",
	["Tomando tus cartas..."] = "Je prends ton courrier...",
	["Tomar %s"] = "Accepter %s",
	["Tomar el vuelo de tu ruta"] = "Prendre le vol de ton itinéraire",
	["Tomar la mejor recompensa"] = "Prendre la meilleure récompense",
	["Tomar todo"] = "Tout prendre",
	["Tomarla"] = "L'accepter",
	["Tomarla, completarla o entregarla."] = "L'accepter, la terminer ou la rendre.",
	["Tomaste otra misión de su grupo: esta ya no se abre."] = "Vous avez pris une autre quête de son groupe : celle-ci ne s'ouvrira plus.",
	["Top %d de %s"] = "Top %d %s",
	["Top de daño"] = "Top des dégâts",
	["Tope por personaje"] = "Plafond par personnage",
	["Torre de zepelines de %s"] = "Tour des zeppelins de %s",
	["Tortura mental: daño constante y frena al enemigo."] = "Fouet mental : dégâts constants et ralentit l'ennemi.",
	["Total"] = "Total",
	["Tramo %d de %d: %s."] = "Tronçon %d sur %d : %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "Pièges, coups au corps à corps d'urgence et beaucoup d'agilité : le chasseur le plus difficile à attraper.",
	["Tranquila, aquí nadie se queda atrás."] = "T'en fais pas, ici personne n'est laissé derrière.",
	["Tranquilo"] = "Prudent",
	["Transformar"] = "Transformer",
	["Transformar %d"] = "Transformer %d",
	["Transmutar hierro en oro existe de verdad: el sueño de todo alquimista."] = "Transmuter du fer en or existe vraiment : le rêve de tout alchimiste.",
	["Tranvía de %s"] = "Tram de %s",
	["Tras aceptar o entregar, cierra la ventana del PNJ si solo ofrece misiones que tu guía no hace."] = "Après avoir accepté ou rendu, ferme la fenêtre du PNJ s'il ne propose que des quêtes que ton guide ne fait pas.",
	["Tras la Guerra de los Tres Martillos, los Martillo Salvaje se fueron a Grim Batol y luego al Interior; los Hierro Negro, a la Montaña Roca Negra."] = "Après la guerre des Trois marteaux, les Marteau-hardi sont partis à Grim Batol puis dans les Hinterlands ; les Sombrefer, au mont Rochenoire.",
	["Tras la Segunda Guerra, mantener a los orcos en los campos de internamiento costaba una fortuna. Esos impuestos ayudaron a romper la Alianza."] = "Après la Deuxième Guerre, garder les orcs dans les camps d'internement coûtait une fortune. Ces impôts ont aidé à briser l'Alliance.",
	["Tras la pelea: quienes curaron"] = "Après le combat : ceux qui ont soigné",
	["Tras las Guerras Trol, el viejo Arathor se repartió en siete reinos: Lordaeron, Ventormenta, Gilneas, Alterac, Stromgarde, Kul Tiras y Dalaran."] = "Après les guerres des Trolls, l'ancien Arathor s'est divisé en sept royaumes : Lordaeron, Hurlevent, Gilnéas, Alterac, Stromgarde, Kul Tiras et Dalaran.",
	["Tratado"] = "Libram",
	["Treinta. La manada habla de ti."] = "Trente. La meute parle de toi.",
	["Tres caminos para cada objeto"] = "Trois options pour chaque objet",
	["Tres estilos y el lobo"] = "Trois styles et le loup",
