	["Tu grupo, tu hermandad y tus amigos en el mapa, con Seguir y la página del clan."] = "Ton groupe, ta guilde et tes amis sur la carte, avec Suivre et la page du clan.",
	["Tu guarida a la vista"] = "Ta tanière en vue",
	["Tu guarida en el rastreador y en el cuadro de los lobos, y Lya te avisa si el juego te cambia de capa."] = "Ta tanière dans le suivi et dans la bulle des loups, et Lya te prévient si le jeu change ta couche.",
	["Tu guarida está abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo."] = "Ta tanière est ouverte : si quelqu’un de la meute demande à entrer, Alfa l’invite dans ton groupe.",
	["Tu guía"] = "Ton guide",
	["Tu guía deja fuera las misiones que ya no dan experiencia, salvo que otra las necesite."] = "Ton guide laisse de côté les quêtes qui ne donnent plus d'expérience, sauf si une autre en a besoin.",
	["Tu guía está lista. Ábrela para ver tu paso."] = "Ton guide est prêt. Ouvre-le pour voir ton étape.",
	["Tu guía puede elegir y avanzar sola, o preguntarte en cada cruce."] = "Ton guide peut choisir et avancer tout seul, ou te demander à chaque embranchement.",
	["Tu guía te lleva a entrenar en %d pasos."] = "Votre guide vous emmène apprendre vos sorts en %d étapes.",
	["Tu guía te lleva a entrenar en este paso."] = "Votre guide vous emmène apprendre vos sorts à cette étape.",
	["Tu guía te lleva a tomarla."] = "Votre guide vous emmène la prendre.",
	["Tu guía terminó y el camino se abre"] = "Votre guide est terminé et le chemin se divise",
