	["Tu hermandad conectada"] = "Ta guilde en ligne",
	["Tu hermandad sabe tu clase y tu nivel, para que te avisen si les sale algo que te sirve."] = "Ta guilde connaît ta classe et ton niveau, pour te prévenir si elle ramasse quelque chose d'utile pour toi.",
	["Tu hermandad se entera cuando llegas al nivel 60, consigues tu primera montura o cazas un raro."] = "Ta guilde l'apprend quand tu atteins le niveau 60, obtiens ta première monture ou chasses un rare.",
	["Tu hermandad y tu grupo reciben los horarios que tomas, y tú los suyos."] = "Ta guilde et ton groupe reçoivent les horaires que tu relèves, et toi les leurs.",
	["Tu hermandad ya sabe tu clase y tu nivel: te avisarán si les sale algo que te sirve."] = "Ta guilde connaît maintenant ta classe et ton niveau : ils te préviendront s'ils trouvent quelque chose pour toi.",
