	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "Votre liste : suivez-les avec la flèche, partagez-les avec le groupe, modifiez-les ou effacez-les.",
	["Tu loba compañera: consejos cortos, ánimo y nunca te deja atrás."] = "Ta louve compagne : de courts conseils, des encouragements, et elle ne te laisse jamais derrière.",
	["Tu loba compañera: te da consejos y ánimo. También con /alfa lya."] = "Ta louve compagne : elle te donne conseils et encouragements. Aussi avec /alfa lya.",
	["Tu lugar resalta más: tu flecha lleva un aro y un pulso suave, y se ve bien hasta en la nieve."] = "Ta position ressort mieux : ta flèche porte un anneau et une pulsation douce, et se voit bien même dans la neige.",
	["Tu manada"] = "Ta meute",
