	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "Vous encaissez les coups et protégez le groupe. Il vous faut un bouclier.",
	["Tú también contestas: si alguien busca algo que llevas, Alfa le dice cuántos tienes (solo eso)."] = "Tu réponds aussi : si quelqu'un cherche un objet que tu portes, Alfa lui dit combien tu en as (rien d'autre).",
	["Ubicación de %s"] = "Position de %s",
	["Ultra"] = "Ultra",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "Une arme dans chaque main et beaucoup de rage : celui qui fait le plus de dégâts en groupe.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Une grande arme à deux mains et des coups qui font saigner. La façon la plus facile de monter.",
	["Un aturdimiento cuando lo necesites."] = "Un étourdissement quand vous en avez besoin.",
	["Un aullido corto cada vez que entregas una misión. Viene apagado."] = "Un court hurlement chaque fois que tu rends une quête. Désactivé par défaut.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "Un hurlement de loup, tiré du jeu, la première fois que tu ouvres Alfa à chaque session.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "Une alerte avec ses boss et ceux que vous avez vaincus, à un clic de leurs conseils.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "Un avis court avec le lieu, sa zone et le temps de trajet.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "Une courte alerte quand une technique qui dépend de ce qui vient de se passer s'active, comme Fulgurance après une esquive de l'ennemi.",
