	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "Une alerte quand vous vainquez un nouveau boss, à un clic de son butin.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "Une alerte et un bandeau dans vos sacs avec quoi vendre, quoi garder et chez quel marchand aller, avec un clic pour marquer la camelote.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "Un balayage sombre et doux sur les icônes pendant leur recharge.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Une bordure de la couleur de la qualité : vert, bleu, violet...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "Une bordure verte qui pulse sur le bouton de votre barre portant la technique suggérée, pour le trouver vite.",
	["Un botón «Alfa» en el menú Esc, como el ícono del minimapa: clic, abre la ventana de Alfa; clic derecho, el menú de Alfa."] = "Un bouton « Alfa » dans le menu Échap, comme l'icône de la minicarte : un clic ouvre la fenêtre d'Alfa ; un clic droit, le menu d'Alfa.",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "Un démoniste avec deux aides peut invoquer le reste du groupe à l'entrée d'un donjon.",
	["Un buzón"] = "Une boîte aux lettres",
	["Un clic bajito cuando Lya te dice algo."] = "Un petit clic discret quand Lya te dit quelque chose.",
	["Un clic te pone el conjunto (fuera de combate; en combate, al terminar). Lo que esté en el banco no se puede poner."] = "Un clic t'équipe l'ensemble (hors combat ; en combat, à la fin). Ce qui est en banque ne peut pas être équipé.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Un clic et il ne reste que l'essentiel : vous, votre groupe, vos marqueurs et la prochaine étape du guide.",
	["Un compañero tiene %s y tú lo puedes quitar, pero ningún clic lo hace. Elige «%s» en Tus clics, en la página Curación."] = "Un compagnon a %s et tu peux le dissiper, mais aucun clic ne le fait. Choisis « %s » dans Tes clics, sur la page Soins.",
	["Un consejo"] = "Un conseil",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Un petit cadre déplaçable avec votre vie et les caractéristiques qui comptent le plus pour votre classe. En combat, le jeu masque certains chiffres : le dernier lisible reste affiché.",
	["Un disparo instantáneo extra. Úsalo mientras corres o para rematar."] = "Un tir instantané en plus. Utilise-le en courant ou pour achever.",
	["Un enemigo"] = "Un ennemi",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "Un bug, une idée ou un commentaire, directement au développeur",
	["Un escudo que absorbe daño. Ponlo antes de que te peguen o en quien tanquea."] = "Un bouclier qui absorbe les dégâts. Mets-le avant d'être frappé, ou sur ton tank.",
	["Un fondo del color de tu clase bajo tu nombre."] = "Un fond de la couleur de ta classe sous ton nom.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Un énorme coup de bouclier et énormément de menace.",
	["Un golpe más para gastar ira."] = "Un coup de plus pour dépenser la rage.",
	["Un golpe nuevo y fuerte para tu barra."] = "Un nouveau coup puissant pour votre barre.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Un gros bonus de dégâts pour les monstres difficiles ; il vous libère aussi de la peur.",
	["Un grano fino de cine sobre el mundo."] = "Un fin grain de cinéma sur le monde.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "Un grain fin, comme au cinéma. Ne coûte presque rien : il bouge environ 14 fois par seconde et seulement quand il est visible.",
	["Un hechizo de tus barras tiene un rango viejo"] = "Un sort de vos barres est d'un ancien rang",
	["Un lobo de La Jauría anda cerca"] = "Un loup de La Jauría est dans le coin",
	["Un lobo de nivel %d te quiere echar la mano: ve tu nivel, tu zona y tu misión, solo él. Acepta aquí o en La Jauría."] = "Un loup de niveau %d veut te donner un coup de patte : lui seul voit ton niveau, ta zone et ta quête. Accepte ici ou dans La Jauría.",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "Une carte d'un seul tenant : en zoomant, on ne voit plus de morceaux collés, et le terrain se raccorde sans lignes ni carrés.",
	["Un mapa impecable"] = "Une carte impeccable",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Un cadre doré sur ce qui sert à une quête (avec « ! » si l'objet en commence une).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "Un objet que vous voulez : Alfa crée le chemin pour l'obtenir, avec tout ce qu'il faut avant.",
	["Un paisaje más bonito"] = "Un plus beau paysage",
	["Un paseíto y unas palabras. Así también se hace manada."] = "Une petite balade et quelques mots. C'est aussi comme ça qu'on fait une meute.",
	["Un pescadito asado no me caería nada mal."] = "Un petit poisson grillé ne me ferait pas de mal.",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "Un petit poisson grillé pour la louve qui t'accompagne, ce ne serait pas de refus, hein ?",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Un petit repère numéroté là où vous mènent les prochaines étapes.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Un peu de coup critique, d'esquive et d'armure.",
	["Un poco de vida de vuelta después de críticos."] = "Un peu de vie récupérée après les critiques.",
	["Un poco más de defensa."] = "Un peu plus de défense.",
	["Un poco más de ira al cargar."] = "Un peu plus de rage en chargeant.",
	["Un punto azul abajo a la derecha si a ese compañero le falta el buff de tu clase. Se revisa fuera de combate."] = "Un point bleu en bas à droite si ce compagnon n'a pas l'amélioration de ta classe. Vérifié hors combat.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Un point pour ouvrir la rangée suivante et rater un peu moins.",
	["Un raro vuelve más o menos entre media hora y una hora después de caer. Aquí ves hace cuánto lo cazaron tú o la manada."] = "Un rare revient environ entre une demi-heure et une heure après sa mort. Ici, tu vois depuis combien de temps toi ou la meute l'avez tué.",
	["Un raro: %s"] = "Un rare : %s",
	["Un rayo que salta entre varios enemigos."] = "Un éclair qui rebondit entre plusieurs ennemis.",
	["Un reto de Lya para esta semana."] = "Un défi de Lya pour cette semaine.",
	["Un rincón de %s que todavía no pisas."] = "Un coin de %s où tu n'es pas encore allé.",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "Un service proche, un marqueur de votre carte, l'endroit où vous êtes ou l'entrée d'un donjon.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Un point d'exclamation au-dessus de ceux qui donnent des quêtes de votre niveau.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Un point d'interrogation au-dessus de ceux qui attendent une quête terminée.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "Un seul addon avec tout ce que tu utilises en jouant : guides pas à pas avec flèche et itinéraire, carte, sacs, builds, soins en un clic, récolte, donjons, pêche et commerce. Le tout dans le même style.",
	["Un solo aviso: el de tus bolsas, que también te dice qué vender."] = "Un seul avertissement : celui de vos sacs, qui vous dit aussi quoi vendre.",
	["Un solo día de precios: el historial crece con cada escaneo o búsqueda."] = "Un seul jour de prix : l'historique grandit à chaque scan ou recherche.",
	["Un solo menú de Alfa: el ícono del minimapa, la lista de addons y el botón Alfa del menú Esc abren lo mismo."] = "Un seul menu d'Alfa : l'icône de la minicarte, la liste des addons et le bouton Alfa du menu Échap ouvrent la même chose.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Un tank qui frappe fort : beaucoup de menace pour les groupes qui font beaucoup de dégâts, en échange de moins de défense en plus. Pour les tanks qui ont un peu d'expérience.",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "Un tronçon de plus dans l'itinéraire que vous créez sur la page Itinéraire : Alfa choisit le chemin pour l'obtenir.",
	["Un tótem que atrae los golpes de los enemigos. Te da un respiro."] = "Un totem qui attire les coups des ennemis. Il te laisse souffler.",
	["Un tótem que cura poco a poco a tu grupo."] = "Un totem qui soigne peu à peu ton groupe.",
	["Un tótem que hace lentos a los enemigos cercanos. Para escapar o pelear con ventaja."] = "Un totem qui ralentit les ennemis proches. Pour fuir ou combattre avec l'avantage.",
	["Un tótem que le dispara fuego al enemigo. Ponlo al empezar."] = "Un totem qui tire du feu sur l'ennemi. Pose-le au début.",
	["Un tótem que quita el miedo, el sueño y el encanto a tu grupo."] = "Un totem qui retire la peur, le sommeil et le charme de ton groupe.",
	["Un tótem que reduce el daño que recibes cuerpo a cuerpo."] = "Un totem qui réduit les dégâts de mêlée que tu subis.",
	["Un zarpazo fuerte en forma de oso. Genera mucha amenaza."] = "Un coup de griffe puissant en forme d'ours. Génère beaucoup de menace.",
	["Un «?» en cada página de Alfa para que Lya te la explique, y su propia tecla."] = "Un « ? » sur chaque page d’Alfa pour que Lya te l’explique, et sa propre touche.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "Une icône avec la technique la plus utile maintenant. Elle ne fait que montrer : elle n'appuie jamais à votre place.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "Une icône de quête sur la barre de nom des ennemis et personnages dont vous avez encore besoin pour une quête de votre journal. Dans les donjons, le jeu masque ces données et ils ne sont pas marqués.",
	["Un'Goro de día: dinosaurios por todas partes. Yo me quedo atrás de ti, ¿va?"] = "Un'Goro de jour : des dinosaures partout. Je reste derrière toi, d'accord ?",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "Une grande action recommandée, et ton chemin en quelques clics.",
	["Una barra bajo el buzón para tomar el dinero y los objetos de tus cartas con un clic, y lo que recibiste al final."] = "Une barre sous la boîte aux lettres pour prendre l'argent et les objets de tes lettres en un clic, et ce que tu as reçu à la fin.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Une barre avec les attaques que le boss va lancer et le temps restant avant chacune. Vous savez ainsi quand bouger ou vous défendre.",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "Un nouvel accueil en 9 étapes avec l'intro du loup : tu choisis la langue d'Alfa (il y en a 10) et tout ce qu'il fait seul pour toi.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "Une ligne de texte contient un build complet : vous la copiez, la transmettez et ils la collent.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "Une somme d'or ; c'est rempli quand vous l'avez sur vous.",
	["Una carta con objetos vence pronto"] = "Une lettre avec des objets expire bientôt",
	["Una categoría…"] = "Une catégorie…",
	["Una cuenta de prueba no puede compartir"] = "Un compte d'essai ne peut pas partager",
	["Una curación muy rápida pero cara. Para emergencias."] = "Un soin très rapide mais coûteux. Pour les urgences.",
	["Una curación más fuerte. Para cuando la vida baja mucho."] = "Un soin plus puissant. Pour quand la vie baisse beaucoup.",
	["Una curación que salta entre tus compañeros heridos."] = "Un soin qui rebondit entre tes compagnons blessés.",
	["Una curación rápida y barata. Perfecta para mantener a todos de pie."] = "Un soin rapide et économique. Parfait pour garder tout le monde debout.",
	["Una curación rápida. Para cuando no hay tiempo."] = "Un soin rapide. Pour quand le temps manque.",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "Une rangée avec vol, auberge, réparation, banque, boîte aux lettres et votre maître, à un clic.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "Une flèche à l'écran qui pointe vers ton prochain objectif, avec la distance. Désactivée : tu choisis ton chemin.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "Une flèche verte sur chaque objet de tes sacs qui est une amélioration pour ta spécialisation.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Une flèche verte sur l'équipement meilleur que celui que vous portez, selon votre classe et votre niveau.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Une bande vert clair montre les soins déjà en route.",
	["Una gran curación para todo el grupo mientras canalizas."] = "Un gros soin pour tout le groupe pendant que tu canalises.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "Un guide pour votre niveau et votre zone, ou votre propre itinéraire de quêtes.",
	["Una hora de caza"] = "Une heure de chasse",
	["Una hora de caza, aviso de cadena, «Deshacer» al omitir y cuánto te falta de tu guía."] = "Une heure de chasse, alerte de chaîne, « Annuler » après avoir sauté une étape et ce qu’il reste de ton guide.",
	["Una huella sobre la mejor para tu clase (o la que más vale al venderla) y «Alfa te recomienda». Nunca elige por ti."] = "Une empreinte sur la meilleure pour ta classe (ou celle qui se vend le plus cher) et « Alfa te recommande ». Alfa ne choisit jamais à ta place.",
	["Una lista de las grises que ya no valen la pena, con «Abandonar» en cada una (tú lo confirmas)."] = "Une liste des quêtes grises qui n'en valent plus la peine, avec « Abandonner » sur chacune (c'est toi qui confirmes).",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "Une louve dodue comme moi a besoin de ses trois repas... et de ses grignotages.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "Une louve noire qui te donne conseils et encouragements en route, sans gêner. En mémoire d'une merveilleuse petite chienne.",
	["Una loba que cuida tan bien a su lobo merece una salchicha, ¿no crees?"] = "Une louve qui veille si bien sur son loup mérite une saucisse, tu ne crois pas ?",
	["Una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla. En grupo la ve todo el grupo, con o sin Alfa; solo, sale en tu chat. Nunca en banda."] = "Une ligne avec le lien de la quête quand tu remplis ses objectifs, une autre quand elle est prête à rendre et une autre quand tu la rends. En groupe, tout le groupe la voit, avec ou sans Alfa ; seul, elle s’affiche dans ton chat. Jamais en raid.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "Une courte ligne sous l'icône, comme « Frappe mortelle : recharge prête ». Chacune s'affiche jusqu'à 4 fois puis se tait ; son × la fait taire plus tôt.",
	["Una línea debajo del aviso con lo que pasó."] = "Une ligne sous l'alerte avec ce qui s'est passé.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "Une ligne rouge en haut prévient quand un ennemi s'en prend à ce membre.",
	["Una mano"] = "Une main",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "Un objectif que vous cochez vous-même (le bouton fait du suivi ou de cette liste).",
	["Una misión"] = "Une quête",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "Une pièce sur les objets gris et ce que vous avez marqué comme camelote.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "Un avis avec le maître le plus proche quand tu as de nouvelles techniques.",
	["Una piedra de salud para emergencias. Haz una antes de cada mazmorra."] = "Une pierre de soins pour les urgences. Fais-en une avant chaque donjon.",
	["Una piedra que deja revivir al morir. Pónsela a quien cura."] = "Une pierre qui permet de revenir après la mort. Donne-la à ton soigneur.",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "Une révision complète de tous les modules : plus de 60 corrections.",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "Une révision complète pour la version stable : plus de 20 corrections en donjon de groupe, en combat, sur la carte, la pêche, les talents et plus.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "Un itinéraire est votre arbre de tronçons : quêtes d'XP, d'or ou de classe, matériaux ou objets. Choisissez-en un pour commencer :",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "Un itinéraire demande au moins 3 lieux à la portée de votre compétence. Choisissez un autre type ou une autre ressource plus bas, ou récoltez ici : Alfa note chaque nœud que vous trouvez.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "Un itinéraire par les meilleurs lieux pour votre compétence, avec quelques quêtes d'XP entre-temps.",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "Une saucisse par jour rend la louve heureuse. C'est scientifique.",
	["Una semana de caza juntos"] = "Une semaine de chasse ensemble",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "Une session se termine après 20 minutes sans lancer ou quand vous en commencez une autre ; elle apparaît alors ici avec vos prises et l'endroit.",
	["Una sesión tranquila: nada nuevo que contar."] = "Une session tranquille : rien de neuf à signaler.",
	["Una sola voz: Hoy, las bolsas y Lya ya no repiten lo mismo."] = "Une seule voix : Aujourd'hui, tes sacs et Lya ne répètent plus la même chose.",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "Une touche pour tout : équipement, appât, lancer et remonter. Avec journal, guide, cuisine, objectifs et statistiques.",
	["Una tormenta de hielo en un área. Ideal contra grupos."] = "Une tempête de glace sur une zone. Idéal contre les groupes.",
	["Una vuelta de recolección en tu zona"] = "Une tournée de récolte dans ta zone",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "Relie les %d lieux à la portée de votre compétence en une boucle courte, la trace sur la carte, et la flèche vous mène d'étape en étape.",
	["Unir las capas de sombra"] = "Fondre les couches d'ombre",
	["Unirte al grupo de tus amigos"] = "Rejoindre le groupe de tes amis",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "L'un des dragons verts du cauchemar apparaît dans le bois de la Pénombre, près d'un grand arbre.",
	["Uno menos"] = "Un de moins",
	["Uno más"] = "Un de plus",
	["Unos %d pasos a tu ritmo"] = "Environ %d étapes à ton rythme",
	["Unos %s de juego a tu ritmo (%s XP por hora)."] = "Environ %s de jeu à ton rythme (%s XP par heure).",
	["Unos materiales: %s."] = "Environ ces composants : %s.",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "Quelques hauts-elfes restent avec l'Alliance ; ils vivent à Quel'Danil, dans les Hinterlands.",
	["Unos prefieren que yo haga lo aburrido y otros quieren hacerlo todo. Tú dime, y si cambias de idea, lo cambias cuando quieras."] = "Certains préfèrent que je fasse le plus ennuyeux, d’autres veulent tout faire. Dis-moi, et si tu changes d’avis, tu le changes quand tu veux.",
	["Usa %s"] = "Utilisez %s",
	["Usa %s: tu tecla lo pone."] = "Utilisez %s : votre touche l'applique.",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "Utilisez Maîtrise du blocage quand un boss frappe fort.",
	["Usa Deseo de muerte al empezar contra un jefe."] = "Utilisez Death Wish au début d'un combat de boss.",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "Utilisez Death Wish contre les monstres difficiles, pas contre les faciles.",
	["Usa Golpe mortal sobre todo contra sanadores."] = "Utilisez Frappe mortelle surtout contre les soigneurs.",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "Utilisez Attaques circulaires quand il y a deux ennemis ou plus ensemble.",
	["Usa Ira rabiosa para romper miedos."] = "Utilisez Rage berserker pour briser les peurs.",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "Utilisez Vengeance chaque fois qu'elle s'illumine et Fracasser armure pour ajouter de la menace.",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "Utilisez Connexion pour récupérer du mana en échange de vie.",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "Utilisez votre démon pour retenir le monstre pendant que vous lancez vos sorts.",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "Utilisez le Jugement et remettez votre sceau tout de suite.",
	["Usa el número de abajo en lugar del que detecta el juego."] = "Utilise le nombre ci-dessous au lieu de celui que détecte le jeu.",
	["Usa el número de abajo para el blanco normal."] = "Utilise le nombre ci-dessous pour le blanc normal.",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "Utilise la surbrillance du jeu sur le bouton de la technique suggérée.",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "Utilisez la forme de félin contre un monstre et la forme d'ours s'il en vient plusieurs.",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "Utilisez votre coup principal pour accumuler des points de combo et dépensez-les dans votre coup de grâce.",
	["Usa tu piedra de hogar"] = "Utilise ta pierre de foyer",
	["Usa tu piedra de hogar: te lleva a tu posada."] = "Utilise ta pierre de foyer : elle t'emmène à ton auberge.",
	["Usa tu varita cuando quieras ahorrar maná."] = "Utilisez votre baguette quand vous voulez économiser du mana.",
