	["¡%d misiones entregadas hoy! Así se caza en manada."] = "%d quêtes rendues aujourd'hui ! C'est comme ça que chasse la meute.",
	["¡%d misiones hoy! A este paso me debes una salchicha."] = "%d quêtes aujourd’hui ! À ce rythme, tu me dois une saucisse.",
	["¡%d misiones hoy! Estás que no te para nadie."] = "%d quêtes aujourd'hui ! Rien ne t'arrête.",
	["¡%s al máximo: %d/%d! Ya no hay nada que te enseñen. Qué orgullo, de verdad."] = "%s au maximum : %d/%d ! Plus personne n'a rien à t'apprendre. Quelle fierté, vraiment.",
	["¡%s cazó a %s!"] = "%s a chassé %s !",
	["¡%s es tu aprendiz!"] = "%s est ton apprenti !",
