	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s a atteint le niveau %d ! Ahouuu, félicitations.",
	["¡%s tiene su primera montura!"] = "%s a sa première monture !",
	["¡%s ya está feliz! Así sí da gusto cazar juntos."] = "%s est content maintenant ! Là, ça fait plaisir de chasser ensemble.",
	["¡%s!"] = "%s !",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s ! Ça fait des jours que je ne t'avais pas vu. Dans Aujourd'hui, je te dis où on en était.",
	["¡%s! Si algo te pega, corre hacia el tanque, no lejos de él."] = "%s ! Si quelque chose te frappe, cours vers le tank, pas loin de lui.",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s ! Tu m'as tellement manqué. J'ai accouru dès ton arrivée.",
	["¡%s, listo! La manada aúlla por ti. Auuuu. ¿Y mi salchicha?"] = "%s, c'est fait ! La meute hurle pour toi. Aouuuu. Et ma saucisse ?",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s, tu es de retour ! Tu m'as tellement manqué que je n'arrêtais pas de remuer la queue.",
	["¡Abrumar!"] = "Fulgurance !",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "Maintenant je te cours après en tirant la langue !",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "Te voilà, %s ! Si tu veux un conseil, clique sur moi.",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "Ah, te voilà, %s ! Je t'attendais… tu m'as manqué.",
	["¡Al máximo!"] = "Au maximum !",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "Debout, loup ! Avant de reprendre le combat, récupère vie et mana.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "Debout, loup ! Tomber fait partie de la chasse. Une fois revenu, répare ton équipement.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "Debout, loup ! Libère ton esprit : la flèche te dit s'il vaut mieux rejoindre ton corps ou l'esprit guérisseur.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "Debout, loup ! S'ils étaient trop nombreux, la prochaine fois attire-les un par un.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "Debout, niveau %d ! Si tu as un point de talent libre, ne l'oublie pas.",
	["¡Así se ve un aviso!"] = "Voici à quoi ressemble une alerte !",
	["¡Ataque de la victoria!"] = "Ivresse de la victoire !",
	["¡Auuu! Juntas cazamos mejor."] = "Aouuu ! Ensemble, on chasse mieux.",
	["¡Auuu! Toda la manada está de fiesta."] = "Aouuu ! Toute la meute fait la fête.",
	["¡Auuuu! La manada unida no se rinde."] = "Aouuuu ! Une meute unie n'abandonne jamais.",
	["¡Auuuu! ¡Nivel %d y dos niveles en menos de media hora! Vas como lobo en luna llena."] = "Ahouuu ! Niveau %d, et deux niveaux en moins d'une demi-heure ! Tu es comme un loup à la pleine lune.",
	["¡Bien hecho! %s"] = "Bien joué ! %s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "Bonjour, %s ! Le soleil s'est levé sur Azeroth. On y va ?",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "Bonsoir, %s ! Nous, les louves, chassons mieux la nuit.",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "Bon après-midi, %s ! C'est le bon moment pour quelques quêtes.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "Salut, %s ! Pas à pas, on va loin.",
	["¡Buenos días! Un buen desayuno y a cazar, que la mañana rinde."] = "Bonjour ! Un bon petit-déjeuner et en chasse, le matin rapporte.",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "Bonjour, %s ! Je m'étire, je bâille et je suis prête.",
	["¡Bájale, casi se lo quitas al tanque!"] = "Doucement, tu vas la prendre au tank !",
	["¡Claro! Saludo a tu mascota cuando la llamas y, si eres cazador, te aviso cuando tiene hambre o está triste para que le des de comer."] = "Bien sûr ! Je salue ton familier quand tu l'appelles et, si tu es chasseur, je te préviens quand il a faim ou n'est pas content pour que tu le nourrisses.",
	["¡Completaste %s!"] = "Vous avez terminé %s !",
	["¡Contraataque!"] = "Contre-attaque !",
	["¡Cumplido! Salchicha ganada."] = "Réussi ! Saucisse gagnée.",
	["¡Córtale a tu foco!"] = "Interromps ta focalisation !",
	["¡Córtalo!"] = "Interromps-le !",
	["¡De vuelta con la manada!"] = "De retour avec la meute !",
	["¡De vuelta en la manada, %s!"] = "De retour dans la meute, %s !",
	["¡Ejecutar!"] = "Exécution !",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "On vend du boudin à Thelsamar ! Le boudin de Thelsamar, c'est presque une saucisse... tu m'en achètes un ?",
	["¡Es Halloween de Azeroth! Pide dulces a los posaderos: a veces te disfrazan de algo chistoso."] = "C'est la Sanssaint ! Demande des friandises aux aubergistes : parfois ils te déguisent de façon rigolote.",
	["¡Es ahora! Hasta las %s"] = "C'est maintenant ! Jusqu'à %s",
	["¡Es el Festival del Fuego del Solsticio! Visita las hogueras de las ciudades y honra su llama."] = "C'est la fête du Feu du solstice d'été ! Visite les feux des villes et honore leur flamme.",
	["¡Espera! Dejas %d misiones listas sin entregar. Si no, mañana empezamos por ahí."] = "Attends ! Tu laisses %d quêtes terminées sans les rendre. Sinon, la prochaine fois, on commence par là.",
	["¡Esto le sirve a %s!"] = "Ça peut servir à %s !",
	["¡Está lanzando!"] = "Il incante !",
	["¡Explorada completa!"] = "Entièrement explorée !",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "Bravo pour le niveau %d, %s ! Ahouuu.",
	["¡Feliz cumpleaños!"] = "Joyeux anniversaire !",
	["¡Feliz cumpleaños, Alfa!"] = "Joyeux anniversaire, Alfa !",
	["¡Gracias! Ya van %d salchichas que me das. Las llevo contadas, eh."] = "Merci ! Ça fait %d saucisses que tu me donnes. Je les compte, hein.",
	["¡Hasta pronto! Aquí te espero, cuidando tu lugar."] = "À bientôt ! Je t'attends ici, je te garde ta place.",
	["¡Hasta pronto! Hoy cazamos %s Aquí te espero."] = "À bientôt ! Aujourd'hui, on a chassé : %s Je t'attends ici.",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "Il y a du nouveau dans Alfa : %s ! Je te montre ?",
	["¡Hola!"] = "Bonjour !",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "Salut ! Demande-moi ce que tu veux sur Alfa : je t’explique en bref et je t’y emmène.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "Salut ! Je suis Lya, la louve de confiance de l'Alfa. Je veille sur la meute et je fais la route avec toi.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "Salut ! Je suis Lya, la louve de confiance de l’Alpha. Je t’accompagne dans cette configuration, puis sur ton chemin.",
	["¡Hola, %s!"] = "Bonjour, %s !",
	["¡Hola, %s! Familia %s y de buena casta. Tú y yo vamos a cuidar a nuestro alfa."] = "Salut, %s ! De la famille %s, et de bonne lignée. Toi et moi, on va veiller sur notre alpha.",
	["¡Hola, %s! Hoy huele a buena cacería."] = "Bonjour, %s ! Aujourd'hui, ça sent la bonne chasse.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "Salut, %s ! L'après-midi s'annonce calme. On chasse quoi aujourd'hui ?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "Salut, %s ! Une nuit de lune : parfaite pour la meute.",
	["¡Hola, %s! Tú y yo vamos a cuidar a nuestro alfa."] = "Salut, %s ! Toi et moi, on va veiller sur notre alpha.",
	["¡Hoy Alfa cumple %d años! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Aujourd'hui, Alfa fête ses %d ans ! La Jauría l'a fait avec amour pour toi. On fête ça avec une saucisse ?",
	["¡Hoy Alfa cumple 1 año! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Aujourd'hui, Alfa a 1 an ! La Jauría l'a fait avec amour pour toi. On fête ça avec une saucisse ?",
	["¡Hoy cumplimos %d años cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Aujourd'hui, ça fait %d ans qu'on chasse ensemble, %s ! Merci de me laisser être ta louve. Aouuuu.",
	["¡Hoy cumplimos 1 año cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Aujourd'hui, ça fait 1 an qu'on chasse ensemble, %s ! Merci de me laisser être ta louve. Aouuuu.",
	["¡La Lya de %s me contestó el saludo! Ya somos manada."] = "La Lya de %s m'a rendu mon salut ! On est une meute maintenant.",
	["¡La Lya de %s me saludó! Entre lobas nos entendemos."] = "La Lya de %s m'a saluée ! Entre louves, on se comprend.",
	["¡Le encantan! Pero las mías son más ricas."] = "Il adore ça ! Mais les miennes sont meilleures.",
	["¡Listo! %s precios guardados."] = "Terminé ! %s prix enregistrés.",
	["¡Listo! Alfa ya es tuyo"] = "C'est prêt ! Alfa est à toi",
	["¡Llegó el Festival de Invierno! En Forjaz y Orgrimmar el árbol se llena de luces y regalos."] = "Le Voile d'hiver est là ! À Forgefer et Orgrimmar, l'arbre se remplit de lumières et de cadeaux.",
	["¡Lo lograste: %s! Esa salchicha de premio me la voy a comer despacito."] = "Tu l'as fait : %s ! Cette saucisse de récompense, je vais la manger tout doucement.",
	["¡Lo tienes! %s ×%d"] = "Attrapé ! %s ×%d",
	["¡Martillo de cólera!"] = "Marteau de courroux !",
	["¡Mi primera salchicha contigo! Esta no la voy a olvidar nunca."] = "Ma première saucisse avec toi ! Celle-là, je ne l'oublierai jamais.",
	["¡Misión completada: %s!"] = "Quête terminée : %s !",
	["¡Mmm, qué rica! Gracias, eres el mejor lobo de la manada."] = "Mmm, délicieux ! Merci, tu es le meilleur loup de la meute.",
	["¡Mordedura de mangosta!"] = "Morsure de la mangouste !",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "Niveau %d ! Prends un moment pour t'en vanter, tu l'as mérité.",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "Niveau %d ! Pas assuré et crocs affûtés.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "Niveau %d ! Tes efforts se voient. Continue comme ça.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "Niveau %d ! Aouuu ! C'est comme ça qu'on monte en meute.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "Niveau %d, bien joué ! Vois si ton maître a du nouveau.",
	["¡Nivel %d, y el anterior hace nada! Aúllo dos veces, una por cada uno. ¡Auuuu, auuuu!"] = "Niveau %d, et le précédent, c'était à l'instant ! Je hurle deux fois, une pour chacun. Ahouuu, ahouuu !",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "Niveau 10 ! Tu as des talents : choisis-les tranquillement, Talents t'aide.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "Niveau 20 ! Tu peux faire de vrais donjons. On monte un groupe ?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "Niveau 30 ! Tu es à mi-chemin. Quelle fierté pour la meute !",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "Niveau 40 ! Tu peux apprendre la monte. Ta première monture t'attend !",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "Niveau 50 ! On sent déjà le sommet. Réunis de l'or pour la suite.",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "Niveau 60 ! Tu as réussi, alpha ! Place à la grande chasse.",
	["¡Nueva página en tu historia: %s! %s"] = "Nouvelle page dans ton histoire : %s ! %s",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "Nouveau record : %d quêtes en un jour ! Même la meute ne te suit pas.",
	["¡Ojo! Tu precio está %d %% por debajo de lo que vale."] = "Attention ! Ton prix est %d %% en dessous de sa valeur.",
	["¡Otro nivel tan pronto! Nivel %d. ¡Auuuu, esta racha no la para nadie!"] = "Encore un niveau, déjà ! Niveau %d. Ahouuu, personne n'arrête cette série !",
	["¡Perdiste su atención!"] = "Tu as perdu son attention !",
	["¡Plan cumplido!"] = "Plan accompli !",
	["¡Plan terminado!"] = "Plan terminé !",
	["¡Primera vez! Nuevo en tu diario"] = "Première fois ! Nouveau dans votre journal",
	["¡Qué buena racha traes! Sigue así."] = "Quelle belle série ! Continue comme ça.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "Ça fait plaisir de te revoir, %s ! Je suis toujours là, à surveiller tes arrières.",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "Quel plaisir de te revoir ! Voici ce que cette version apporte pour toi et ta meute.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "Quel plaisir de te voir, %s ! La meute t'attendait.",
	["¡Repara tu equipo!"] = "Répare ton équipement !",
	["¡Reto cumplido: %s! Me gané una salchicha... digo, te la ganaste tú. Bueno, nos la ganamos."] = "Défi réussi : %s ! J'ai gagné une saucisse... enfin, c'est toi qui l'as gagnée. Bon, nous deux.",
	["¡Revancha!"] = "Vengeance !",
	["¡Salchicha! *mueve la cola a toda velocidad* Gracias, gracias."] = "Saucisse ! *remue la queue à toute vitesse* Merci, merci.",
	["¡Salimos de %s! %s adentro."] = "On est sortis de %s ! %s à l'intérieur.",
	["¡Salimos de la mazmorra! %s adentro."] = "On est sortis du donjon ! %s à l'intérieur.",
	["¡Sesenta! Lo lograste. Me debes una salchicha gigante."] = "Soixante ! Tu l'as fait. Tu me dois une saucisse géante.",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "Tu es passé niveau %d ! Chaque niveau te rend plus fort.",
	["¡Sí, acompáñame!"] = "Oui, accompagne-moi !",
	["¡Te está atacando a ti!"] = "Il t'attaque, toi !",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "Tu m'as manqué, %s ! J'ai couru jusqu'ici pour te voir.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "Tu m'as manqué, %s ! Ton itinéraire reprend là où tu l'as laissé.",
	["¡Terminaste %s!"] = "Vous avez terminé %s !",
	["¡Terminaste esta guía!"] = "Tu as terminé ce guide !",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "Tu as terminé ce guide ! Choisis le suivant et continue à monter avec la meute.",
	["¡Terminaste tu guía!"] = "Tu as terminé ton guide !",
	["¡Tienes todo!"] = "Tu as tout !",
	["¡Tierra a la vista! La manada desembarca en %s"] = "Terre en vue ! La meute débarque à %s",
